WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[66465] = { title = "Cache and Release", description = "Even with their leader gone, the Tarasek are unlikely to stop using their poison-tipped spears simply because we ask them nicely. I cannot risk even one of these weapons being used on an unsuspecting traveler.\n\nThey will all need to be destroyed. If you did not see any in the caches by the pools, then the Embertooth are likely keeping their spears closer to the source. \n\nNo one else will get hurt because of my carelessness. Enter the cave and destroy any weapon caches that you find.", objectives = "" }
WordHunterWoW_QuestEN[66466] = { title = "The Essence of Fury", description = "Journal entry: 9\n\nI swear I better not get stuck with these two as my assistants again, they can barely pull this wagon! We're supposed to arrive at pools of supposedly enchanted waters, where water congeals into swirling essence that seems to have attracted a swarm of elementals.\n\nIf we can examine samples of this congealing essence before it becomes completely concentrated we might be able to figure out how to stop the elementals from drawing power here. IF WE EVER ARRIVE!", objectives = "" }
WordHunterWoW_QuestEN[66467] = { title = "Art Imitates Life", description = "The last time I was in this cave, I sketched a massive flower that dripped a vile, viscous sap. It's one of my best drawings, I couldn't forget it if I tried.\n\nThat sap is what's stuck to these tarasek spears, I'm sure of it. They must have started harvesting it to envenom their weapons.\n\nThe plant is beautiful; it will be a shame to kill it. Still, we can't let the tarasek keep harvesting it. {name}, please cull the plant and put a stop to this whole mess.", objectives = "" }
WordHunterWoW_QuestEN[66468] = { title = "What Once Was Ours", description = "<Thadezus scoffs at your approach.>\n\nAre you a mortal of action, or are you going to get out of our way, {class}?\n\nI have lost many good soldiers to those Primalists up ahead.\n\nWe have an idea of what they are planning, but we must first rout the enemy and rescue those serving under me.", objectives = "" }
WordHunterWoW_QuestEN[66470] = { title = "The Forward Push", description = "<Sharnax scratches her chin.>\n\nThe commander was right. The Primalists are calling reinforcements from the elemental planes.\n\n<Sharnax smirks.>\n\nIt would be a shame if something happened to their gateways, {class}.", objectives = "" }
WordHunterWoW_QuestEN[66471] = { title = "Prime Planning", description = "The commander ordered me to establish a forward base and dispatch any resistance. It wasn't until I did all the dispatching that I realized something.\n\n<Sharnax lets out a long sigh.>\n\nThe Primalists were talking about Tyrhold.\n\nUnless you are exceptionally skilled at interrogation, I need you to discover their plans.", objectives = "" }
WordHunterWoW_QuestEN[66472] = { title = "Primal List", description = "The gateways closed, the elementals slain, and the Primalists stopped... for now.\n\n<Sharnax laughs.>\n\nIs there anything we cannot do, {class}? I guess only time will tell.\n\nTake the plans back to the commander. I am certain he will be glad to see we have been successful.", objectives = "" }
WordHunterWoW_QuestEN[66473] = { title = "The Land Awakens", description = "The fiends in this cave were too much for me.\n\n<Sharnax lets out a labored cough.>\n\nI have seen what you can do.\n\nI need you to slay these elementals before they reach their full potential. We cannot allow the Primalists to take control of Tyrhold!", objectives = "" }
WordHunterWoW_QuestEN[66474] = { title = "The Other Scouts", description = "Journal entry: 10\n\nIdiots! Shortsmith and Stockson took off as soon as we arrived, their enthusiasm will be their death! We were sent here to study the elementals not play hide and seek.\n\nHow am I supposed to study these elementals without a decent distra... assistants?", objectives = "" }
WordHunterWoW_QuestEN[66477] = { title = "The Pond and the Fury", description = "Journal entry: 15\n\nThese waters are swarming with elementals drawing power from the swirling essences that gather here naturally. As much as I would love to see where this leads, the elementals pose a significant threat to the Expedition and get in my way of studying the source of this pools magic.\n\nIf only we could thin out their numbers but my two overly enthusiastic assistants have decided to get themselves trapped! How am I supposed to do everything on my own!", objectives = "" }
WordHunterWoW_QuestEN[66482] = { title = "Scout for Trophies: Terramaw", description = "[PH] Get rid of that annoying flying lizard!", objectives = "" }
WordHunterWoW_QuestEN[66484] = { title = "Know Your Enemy: Proto-Dragons", description = "The area is crawling with those powerful beasts! Conveniently. the Surveying Scope has allowed you to spot a few weak spot in their tough scale. You can also devise a few tricks to avoid their sharp claws and fangs.", objectives = "" }
WordHunterWoW_QuestEN[66488] = { title = "WANTED: Frigellus", description = "<The page's script glows with a soft blue light.>\n\nPreviously a cherished plaything of Malygos, the elemental Frigellus suffered from his master's neglect. \n\nWhile this once-happy settlement crumbled apace, the churlish and playful creature grew warped and twisted by the evils that plague this land.\n\nPlease see that it is safely neutralized.\n\nBring word of your success to Custodian Cynegos.", objectives = "" }
WordHunterWoW_QuestEN[66489] = { title = "Setting the Defense", description = "Custodian Cynegos and I were just discussing the impact the Primalist attack has had on the plans to assault the Cobalt Assembly, and I had an idea. \n\n<Celeste withdraws a wand from the folds of her robes.>\n\nTake my wand and empower their weapons!\n\nA little bit of fire should do the trick...", objectives = "" }
WordHunterWoW_QuestEN[66493] = { title = "Send It!", description = "<You hear muffled muttering coming from the other end of the portal.>\n\nHey! Hey you! \n\nI have some mail for our apprentices in the field: care packages, gifts, things they've ordered via magical courier... \n\nStandard fare, really.\n\nMind doing me a favor and handing them out?", objectives = "" }
WordHunterWoW_QuestEN[66500] = { title = "Ways of Seeing", description = "We're not doing anything! We're not doing anything!\n\nHang on a minute...\n\nYou look like a pretty important {race}... Want in on a secret?\n\nTurns out there's magical art in these ruins. And we can see it!\n\n<Scrumpy proudly sticks out his chest.>\n\nI can show you how to see 'em too! Just... don't tell Noriko yet.", objectives = "" }
WordHunterWoW_QuestEN[66503] = { title = "For The Love of Others", description = "Ah, I see my apprentices have roped you into their little games. \n\n<Noriko chuckles.>\n\nIt appears they--and you--have stumbled onto something. The purpose behind these ruins is slowly revealing itself to us, and there's more than faded images and song...\n\nSomething calls out from atop this tower.\n\nI see the intrigue in your eyes. Go. You have my permission. \n\nSee what you can see.", objectives = "" }
WordHunterWoW_QuestEN[66504] = { title = "A Shard of Crystalized Mana", description = "<The small blue crystal vibrates lightly when touched, then produces a low tune that sounds like a distant song. You can hear the words echoing like a soft melody in your head.>\n\nLathos may find it interesting.", objectives = "" }
WordHunterWoW_QuestEN[66507] = { title = "A Winter Veil Gift", description = "", objectives = "" }
WordHunterWoW_QuestEN[66508] = { title = "A Gently Shaken Gift", description = "", objectives = "" }
WordHunterWoW_QuestEN[66509] = { title = "Paranoid 1", description = "Agura sent me out here to pick FLOWERS for my ANXIETY but there are CREATURES and I'm terrified.", objectives = "" }
WordHunterWoW_QuestEN[66510] = { title = "Paranoid 2", description = "Getting out here was so scary. Now I have to go BACK? Please come with me.", objectives = "" }
WordHunterWoW_QuestEN[66513] = { title = "Ground Leave", description = "Perhaps we should get an idea of this city, if it is to be our new home. A scouting mission, if you will.\n\nGo, see what this place has to offer. I will follow Wrathion and attempt to help in any way I can.\n\nTry not to upset the locals any more than you must, though. I doubt many of them are used to seeing dragons walk among them.\n\nMeet up with us once you've gotten the lay of the land.", objectives = "" }
WordHunterWoW_QuestEN[66516] = { title = "Mundane Gems, I Think Not!", description = "It's such a waste. The djaradin of this land use powerful gems as mundane decorations. Mere jewelry! Gems have so many uses: telescopes, mirrors, focusing pointers, not to mention the myriad magical properties they possess.\n\nWe must rectify this situation, explorer. Relieve the djaradin of their gems, and bring them back to me. I'll make sure they're put to better use! Be careful though--the djaradin are fierce warriors.", objectives = "" }
WordHunterWoW_QuestEN[66517] = { title = "A New Source of Weapons", description = "These Sundered Flame pose a great threat to our borders. Their weapons are concerning. Gather what you can of their weapons--we can study them for any weaknesses, and even use them for our own defenses.\n\nI have faith in you, outsider. If you perform this task for us, I will teach you some of our own blacksmithing arts.", objectives = "" }
WordHunterWoW_QuestEN[66523] = { title = "Tending the Forge", description = "If you're looking for an instructor, I'm sorry to say I... Ah, you're not an apprentice! My apologies. Allow me to introduce myself. \n\nI am Custodian Vernagos, one of the caretakers of these ruins. More specifically, the task of restoring this workspace to its former glory has fallen upon my very tired shoulders. \n\nWould you be able to lend a hand? All the reagents I need are nearby: ice elemental cores, embercones, hornswog leather...\n\nFairly standard, easily gathered stuff. What say you?", objectives = "" }
WordHunterWoW_QuestEN[66524] = { title = "Amateur Protography", description = "So, you want to be a seasoned cataloger like me? You've come to the right place! \n\nThe Wild Preserve is teeming with knowledge waiting to be found and filed! And how do I do that you ask? Why, with my handy Catalog-izer 3000 Dragon Isles edition--now with improved motion capture!\n\nTo gain experience, photograph a proto-dragon egg, a whelp learning to fly, and a hunting proto-drake. Meet me at the ancient, proto-dragon skeleton west of here, and I'll assess your photos.", objectives = "" }
WordHunterWoW_QuestEN[66525] = { title = "Competitive Protography", description = "Well, now that you've cut your teeth on some starter shots, how about we move onto something a little spicier?\n\nI spotted a gorgeous proto-drake flying around the area behind us. Beautiful horns, scales crackling with electricity... Probably the work of the Primalists, no doubt, but art is art!\n\nSee if you can get a picture of the proto-drake and some of its eggs. You might have to climb up a bit to get a good shot!", objectives = "" }
WordHunterWoW_QuestEN[66526] = { title = "Preserving the Wilds", description = "The Wild Preserve is one of the few areas where proto-dragons thrive. But the Primalists are disrupting their nesting grounds by sending sorties to capture and experiment on proto-whelps and proto-drakes.\n\nShow them no mercy. Locate these Primalist poachers, wipe them out, and free their captives. The proto-dragon species depends on it.", objectives = "" }
WordHunterWoW_QuestEN[66527] = { title = "Professional Protography", description = "I haven't trained a photographer as good as you... that's still alive, that is. It's a dangerous profession.\n\nSpeaking of dangerous, our final target is a large proto-dragon we believe may be one of the next apex predators in this preserve. Let's get up close and personal and take a picture!", objectives = "" }
WordHunterWoW_QuestEN[66528] = { title = "King Without a Crown", description = "This ancient proto-dragon must have been a glorious creature when it was alive--perhaps the largest the Wild Preserve has ever seen.\n\nBut it wasn't enough. Observe the skeleton more closely, so we may learn the story of its final moments.", objectives = "" }
WordHunterWoW_QuestEN[66529] = { title = "A Thousand Words", description = "With all that we've learned here, I can't imagine moving on without a memento. \n\nWould you be kind enough to take my picture next to the proto-dragon fossils?", objectives = "" }
WordHunterWoW_QuestEN[66534] = { title = "Ground Leave", description = "It seems like our arrival was noticed after all. Maybe there's hope for these people yet.\n\nI'll follow up with Ebyssian and the Horde leadership and try to smooth this out. You're on recon.\n\nSee what this place has to offer. We may be here for a while, after all.\n\nCome find us once you're finished. Hopefully we'll have all the boring bits sorted out by then.", objectives = "" }
WordHunterWoW_QuestEN[66546] = { title = "Retrieve the Discs", description = "The discs in here represent the sum of this facility's knowledge. We need to retrieve them!\n\nI'll bring the barrier down with this console. It'll be on ye to retrieve the discs.", objectives = "" }
WordHunterWoW_QuestEN[66547] = { title = "It Belongs in a Museum... Eventually", description = "Waves of titan security, escaped proto-dragons, keys that turn you into constructs... I'll just say it.\n\nI've never had so much fun in my LIFE!\n\nAlthough Naleidea will probably say this is where the real fun begins. We're sitting on a trove of confidential titan data, thanks to the effort ye put in!\n \nWhen ye can, come meet us at camp and we'll compare notes.", objectives = "" }
WordHunterWoW_QuestEN[66549] = { title = "Waking Shores Rally", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[66553] = { title = "Hollow Up", description = "The Winterpelt are a special case among the furbolgs. \n\nI'd categorize 'em as a wee bit \"isolationist.\" They are ghosts in the hollow, their pelts blendin' in with tha snow. \n\nUsedta keep to themselves, but now they're outright aggressive. They attacked our camp with nae provocation!\n\nSomethin' must be wrong to drive 'em to it. I can't ask 'em what happened--yet--but maybe ye can find some clues in their village?", objectives = "" }
WordHunterWoW_QuestEN[66554] = { title = "Aggressive Self-Defense", description = "With the Winterpelt all in a tizzy, I don't imagine they'll appreciate ya poking around up there. \n\nDon't be afraid to defend yourself if they start somethin'. A firm reminder that ya mean business might knock some sense back into 'em.\n\nTry not to kill anyone though, will ya? I know how ya adventurin' types can get.", objectives = "" }
WordHunterWoW_QuestEN[66555] = { title = "Bear With Me", description = "Aye, sounds like a right mess up there--like a storm blew through and wrecked the whole place. I can see why they'd be up in arms, but why attack us?\n\nThis would be a lot easier if we could just talk it out, but the Winterpelt are famously tight-lipped and don't seem to speak any of the common branches of Furbolg-ish. Furbolgian? Eh, ye know what I mean.\n\nI don't suppose ya happened to have a nice chat with any of 'em while ye were checking in on them, did ye?", objectives = "" }
WordHunterWoW_QuestEN[66556] = { title = "Ice Cave Ya Got There", description = "Well, yer accent is atrocious, and ten-thousand years o' isolation an' linguistic drift hasn't done us any favors, but I think I got a rough impression at least.\n\nThe common thread in what they were tryin' to say was somethin' aboot a \"bad cave wind\" or an \"evil storm cave.\" That, or their laundry was too Thursday?\n\nLook, this isn't like learnin' Gnomish; there're goin' to be some hiccups. I'm pretty sure aboot the cave though, so let's start there.", objectives = "" }
WordHunterWoW_QuestEN[66557] = { title = "Academic Acquaintances", description = "Aye, this Winterpelt variation on furbolg is provin' to be a tough nut to crack even for me.\n\nI've got some colleagues down in Camp Nowhere who might be able to help. I hear there are other furbolg tribes in the area, and comparin' notes on those dialects might give us somethin' to go off of.", objectives = "" }
WordHunterWoW_QuestEN[66558] = { title = "Rowie", description = "You were the one that came back with the others from Brackenhide, weren't you? Then you probably know what happened to Kaqiata...\n\nHer son, Rowie, has been distraught ever since Brena and the others returned without her. I'll stay here in case he comes back, but could you look for him? \n\nI think he ran off towards the ice cave to the east. He said something about trying to fight the yeti in there!", objectives = "" }
WordHunterWoW_QuestEN[66559] = { title = "Back To Camp", description = "I saw Mordigan run out of there like a dwarf possessed. I'll go chase him down and make sure he gets back to the others in one piece.\n\nIf you hug the cliff and jump down the waterfalls, you should be able to avoid stirring up any more of the gorlocs. \n\nSee you back at camp.", objectives = "" }
WordHunterWoW_QuestEN[66575] = { title = "Item as Questgiver: Vial", description = "<This strange vial nestled amongst the odds and ends of the Tarasek stash seems to be filled with a viscous, bubbling fluid.>\n\n< It would be wise to show this to Alvi.>", objectives = "" }
WordHunterWoW_QuestEN[66577] = { title = "Aspectral Invitation", description = "Ah, {name}. Impeccable timing!\n\nI just met with Lord Commander Turalyon and his allies, and they have accepted the Aspects' invitation to the Dragon Isles. \n\nYou will be coming along, of course? It wouldn't be the same without you!\n\nI imagine you have noticed some unfamiliar faces gathered here. The ones with the wings are called dracthyr. They have only known me a short time, but they are already great admirers.\n\nAh, but where are my manners? We should have a chat.", objectives = "" }
WordHunterWoW_QuestEN[66579] = { title = "Sounds of Healing", description = "<You hear a soothing sound emanating from the disc as it hums softly.\n\nOlea Manu might know more about this.>", objectives = "" }
WordHunterWoW_QuestEN[66582] = { title = "Power Procurement", description = "In normal circumstances, the capture of energy is not problematic. However, the energy we require is massive and unstable. This enchanted vessel should provide a safe means of transport.\n\nThere is a region to the southwest filled with energy-laden creatures. The anomalous energy within these creatures is powerful, but unstable.\n\nCapture their energy and return it to me. Then we may embark on the remainder of this journey together.", objectives = "" }
WordHunterWoW_QuestEN[66584] = { title = "Additional Waygate Energy", description = "", objectives = "" }
WordHunterWoW_QuestEN[66586] = { title = "Legacy of Tyr: Secrets of the Past", description = "To stop Raszageth from freeing the other Incarnates, the Aspects' power must be restored.\n\nBut this will not be an easy task. The Titans are silent and Keeper Tyr is long dead.\n\nQueen Alexstrasza has devised a plan. In the Badlands lies a Titan facility called Uldaman. She believes Tyr's companions hid a disc of his memories inside its depths.\n \nTake your allies to Uldaman and find the disc for the Dragon Queen. Let us hope Tyr's knowledge can be used to re-empower the Aspects.", objectives = "" }
WordHunterWoW_QuestEN[66589] = { title = "Expeditionary Coordination", description = "The name's Toddy. I'll be headin' up our band of cheery adventurers under the banner of the Dragonscale Expedition. We'll get into the details later. For now, let's focus on gatherin' up our crew.\n\nEvery expedition worth its salt has a variety of folk. We'll be needin' scholars, artisans, and of course explorers.\n\nWell? What're you standin' here for? Assemble that crew!", objectives = "" }
WordHunterWoW_QuestEN[66595] = { title = "Dormant Discovery", description = "<Nevermind how this curious parchment ended up in your bags. What's important are the contents of the message.>\n\nMembers of the Dragonscale Expedition:\n\nYour assistance is required! Report to the Rubyscale Outpost at once!\n\n<Before the signature can be read, the magical lettering inscribed on the note dissipates into a cloud of white and blue-tinted dust, leaving behind an empty page and a deliciously flowery scent in the air.>", objectives = "" }
WordHunterWoW_QuestEN[66596] = { title = "Whispers on the Winds", description = "Hello, {name}. It's been a while, and I wish we had more time to catch up.\n\nBut you see, I've just had a rather enlightening... no, make that foreboding... yes, a foreboding conversation with an old friend.\n\nSometimes a revelation can be both, after all.\n\nI really must tell you of what I've learned.", objectives = "" }
WordHunterWoW_QuestEN[66597] = { title = "This Old Stone", description = "This stone behind me is just one piece of, what do ye call it--ancient technology--we stumbled upon here in the Isles.\n\nBut, we're not entirely sure what they are just yet. Baffling, really.\n\nWe've sent word to some friends to see if they can help. In the meantime, perhaps ye can figure out how tae use it?", objectives = "" }
WordHunterWoW_QuestEN[66598] = { title = "Nightborne Know-How", description = "Ancient symbols aren't really me thing. However...\n\n<Thaelin searches through his belongings, eventually pulling out a map. At the top of the parchment appears the name Antonidas, scribbled in large, sloppy letters.>\n\nAh hah! Here it is!\n\nBit of a trek, but a few of those old magic users can be found... here. \n\n<Pointing to a spot on the map.>\n\nMaybe they have somethin' tae offer.", objectives = "" }
WordHunterWoW_QuestEN[66611] = { title = "Clearing the Skies", description = "Can you hear that? Bugs! All around. Some of them are getting pretty big.\n\nWhy don't you and your gliding friend use the thermal behind me and do something about it?", objectives = "" }
WordHunterWoW_QuestEN[66612] = { title = "Crabtender's Quandry", description = "The crabs are in danger!\n\nThis particular bunch has been through a rough season. Their previous habitat was ransacked by the Primalists, and then I led them to this area only for gorlocs to invade!\n\nI thought they would be safe here, but the gorlocs only nurture aggression in their crabs, leading them to an early demise!\n\nPlease, defeat some of the gorlocs so the crabs can escape!", objectives = "" }
WordHunterWoW_QuestEN[66622] = { title = "Wayward Tools", description = "This is terrible! My *hic* tools seem to have run off when I wasn't looking. I can't *hic* stand the thought of them all alone out there, no doubt scared out of their minds!\n\nWould you round them up for me? Just be patient and *hic* try to soothe their nerves and I'm sure they'll warm right up to you!", objectives = "" }
WordHunterWoW_QuestEN[66633] = { title = "Make a Statement", description = "These djaradin believe the black dragonflight is finished. They don't fear or respect Wrathion's authority here.\n\nWe need a statement to remind them that the obsidian flight has returned, and that we are stronger than ever.\n\nSlay the djaradin and mark each corpse so they don't forget who rules here.", objectives = "" }
WordHunterWoW_QuestEN[66635] = { title = "Reunited, Once Again", description = "That should be enough. I can sense the others just on the outside of the grove, ready to enter the Dream.\n\nWhen you're ready, speak to me and I will break the ice walls and bring down the dome. I hope that my changes will not dishearten the flight. \n\nWe will not be done, but we will be all together again.", objectives = "" }
WordHunterWoW_QuestEN[66636] = { title = "The Other Side", description = "We've finally figured out the placement of the third stone--and ye get to do the honors! I've affixed the stone to what's left of the watcher's staff. Just climb the scaffolding there, hold it up, and watch the show!", objectives = "" }
WordHunterWoW_QuestEN[66646] = { title = "Quelling Causalities", description = "The Infinite has forced the energies of time to aggression. This is not good.\n\nPlease slay any time elementals you encounter while assisting Ambassador Chronormu. I will remain here and help her hold Eternus in place.", objectives = "" }
WordHunterWoW_QuestEN[66647] = { title = "Elemental Unfocus", description = "Kalecgos and I are under heavy fire in the skies above the mountain. The Primalists are unrelenting and their army endless.\n\nSoon, Kalecgos and I may be overrun by their forces.\n\nBut I have a plan.\n\nAt the base of the mountain is a disturbed orc named Ruvin Stonegrinder. The Kirin Tor fought her numerous times.\n\nShe holds a device that can absorb and redirect elemental energies. \n\nTake it from her, then meet me further in.", objectives = "" }
WordHunterWoW_QuestEN[66648] = { title = "Crossing Fate", description = "<Reality spins around you. Your memories of this place become obscured, and shift intensely with each passing moment. Something has changed.>\n\n<You are certain that for all its similarities, this is not the place you once knew. Not exactly.>\n\n<Regardless, the path ahead beckons. Neither deception nor distortion will delay your destiny.>", objectives = "" }
WordHunterWoW_QuestEN[66649] = { title = "Turning the Wheel", description = "<Through your many trials you feel the power inside you growing. Whatever the source of these anomalies, they now bring you comfort instead of confusion.>\n\n<Dive once more into uncertainty, strive against the darkness, and grasp Fate with both hands.>", objectives = "" }
WordHunterWoW_QuestEN[66650] = { title = "Fate's Finale", description = "<You are calm. The nature of this experience remains unknown, but it is no longer unfamiliar. Your now possess mastery over these ordeals with clarity as your ultimate reward.>\n\n<With clear mind and steady hand you stride forth one last time. Create your own destiny, and watch it unfold under your very feet.>", objectives = "" }
WordHunterWoW_QuestEN[66651] = { title = "Up to No-khud", description = "The Nokhud and Ukhel clans have overtaken the Eternal Kurgans. Their purpose can only be malign. Our most esteemed ancestors are buried there.\n\nI sent Initiate Zorig to investigate. He still has not returned.\n\nHe is capable, but lacking in confidence. Please help him put a stop to their foul activities!", objectives = "" }
WordHunterWoW_QuestEN[66652] = { title = "Return to Mender", description = "I can't see what they're doing from here, but I fear they're desecrating the kurgans.\n\nPlease go to the nearest tomb, and see if you can stop the ritual they're performing. \n\nAnd if you find anything that may tell us their purpose here, please bring it back to me.", objectives = "" }
WordHunterWoW_QuestEN[66654] = { title = "Desecrator Annihilator", description = "My mother was a hero. She deserves peace and rest, not this... enslavement! None of our heroes do.\n\nThey must pay for this. And our ancestors must rest once more with their weapons, with honor. Take the weapons back from those desecrators!", objectives = "" }
WordHunterWoW_QuestEN[66655] = { title = "Reagents of De-Necromancy", description = "I fear the spirits will be unable to find their tombs, even if we release them from the Ukhel's grip.\n\nThe Ukhel are also raising the ancestors' animal companions who guided and protected them in life.\n\nBring me the skulls of those animals, and the sacred soil disturbed by these enemies. Combined, these reagents should help the ancestors find peace.", objectives = "" }
WordHunterWoW_QuestEN[66656] = { title = "Definitely Eternal Slumber", description = "The ancestors are gripped by this dark magic. They will fight before they follow. The Ukhel raised our fiercest warriors and hunters. Stopping them will be no easy task.\n\nI'm going to come along and help. It's time I put my mother's spear back to use.\n\nOnce they are defeated, use this totem I've crafted to help the subdued spirits find their way back to the kurgans.", objectives = "" }
WordHunterWoW_QuestEN[66657] = { title = "And Stay Dead!", description = "Tombcaller Arban has holed up in the largest kurgan, where the first Maruuk ancestors were laid to rest. Stop Arban before he raises Maruuk and Teera!", objectives = "" }
WordHunterWoW_QuestEN[66658] = { title = "The Nokhud Offensive: Founders Keepers", description = "Teera and Maruuk's weapons were removed before we stopped Tombcaller Arban. Our greatest ancestors may fight again in these plains... for the Nokhud.\n\nGo to the Nokhud Offensive. Find Maruuk and Teera. When you have subdued them, bring their weapons back to the Teerakai burial mound. We will lay them back to rest with the honor they deserve, in a place we can protect more easily.", objectives = "" }
WordHunterWoW_QuestEN[66660] = { title = "On Your Mark... Get Set...", description = "<Nozdormu's gaze is unfocused.>\n\nThe further they fall, the faster they travel. They punch holes through the fabric of time which send out great ripples. You will need to be swift to catch them.\n\n<Nozdormu's focus sharpens and shifts to you.>\n\nI will send my timewalkers to help you navigate the timeways and speed your efforts. Avoid entangling with the temporal locals and do not stop until you have found Chronormu!\n\nGo. We have precious little time.", objectives = "" }
WordHunterWoW_QuestEN[66661] = { title = "It's Just a Coin, What Could it Cost?", description = "<This curious object provides more questions than answers. How did you come to have it? What is it used for? Is it dangerous?>\n\n<If the Eternal City does not hold answers for you, then surely the Brokers who trade there will.>", objectives = "" }
WordHunterWoW_QuestEN[66671] = { title = "Path to Nowhere", description = "Ye look like a willin' and able adventurer! How would ye like to help out the Dragonscale Expedition?\n\nWe've got ourselves a lovely camp in the middle of a nice bit of wilderness.\n\nThere's plenty for ye to do if ye'd like to take the trip over there. \n\nTalk to me sis, Maddy, when ye get there. She'll get ye all settled in.", objectives = "" }
WordHunterWoW_QuestEN[66673] = { title = "Speak to Koranos", description = "The Watchers have observed much over the years. Many of them are lost to the vagaries of time, but we still have Koranos.", objectives = "" }
WordHunterWoW_QuestEN[66675] = { title = "Aspect Power", description = "The Mother Oathstone is an ancient gift bestowed to our flights by the Titans. If what we have learned is true, I might be able to reactivate it and in doing so restore our aspectral powers.\n\nThough we are unsure of the outcome, if this has the slightest chance of working I must attempt it.\n\n{name}, I would appreciate if you would join me in this.", objectives = "" }
WordHunterWoW_QuestEN[66676] = { title = "Sneaking In", description = "This is Lizi... she's my secret friend. I've been taking care of her since she was rejected by her mother.\n\nThis isn't looking good. Whatever they did to her is beyond my knowledge. I have to bring her home. My Ohn may ground me for the rest of time, but Lizi must get help. I am ever grateful to you, {name}. I'm sorry this was more trouble than you signed up for.\n\nIf you wouldn't mind one more adventure... please face my Ohn's wrath with me? Meet me back at the springs.", objectives = "" }
WordHunterWoW_QuestEN[66679] = { title = "Ruby Lifeshrine Loop", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[66680] = { title = "Counting Sheep", description = "How frustrating. A rabid stag did this while my brother Olekk and I were scouting.\n\n<Watu gestures at his bloody leg and winces.>\n\nAre you here to help? After the primalists attacked, our herd of argali scattered into the pines. Their wool and milk are essential to the camp's functions.\n\nTake this whistle, which commands Wish to herd the argali back home. Sondo the butcher has her favorite treats if she needs extra encouragement.", objectives = "" }
WordHunterWoW_QuestEN[66681] = { title = "Tempests Abound", description = "If you're venturing out into the pines, please slay any stormtouched animals. This is not easy for me to ask, but they're clearly in pain, unable to be helped, and spreading the aggression.\n\nI suspect it's the primalists' doing. It must be coming from their outpost nearby, where I saw a strange magical altar at work.\n\nI'm going to go investigate again. If I'm not back by the time you return, Scout Watu can brief you on additional tasks. We're grateful for any help.", objectives = "" }
WordHunterWoW_QuestEN[66683] = { title = "Last Resort Analysis", description = "<Watu mumbles to himself, eyes closed and arms crossed.>\n\nOf course I get gored by a stag, of all creatures. Now I'm just another one who needs help. My brother will get all the credit, and no one back home will be surprised.\n\n<Watu looks up.> What? What's that you've got there? Glowing rocks? I'll look at one, but take the rest to somebody else. I'm a hunter, not an archaeologist. <Watu snorts, glaring at his leg.> Maybe this is a sign for me to switch jobs. Go on, you've proven more useful than I.", objectives = "" }
WordHunterWoW_QuestEN[66684] = { title = "Storm Chasing", description = "<Watu rips the shard out and gasps for air.>\n\nI...completely lost control. Olekk was right. This terrible magic has to be the primalists' doing. Please, stop them!\n\nI must get my brother back to camp.", objectives = "" }
WordHunterWoW_QuestEN[66687] = { title = "Land of the Apex", description = "You should know of Rellen, the Learned, who gave centaur the tools to survive a merciless land. His memory requires offerings from worthy beasts.\n\nTake care, traveler. They are not as dangerous as they were eons past, but they're still the plains' apex predators.", objectives = "" }
WordHunterWoW_QuestEN[66688] = { title = "Signs of the Wind", description = "When the elements, true primals of the world, challenged the centaur, Himia met them with our given gift. The wind.\n\nA singing stone stands strong in the plains. There, you can offer tokens of the wind to evoke her memory. Such tokens may be found all around us--a bird's feather, a plant spore, a river's reeds.", objectives = "" }
WordHunterWoW_QuestEN[66689] = { title = "More Than A Rock", description = "<The shards are smooth and slightly hot to the touch. Lightning sparks deep within their core.>\n\n<Maybe Watu or Olekk would know more.>\n\n<The thought of parting with the shard fills you with compulsion to hold the shard close. To keep it forever.>", objectives = "" }
WordHunterWoW_QuestEN[66690] = { title = "The Nokhud Offensive: The Final Ancestor", description = "You've proven yourself an ally to us, with genuine interest in our values and way of life. There is one more ancestor I'd like to tell you about, but it will be dangerous.\n\nKill the traitorous Balakar, leader of Nokhud, son of none. He wears a precious medallion at all times. Bring it back to me, and I will be forever in your debt.", objectives = "" }
WordHunterWoW_QuestEN[66691] = { title = "Waking Shores - Race 01 - Intermediate", description = "This course has a similar layout to the previous, just with more variance in the checkpoint placement.\n\nIf you get stuck, blow the whistle and I'll reset you.", objectives = "" }
WordHunterWoW_QuestEN[66692] = { title = "Ruby Lifeshrine Loop - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[66698] = { title = "Counting Argali", description = "One of our key resources is our argali herd. Every loss is felt deeply for the strength of our clan.\n\nA few of the argali have gotten separated and have wandered away from the herd. Our shepherds could use your assistance reclaiming them.", objectives = "" }
WordHunterWoW_QuestEN[66699] = { title = "Ask the Locals", description = "Kalecgos is wise to seek the tuskarr's counsel. They have generations of experience with this land.\n\nMany are resting here on their way to their various camps across the Span. \n\nAsk around! One of them must know about local ley lines.", objectives = "" }
WordHunterWoW_QuestEN[66700] = { title = "The Black Locus", description = "It really is quite enticing, isn't it? The Locus was too much for the Sundered Flame. However, it fits just right in my hands. Funny, that.\n\n<Adenedal shakes his head.>\n\nPerhaps not. Not this day. Not again. Take it from me. It is not my burden to bear.\n\nGood bye, dear friend.", objectives = "" }
WordHunterWoW_QuestEN[66703] = { title = "Snowball Effect", description = "Snowhide gnolls smart. They know you put food on ice, food is good longer. But just ice no good. Magic ice be better! \n\nThis be the work of shamans. And they put Frostbite here, so he starve to death next to delicious tuskarr meat.\n\nIf {race} want help tuskarrs, time running out. \n\nBut Frostbite knows how to break the spell.\n\nWhy Frostbite help? He no like shamans either.", objectives = "" }
WordHunterWoW_QuestEN[66704] = { title = "Mugurlglrlgl!", description = "Mrglgulglrrlglgul! Grurguglullgurl!\n\nGruglrlgllrugl rrgulgrulgrgl grugll gurgull gur. Murgllgllrugl gurgllglrl Murgul gruggullgl. Murguglegurgllgur gurgll gurgulgul guruulgurllgr guuglrllgl.\n\nMgrgulllglll gurl gugll.\n\n<You aren't certain what's being said, but there are lots of stabbing motions. It seems like this murloc wants you to kill something.>", objectives = "" }
WordHunterWoW_QuestEN[66706] = { title = "[DNT]QuestNameHere", description = "", objectives = "" }
WordHunterWoW_QuestEN[66708] = { title = "Riders in the Snow", description = "Greetings, {class}. This magical dome is truly astonishing, is it not? But even though it protects us from the biting cold and the wilderness, we cannot count on the Kirin Tor forever.\n\nA few days ago, some of our most seasoned hunters ventured into the forests looking for food and supplies, but they never came back. Even though I know their leader, Old Grimtusk, is a seasoned hiker and hunter, it is very hard not to worry about him and his hunting party.\n\nCan you find them for me?", objectives = "" }
WordHunterWoW_QuestEN[66709] = { title = "Field Medic 101", description = "<It's hard to say how long this wounded tuskarr has been lying here alone in the forest, but he won't last much longer without help.>", objectives = "" }
WordHunterWoW_QuestEN[66710] = { title = "Flashfrost Flyover", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[66711] = { title = "Delicacy in the Dark", description = "Due to the nature of our clan, some resources are in short supply. We do not have the luxury of time to claim the land's metal resources.\n\nThe late khan established multiple trade connections with a variety of individuals, and I see no reason to discontinue their services.\n\nThe nearby bay contains buckets where we catch whelks - they're considered a delicacy for some of our neighbors. Bring a collection back to me for use in trade.", objectives = "" }
WordHunterWoW_QuestEN[66712] = { title = "Flashfrost Flyover - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[66713] = { title = "[DNT]QuestNameHere", description = "", objectives = "" }
WordHunterWoW_QuestEN[66714] = { title = "[DNT]QuestNameHere", description = "", objectives = "" }
WordHunterWoW_QuestEN[66715] = { title = "The Extraction", description = "Right now the most important thing is to bring back my people. Preferably in one piece.\n\nAnd as much as it pains me to say this, I'm in no condition to fight them on my own. \n\nWill you help us?", objectives = "" }
WordHunterWoW_QuestEN[66719] = { title = "One Step Backwards", description = "My friend, it is with great sorrow that I must say that I am familiar with the plight facing your kind in these ruins. If you proceed any further, you too will surely succumb to their madness.\n\nBe it through your nurture or your nature, the call you hear is a physiological one. You have a craving that must be sated.\n\nIt brings me great shame to say that I possess the means to feed this malediction. It will not quite be the same, but you will be able to function... For now.", objectives = "" }
WordHunterWoW_QuestEN[66721] = { title = "Wild Preserve Slalom", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[66722] = { title = "Wild Preserve Slalom - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[66724] = { title = "The Gleamfisher", description = "I am sorry you have been dragged into this, traveler. \n\nMy brother tends to get... carried away. This is only the latest of his follies. But this one might get him killed. \n\nHe won't listen to me. He probably won't listen to you, either. \n\nOur ancestor, Kauriq the Gleamfisher, though, is the center of his fixation. She may be able to.\n\nPlease catch some Gleamfish and bring them here. I shall use them to help us commune with her spirit, which lingers in this stone.", objectives = "" }
WordHunterWoW_QuestEN[66725] = { title = "Wild Preserve Circuit", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[66726] = { title = "Wild Preserve Circuit - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[66727] = { title = "Emberflow Flight", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[66728] = { title = "Emberflow Flight - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[66729] = { title = "Conditionals", description = "I don't like the alliance. Remember me? \n\nGo kill Mawsworn.", objectives = "" }
WordHunterWoW_QuestEN[66730] = { title = "True Survivors", description = "I know we're pretty banged up, but we can't forget why we're here. Our people are counting on us, and I don't plan on letting them down. We've got to find a temporary place for ourselves in these savage parts, and I know just the place.\n\nNow quit whining and MOVE IT.", objectives = "" }
WordHunterWoW_QuestEN[66732] = { title = "Apex Canopy River Run", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[66733] = { title = "Apex Canopy River Run - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[66734] = { title = "Leave Bee Alone", description = "Oh, thank the Life-Binder! Someone with empty hands!\n\nThese gardens are normally a lovely playground for our whelps, but the bees have multiplied uncontrollably. The blooms returned with vigor--and so have the bees. The whelps are terrified, the dragons are annoyed, and just yesterday one was stung and--\n\n<Vaeros takes a deep breath to center himself then looks at you pleadingly.>\n\nWill you please gather up the bees and relocate them to the lake? Take this smoke diffuser; it will calm them down.", objectives = "" }
WordHunterWoW_QuestEN[66735] = { title = "Just a Trim", description = "The bees scaring the whelps is not the only problem. While pollination is usually a good thing, the recent swarm has caused the flora to grow out of control.\n\nWould you mind taking my gardening shears and cutting back the shrubs? Some have already begun to sprout dangerous lashers, but I hope we can stop more from doing so. An ounce of prevention is worth a pound of cure, after all.\n\nAnd I could... very much use some prevention right now, {name}.", objectives = "" }
WordHunterWoW_QuestEN[66737] = { title = "A Better Start", description = "Vaeros is diligent, but whelps have a way of finding trouble. Not mine, of course--but I suppose not every dragon rears their clutch to understand the gravity of their station.\n\nWhile I am loathe to encourage outdoor play over study, I will help you safeguard the garden more effectively. Take these seeds and plant them nearby. When mature, the blooms produce a fragrance that insects find disagreeable.\n\nThe gardeners can help you--and maybe my bronze brethren, if you mind your manners.", objectives = "" }
WordHunterWoW_QuestEN[66777] = { title = "Uktulut Coaster", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[66778] = { title = "Uktulut Coaster - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[66779] = { title = "Heir Apparent", description = "As Neltharion's heir and leader of the only surviving flight of black dragons, I was not expecting to find myself in competition for my birthright. Particularly not against a self-important whelp younger than you, mortal.\n\nNevertheless, if you need more than these self-evident facts, feel free to speak with members of my flight. There's no need to take my word on the subject.", objectives = "" }
WordHunterWoW_QuestEN[66780] = { title = "Claimant to the Throne", description = "I have dedicated myself to saving Azeroth from destruction time and time again, and this fool thinks he can just swoop in and claim the title of aspect? I think not.\n\nTalk to my people, {name}. See what they have to say about me and what I have done for this world.", objectives = "" }
WordHunterWoW_QuestEN[66781] = { title = "A Matter of Taste", description = "The disrespect around here!\n\nA couple smelly gorlocs steal bits from our equipment and we have to shut it all doon... Ha! I've been lickin' rocks since before ye were a wee babe! Did nae need nae fancy gnomish gadgetry. \n\nBring me a rock, and I'll prove it!", objectives = "" }
WordHunterWoW_QuestEN[66783] = { title = "Renewal of Vows", description = "Centuries ago, I made a vow of friendship and cooperation with the first centaur. Although much has changed, I feel it is time for us to renew that vow again.\n\nA recitation was composed to help future generations of centaur remember their bond with the green dragonflight. Each verse must be answered with an offering from the khans. I hope the centaur can still remember the original meanings.\n\nThe choice of gift is critical. Choose the right offering, and our allegiance is bound.", objectives = "" }
WordHunterWoW_QuestEN[66784] = { title = "Starve the Storm", description = "You fight well for one who must balance on only two legs!\n\nIt matters not how hard we fight so long as the Primalists continue to draw reinforcements. We must close that portal, the Storm Corridor!\n\nFight your way into the nearby cavern and slay the Primalist Storm-Summoners holding it open. I will aid you if I am able.", objectives = "" }
WordHunterWoW_QuestEN[66785] = { title = "The Last Eggtender", description = "I understand your concern, {class}, but all will be rectified shortly as it seems that we are about to have company. \n\nFeel free to stay and witness what transpires. It should be quite cathartic.\n\nDo speak with our egg tender when you have a moment, though. She will no doubt need the support.", objectives = "" }
WordHunterWoW_QuestEN[66786] = { title = "Wingrest Roundabout", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[66787] = { title = "Wingrest Roundabout - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[66788] = { title = "Egg-cited for the Future", description = "I can scarcely believe it! Eggs of the Black Dragonflight! After all this time!\n\nBut look at the state of this place! It will not do at all! Nothing is too good for these eggs.\n\nThough with those two blowhards squabbling like children for the Life-Binder's favor, you can bet they have not spared a thought for us! You, though, will not leave an old egg tender all alone, will you?", objectives = "" }
WordHunterWoW_QuestEN[66814] = { title = "The Judgment of Tyr", description = "Welcome to the Veiled Ossuary. Originally built to house and memorialize the dead. Now the likely location of the stone we've come to call the Judgment of Tyr.\n\nWe haven't received reports of any overt Sundered Flame presence here, but the expedition has learned that they prefer to strike unawares.\n\nBe on your guard, {name}.", objectives = "" }
WordHunterWoW_QuestEN[66825] = { title = "A Ruby Lifecalling", description = "{name}! How fortunate you are here! We are about to begin a Lifecalling Ceremony and would be honored if you assisted us. \n\nA dragonspawn's Calling is very special. Some become masterful gardeners; others care for particular wildlife.\n\nThese young dragonspawn have finished their training and are ready to take on their first Callings. I know they would be thrilled to have you participate. When you're ready, please present each of the items on this table to them.", objectives = "" }
WordHunterWoW_QuestEN[66827] = { title = "Flowers of our Labor", description = "The legend says she only sings it for those who prove their devotion to life.\n\nI've been tending this garden for years... And I think my plants and I are finally ready.\n\nI'll start setting up by the pool here. You can help me with the harvest!\n\nGather seed pods from beneath bushes, dragonflowers from sunny fields, and dragonfruit high in the trees. You can borrow my old rake to help with those. And watch out--sometimes the foliage can be feisty!", objectives = "" }
WordHunterWoW_QuestEN[66828] = { title = "Huddle at the Hollow", description = "I've never seen Akora this upset. Usually she's as sunny as her flowers, but that legend means a lot to her. She talks about it all the time. Hm...\n\n<Keshki fidgets with their glasses.>\n\nI don't know a lot about plants, and I don't think frogs would cheer up anyone but me...\n\nBut north of here there's a quiet spot where I do my thinking: Hornswog Hollow. Maybe we can find something to cheer her up there? Or, uh, try to formulate a plan to help?", objectives = "" }
WordHunterWoW_QuestEN[66830] = { title = "Hornswoggled!", description = "Oh, those hornswogs make me so mad!\n\n<Keshki stomps her foot angrily, knocking her glasses askew>\n\nThey're big, greedy bullies! Just because the place is named after them doesn't mean they get to jump all around and eat everything smaller than them!\n\nHere, use my jar of fireflies--it's a frog-minder's best friend. It'll calm the frogs enough that you can collect them, and we can get them out of harm's way.\n\nAnd if any hornswogs get in your way, don't be afraid to bully them back!", objectives = "" }
WordHunterWoW_QuestEN[66831] = { title = "Home Is Where the Frogs Are", description = "All the frogs are rounded up, {name}! I guess we're, uh, taking the frogs to Akora anyway. They'll be safe at the Life Pools until the hornswogs get bored and move on.\n\nUm, well, I guess we didn't find anything to cheer up Akora. I hope she understands...", objectives = "" }
WordHunterWoW_QuestEN[66834] = { title = "Rellen, the Learned", description = "Bring your offerings to the central den. You may witness the legend of Rellen, the Learned, who gave centaur our livelihood as we know it.", objectives = "" }
WordHunterWoW_QuestEN[66835] = { title = "Sundapple Copse Circuit", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[66836] = { title = "Sundapple Copse Circuit - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[66837] = { title = "Nothing for Breakfast", description = "My brother Valdo was supposed to order more supplies. But it's been a week and nothing has come. \n\nI'm not surprised. The lazy oaf probably took a nap instead! Now we're short on food, and I'm too busy to hunt on top of my chores--and Valdo's! \n\nWould you hunt for us? The meat of the vorquin striders and striped bruffalon south of here would keep the kitchen open until I can order supplies.", objectives = "" }
WordHunterWoW_QuestEN[66838] = { title = "It's Cold Up Here", description = "Being a good innkeeper means anticipating guests' needs. Unfortunately, I didn't anticipate how cold the nights would be here. Oops?\n\nMy guests are going to need blankets--and good, thick ones. Maybe bear pelts will do?\n\nThere are some large bears in the forest just east of here. If you bring me some of their pelts, I'll pay you for them! \n\nPlease? Think of the adventurers and their cold, cold feet...", objectives = "" }
WordHunterWoW_QuestEN[66839] = { title = "It's Brew Time!", description = "The gang had some time off and was hankerin' for a pint, so we bellied up to the inn.\n\nBut, ach! I can nae believe it! They didna have any brew! What kind o' inn is that? One ran by the Stonehinges--that's what kind!\n\nSo we're takin' matters into our own hands! The forest to the east has flowers and herbs that we could use to brew some sweet mead. Feel like helpin' me and doin' some flower pickin'? There'd be somethin' in it for ye!", objectives = "" }
WordHunterWoW_QuestEN[66840] = { title = "Water Safety", description = "My greatest responsibility is to make sure everyone has access to clean drinking water.\n\nWith the gnolls to the east dealing with the decay, I must make sure that the camp is safe.\n\nI don't want to alarm anyone by personally taking samples, but I feel testing is necessary.\n\nBring me samples from the three nearby waterfalls, and I will reward you handsomely.", objectives = "" }
WordHunterWoW_QuestEN[66841] = { title = "A Shard of the Past", description = "I've seen ye runnin' in and out of the camp helpin' people. Ye think ye could help ol' Gannar too?\n\nI surveyed the area, and somethin' caught me old eyes. I think 'tis an ancient potsherd or a jar or somethin' just down south of here at the edge of that waterfall.\n\nNow, I am not much of a swimmer, but I'll give ye some coin and you can deliver the findings to Thanessa Silverbloom.", objectives = "" }
WordHunterWoW_QuestEN[66843] = { title = "Out of Lukh", description = "Ach! Have ye seen me assistant, Lukh?\n\nThe kid wanted a moment to look 'round, but he's been gone for an hour! \n\nI told him it ain't safe here and to nae walk far, but the kid has a head as thick as a ram's.\n\nI can nae say I blame him. it's pretty out here, and he has a thing for flowers.\n\nCould ye help me find 'em? They need me and the wagon back at Three-Falls Lookout!", objectives = "" }
WordHunterWoW_QuestEN[66844] = { title = "The Great Shokhari", description = "Of all da animals I have seen here, Shokahri, da great sky vixen, be da most proud.\n\nIt be a shame she preyed on a gnoll shaman, cause now she be crazed with decay. When I saw her eating one of her kits, I knew something was not right.\n\nI took da kits away and brought them here, but Shokhari attacked me, swiping me good. I almost didn't make it.\n\nShokhari must be put down. If da decay rots more of her mind, she be coming for us soon.", objectives = "" }
WordHunterWoW_QuestEN[66845] = { title = "Legendary Foil", description = "Last night, I was lying in my bedroll, tossing and turning, when an unnatural chill filled the inn. \n\nThen, out of nowhere I saw... the ghost of a draconid! It went through my luggage then vanished into thin air! \n\nBut the true horror is that when I woke up... the ghost had taken my most beloved card!\n\nWould you be so kind as to track down the ghost and get my card back? It is my most prized possession.", objectives = "" }
WordHunterWoW_QuestEN[66846] = { title = "The Heart of the Deck", description = "The day the Dragon Isles began their slumber was the day of my very last match. Fate was cruel, and I lost my strongest card before I could compete.\n\nGuo-Hee's card, you see, was mine. I do not know how her ancestors came upon it.\n\nAlas, I cannot claim it as my own as it has been in her family for centuries. That was a foolish mistake on my part.\n\nPerhaps you and I could craft a card together? A truly unique card... Yes! Will you help me?\n\nSpeak to me once you are ready.", objectives = "" }
WordHunterWoW_QuestEN[66847] = { title = "Vault of the Incarnates: Fury of the Storm-Eater", description = "No! We locked the Incarnates away to save this world and now Raszageth seeks to free them!\n\nShe cannot succeed, {name}. All life on Azeroth is in grave danger if you do not stop her!\n\nI shall return to Nozdormu at the Seat of the Aspects to plan for whatever is to come. \n\nKhadgar and Kalecgos are already inside with a contingent of allies. Join them to put an end to Raszageth.\n\nGood luck, champion.", objectives = "" }
WordHunterWoW_QuestEN[66848] = { title = "Omens on the Wind", description = "Ohn'ahra does not speak in language as we do. Her voice carries through the very winds. We mystics are trained to feel her presence, follow her call, and interpret her messages.\n\nI have used the materials you gathered to bind totems to this particular call. Aid me in a ritual to center her voice, then I will interpret her song.", objectives = "" }
WordHunterWoW_QuestEN[66856] = { title = "Becca Black and the Seven Gnomes", description = "The djaradin have ransacked the Obsidian Citadel and stolen a number of valuable artifacts.\n\nWrathion has tasked us to recover every item taken from the Citadel. My team has located several in the area, but we could use your help.", objectives = "" }
WordHunterWoW_QuestEN[66858] = { title = "Tour the Trading Post", description = "<A flyer, carried by the wind, flaps into your hands.>\n\nFancy yourself a collector, trader, or adventurer? \n\nWe've travelled all over Azeroth collecting goods of the finest quality for someone exactly like you!\n\nVisit one of our outposts in Stormwind or Dornogal and browse all the latest goods!\n\n--T&W Trading Post\n\n<You squint to read the fine print.>\n\nBe sure to present this flyer for some extra Trader's Tender!", objectives = "" }
WordHunterWoW_QuestEN[66877] = { title = "Fen Flythrough", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[66878] = { title = "Fen Flythrough - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[66879] = { title = "Hornstrider Havoc", description = "Hornstriders! They've got bone-breaking beaks, fast legs for getting away from danger, and they can eat anything in the Isles.\n\nThis Calling's the easiest around! It's just me and my favorite big birds spending time together. And if anything comes up, I know how to wrangle all of the Isles' critters.\n\nWould you mind following me to the hornstrider plateaus up north? I wouldn't mind an extra pair of hands while getting set up.", objectives = "" }
WordHunterWoW_QuestEN[66880] = { title = "Ravine River Run", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[66881] = { title = "Ravine River Run - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[66882] = { title = "Lost Battlepack", description = "<Talonstalker Kavia might want this.>", objectives = "" }
WordHunterWoW_QuestEN[66883] = { title = "Ancient Horn Ring", description = "<Exadria might want this.>", objectives = "" }
WordHunterWoW_QuestEN[66884] = { title = "Fireproof Gear", description = "The armor of the djaradin can withstand even the fiercest flames. Such qualities would be of great use in combating them!\n\nSee what you can gather from the djaradin. We can study it, and apply the same enchantments to our own armor.", objectives = "" }
WordHunterWoW_QuestEN[66885] = { title = "Emerald Gardens Ascent", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[66886] = { title = "Emerald Gardens Ascent - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[66890] = { title = "Stolen Tools", description = "We have been plagued by gnolls raiding our supply caravans. They appear to be obsessed with the various engineering tools within. We cannot risk these violent raiders figuring out our specialized art! Also, these thefts have set our production schedule back more than I'd like to admit.\n\nIf you can retrieve some of the stolen engineering parts, we can get back on schedule.", objectives = "" }
WordHunterWoW_QuestEN[66891] = { title = "Explosive Ash", description = "The molten phoenixes in the Dragon Isles create an unusual ash substance once they die. It could be used to create some material improvements for some complex, life-changing machinery. Though I would probably use it for explosives.", objectives = "" }
WordHunterWoW_QuestEN[66892] = { title = "Deluge Dilemma", description = "Elementals are killing the hornstriders! I know how to wrangle large critters, but I never thought I'd have to go toe-to-toe with an elemental! These aren't anything like baby thunder lizards...\n\n<Dazakros sighs, distressed.>\n\nPlease knock down a few of them elementals. Hornstriders have a lot more sense than we give them credit for. They'll fight back if they have the means to!", objectives = "" }
WordHunterWoW_QuestEN[66893] = { title = "Beaky Reclamation", description = "I may not know anything about water elementals, but I do know hornstriders!\n\nI've thrown together a salve that'll keep the 'striders healthy and ready to fight. I've never had a chance to apply it to a real hornstrider, but I've done all the studying I can do.\n\nIt's time to put on a brave face and lather them up!", objectives = "" }
WordHunterWoW_QuestEN[66894] = { title = "Same as the Old Boss", description = "The Worldbreaker dragonkin are a trusting lot. We have followed many different leaders over the years, believing that each will lead us to the Hour of Twilight and the return of Deathwing.\n\nHowever, Deathwing has not returned, and still there is no Twilight.\n\nIt is time for a new leader. You can help bring about the change.", objectives = "" }
WordHunterWoW_QuestEN[66895] = { title = "Same as the Old Boss", description = "The Worldbreaker dragonkin are a trusting lot. We have followed many different leaders over the years, believing that each will lead us to the Hour of Twilight and the return of Deathwing.\n\nHowever, Deathwing has not returned, and still there is no Twilight.\n\nIt is time for a new leader. You can help bring about the change.", objectives = "" }
WordHunterWoW_QuestEN[66897] = { title = "Fuel for the Forge", description = "To make the best blades, you need the heat that only a Magma Core can provide. We try to keep a few on hand as a fuel source for our forges. Lately, we've been running low on cores and could use a resupply.\n\nMagma Cores are obtainable from most lava creatures in the Dragon Isles.", objectives = "" }
WordHunterWoW_QuestEN[66899] = { title = "Fuzzy Legs", description = "We have received a request for \"Fuzzy Legs\" for tailoring...\n\nDon't look at me, I don't make the requests, I just pass them on. I imagine the legs of tarantulas would fulfill this request.", objectives = "" }
WordHunterWoW_QuestEN[66900] = { title = "Enchanted Relics", description = "Ah, the tides have brought you at just the right time! Gnolls have stolen some of our relics. These are more precious than most--they have been enchanted. We cannot allow the gnolls to learn our magics!\n\nSomeone of your skill should have no issue identifying the stolen relics. Please, will you lend us your aid?", objectives = "" }
WordHunterWoW_QuestEN[66921] = { title = "Maruukai Dash", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[66925] = { title = "[DNT] Boar-B-Q", description = "", objectives = "" }
WordHunterWoW_QuestEN[66929] = { title = "Gotta Collect Them All", description = "{class}, do you mind helping me get my cards back? \n\nI told Setogosa I need them to show other students how to play Hearthstone. I want to form a club, but she's not giving them back!\n\nShe's always been rude to me, but this is taking it further than normal.", objectives = "" }
WordHunterWoW_QuestEN[66931] = { title = "Who Brought the Ruckus?", description = "That was no ordinary quake.", objectives = "" }
WordHunterWoW_QuestEN[66933] = { title = "Mirror of Sky Dash", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[66935] = { title = "Crystal Quill Pens", description = "There are unique creatures in these lands called crystalspines. They are cute little creatures protected by sharp crystal quills.\n\nWhen I was treating one of our researchers for being stuck by one, I noticed that there was a lingering power resonating within. They might make for an excellent source of enchanting crystals.", objectives = "" }
WordHunterWoW_QuestEN[66937] = { title = "Decaying News", description = "The gnolls and their use of decay magic are concerning. We need to gather as much knowledge as we can, in case the threat escalates. \n\nAs alchemists, we are used to gathering such foul substances safely--plus, we're used to the smell. Will you lend your aid?", objectives = "" }
WordHunterWoW_QuestEN[66938] = { title = "Mammoth Marrow", description = "Creating new and unusual brews is one of our many specialties. While we do enjoy experimenting with new and fascinating ingredients, we have a few common ingredients that we keep in stock. \n\nOne of these ingredients is the marrow from mammoth tusks. We have run short on marrow and would appreciate your help in collecting more for our alchemists.", objectives = "" }
WordHunterWoW_QuestEN[66939] = { title = "Hunting the Huntmaster", description = "I heard from one of the guards in Camp Nowhere that there's a nasty piece of work mutilating the local wildlife. Calls itself a 'huntmaster'.\n\nHunting is one thing, but I can't abide torturing any living thing. \n\nBesides, my wagon could use a good luck charm.\n\n<Nesingwary spits over the side.> \n\nBring me back its paw.", objectives = "" }
WordHunterWoW_QuestEN[66940] = { title = "Elixir Experiment", description = "Our alchemists have recently looked into a variety of new ingredients for experimentation. Their most recent interest is... interesting... to say the least.\n\nIt appears that gorloc mucus has some properties that can be beneficial for certain elixirs.", objectives = "" }
WordHunterWoW_QuestEN[66941] = { title = "Tremendous Tools", description = "The djaradin have some mighty large tools and weaponry. We can easily find a use for such tools, even if only to smelt them down into more tools for ourselves.\n\nBring back some djaradin tools for us to study and use.", objectives = "" }
WordHunterWoW_QuestEN[66942] = { title = "Enemy Engineering", description = "It may be a bit controversial, but I believe that we can study the rituals of the Primalists to learn new ways to channel elemental power. I'm confident that once we understand the pathways of their magic, we can use it to create all sorts of innovative engineering products.", objectives = "" }
WordHunterWoW_QuestEN[66943] = { title = "Wood for Writing", description = "We've found some unusual information in our studies of the Dragon Isles. For instance, the bark of treants afflicted by decay magic acts similarly to hide parchment. \n\nThis odd parchment is strangely able to hold the magic for more powerful inscriptions. Very useful! Can you help us gather some?", objectives = "" }
WordHunterWoW_QuestEN[66944] = { title = "Peacock Pigments", description = "The peacocks of the Dragon Isles have such colorful feathers! I bet we can make some pigments from them for our scribes to use as ink.", objectives = "" }
WordHunterWoW_QuestEN[66945] = { title = "Icy Ink", description = "The icy beasts in the frozen biomes excrete a very rare and mysterious liquid. The liquid's properties make it the perfect binding agent for our inks. I'm a southpaw so the prospect of not smudging my page is very exciting to me.", objectives = "" }
WordHunterWoW_QuestEN[66946] = { title = "Azure Span Sprint", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[66947] = { title = "Azure Span Sprint - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[66948] = { title = "The Emissary's Arrival", description = "I will admit that I have not left the Emerald Gardens in all my life, and as such, I have never met a centaur, let alone a mortal from the mainland.\n\nHowever, I am not here for a kindly visit, but rather to plead for the centaur's aid in securing our oathstone and protecting our charge.\n\nI am glad to see you are here to help as well. There is much to discuss.", objectives = "" }
WordHunterWoW_QuestEN[66949] = { title = "Trinket Bandits", description = "The gnolls have quite a collection of trinkets. Tuskarr trinkets. They have either stolen them from our villages, or worse, from the brave tuskarr that fell in battle against them. These trinkets are our heritage and should reside with us.\n\nIf you bring some back to me, I will teach you the techniques that are used to make them.", objectives = "" }
WordHunterWoW_QuestEN[66950] = { title = "Heart of a Giant", description = "There are various giants within the Dragon Isles that are rumored to contain beautiful gems at their core. We normally don't hunt the creatures of the Isles for treasures, but these giants have caused quite a bit of havoc.\n\nWe may as well collect these gems in the process of clearing out the destructive giants.", objectives = "" }
WordHunterWoW_QuestEN[66951] = { title = "Population Control", description = "Recently there has been an overpopulation of a few different species on the Dragon Isles. In particular, the rockfang and the bruffalon.\n\nWe don't want to be wasteful, of course. Be sure to collect as much of the hides as you can from the creatures.", objectives = "" }
WordHunterWoW_QuestEN[66952] = { title = "The Gnoll's Clothes", description = "The gnolls are a constant threat, launching bloody raids and attacks against the expeditions and peoples of the Dragon Isles. So how are their clothes so clean?\n\nAfter your battles with these raiders, could you collect a sample of their worn cloth for me to analyze?", objectives = "" }
WordHunterWoW_QuestEN[66953] = { title = "All Things Fluffy", description = "The tailors are always anxious to get their hands on that fluffy argali fur. The wool is especially useful for surviving in the freezing cold mountains of the Dragon Isles.", objectives = "" }
WordHunterWoW_QuestEN[66957] = { title = "A Shadow In The Ice", description = "I've heard whispers while passing through Camp Antonidas. Talk of mutilated fauna being found across the icy steppes. Some nothing more than bloody splatters. \n\nWhatever it is, it's got the mages scared and made the local wildlife scarce.\n\nPoke around the top of the glacier. If I was a betting dwarf, I'd say that's where any apex predator worth its salt would stake its claim.\n\nBring me a piece of it so we can soothe the Kirin Tor.", objectives = "" }
WordHunterWoW_QuestEN[66958] = { title = "Protect And Herd", description = "I was talking with some hunters out of Iskaara the other day, and they mentioned finding a grisly scene. \n\nApparently, a particularly murderous rhino, Bloodhorn, has been goring the smaller bruffalon in the area. \n\nThe bruffalon have enough competition in Azure Span without worrying about getting their herds thinned out by an invasive brute from out of town!\n\nBring me his horn. I'd like to make a good impression on our Tuskarr friends!", objectives = "" }
WordHunterWoW_QuestEN[66959] = { title = "Tour the Trading Post", description = "<A flyer, carried by the wind, flaps into your hands.>\n\nRare antiquities from every corner of Azeroth! Fine goods fit for any taste!\n\nYou will not find these unique treasures anywhere else, friend.\n\nCome see us at one of our outposts in Orgrimmar or Dornogal and gaze in wonder upon the mysteries in store for you!\n\n--Zen'shiri Trading Post\n\n<You squint to read the fine print.>\n\nBe sure to present this flyer for some extra Trader's Tender!", objectives = "" }
WordHunterWoW_QuestEN[66962] = { title = "[DNT] 10.0 Explorers - Ch1 - Fake Quest Requirement (SMART)", description = "", objectives = "" }
WordHunterWoW_QuestEN[66963] = { title = "Out For Delivery", description = "I tried to tell Vevesi that I could pull the wagon out of the mud.\n\nBut, no, he insisted on using magic to get it out... And now look what he's done.\n\n<Hauler Bennet sighs.>\n\nWhile I try to talk sense into Vevesi, can you run up the hill to the Basecamp and let Cataloger Wulferd know that he might need to ship another crate of camera supplies over from Boralus?", objectives = "" }
WordHunterWoW_QuestEN[66964] = { title = "Artifacts in the Wrong Hands", description = "We've got a myriad, no, an incalculable number of problems here!\n\nOh man, where to start! \n\nThe Kirin Tor uncovered a Sundered Flame plot. They're after an artifact called \"Valthrux\".\n\nIt's immensely powerful and... sentient? That's an exponential increase in danger if you're keeping track.\n\nOne Alia Sunsoar went south with a pair of tuskarr to investigate the Sundered Flame. She should have been back by now.\n\nPlease find her and stop the Sundered Flame from acquiring the artifact!", objectives = "" }
WordHunterWoW_QuestEN[66968] = { title = "Pruning The Pack", description = "<Nesingwary gestures to the side of the path.>\n\nSee those imprints in the snow? \n\nYeti tracks. \n\nSomething must of riled them up to hunt this close to the road. See if you can't hunt down their pack leader. We don't want them to start ambushing travellers! \n\nIf he's a particularly mean brute, collect his head. That should dissuade the others.", objectives = "" }
WordHunterWoW_QuestEN[66969] = { title = "Clans of the Plains", description = "While you wait for the emissary to arrive, Sansok Khan is interested to hear how meeting the clans went. She sent me to find you and tell you to meet her in the center of Maruukai to discuss.", objectives = "" }
WordHunterWoW_QuestEN[66971] = { title = "The Face of Death", description = "Tell me, friend. Have you ever seen the face of death?\n\n<Nesingwary pauses for dramatic effect.>\n\nWhat am I saying? Of course you have.\n\nDeath, after all, has many faces. \n\nI've heard tell from the Imbu tuskarr that one of its faces lives up in these hills. To even say its name is to invite a violent, frigid death:\n\nFrostjaw.\n\n<Nesingwary looks around warily.>\n\nWell, now you have to hunt it--for my sake at least!", objectives = "" }
WordHunterWoW_QuestEN[66972] = { title = "Old Stonetusk", description = "I have a grim task for you, {name}. Not every kill is a measure of skill. Some are measures of kindness. \n\nThere's an old bull mammoth wandering the forest east of Camp Antonidas. I saw him from a distance awhile back, and I hear his sad trumpeting every so often. Clearly he's in great pain.\n\nHe's started crashing blindly through the undergrowth, and I'm worried he's becoming a danger to others. \n\nIt'd make my old heart glad if you put a fellow weary soul to rest. Bring me his tusk so we can honor him.", objectives = "" }
WordHunterWoW_QuestEN[66987] = { title = "[DNT] 10.0 Explorers - Ch2 - Fake Quest Requirement (SMART)", description = "", objectives = "" }
WordHunterWoW_QuestEN[66997] = { title = "Nursery Direction", description = "I'm so grateful that Lasztak has accepted the Calling of a Whelptender! Especially given how many of the precious little things are teething right now.\n\nBeyond that, the nursery gardens are admittedly facing challenges. The whelps are stressed and the tenders are--well, more stressed than usual.\n\nPlease, whenever you have a spare moment, find me in the gardens below. We could use your help as well!", objectives = "" }
WordHunterWoW_QuestEN[66998] = { title = "Fighting Fire with... Water", description = "In all my years of tending to the lava elementals, I have never seen them act like this! We can barely keep them contained to the cave.\n\nDo you have a minute to spare? We'll hold the exit while you thin their numbers inside.\n\nHere, take this bottled water elemental with you.\n\nI always carry a few spare bottled water elementals when I'm looking after the lava elementals. Natural enemies make for good distractions!", objectives = "" }
WordHunterWoW_QuestEN[67002] = { title = "Azure Span Slalom", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[67003] = { title = "Azure Span Slalom - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[67004] = { title = "Good Things in Large Boxes", description = "Our efforts have created everything we need to open an Earth-Warder's Vault. There are several beneath the Citadel. Locate one and I will reward you.\n\nI have crafted chains to help move it. If you bring the Vault here, we can share in the riches.\n\nWatch for the Vault being moved, as I have dispatched others to find them as well.", objectives = "" }
WordHunterWoW_QuestEN[67007] = { title = "Archival Assistance", description = "<The crisp, clean lettering, written with an elegant touch, fades quickly into the parchment's wet, smudged ink and a smell reminiscent of spilled, fermented beverage.>\n\nADVENTURE SEEKERS, ARCHIVAL ENTHUSIASTS--\n\nThe archives call to those who seek answers, yearn to discover, and those who wish to reveal secrets of the past, and perhaps, the future!\n\nThis request is not for the faint of heart, nor those of wavering will.\n\nOnly curious and brave adventurers need apply.\n\n- Kemora", objectives = "" }
WordHunterWoW_QuestEN[67011] = { title = "Tale of an Adventure: Molten Core", description = "So, you want to tell me a story of your adventure?", objectives = "" }
WordHunterWoW_QuestEN[67031] = { title = "Vakthros Ascent", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[67032] = { title = "Vakthros Ascent - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[67033] = { title = "Assemble the Defenses", description = "The Primalists have been hunting the Kirin Tor since we arrived in the Azure Span. They detest our practice of arcane magic.\n\nI'll send word to Kalecgos to return from the Azure Archives. In the meantime, we need to hold them off.\n\nIt seems one of our main arcane defenses was destroyed in their initial attack. Bring the pieces back to me and I can reassemble it.", objectives = "" }
WordHunterWoW_QuestEN[67034] = { title = "Of Wind and Water", description = "To the east is a great dragonspring which serves as a nesting area for wild eagles. The feathers they shed still contain their magic for quite some time and are used in many rituals.\n\nThe area also hosts raging spirits of the elements, and their cores are of some use as well.\n\nBring a collection of both back to me - and remember that the eagles are sacred, I will not accept feathers that are gathered from their harm.", objectives = "" }
WordHunterWoW_QuestEN[67035] = { title = "Preservation of Knowledge", description = "Greetings, {race}. I am Althanus. I wish we could have met in a less... chaotic time.\n\nWe were helping the Kirin Tor study the history of this place just a few moments before the Primalists attacked.\n\nI fear several tomes may still be out there, at risk of being destroyed in this dreadful assault.\n\nPlease, you must recover these tomes! If they're destroyed, the history of this place will be lost.", objectives = "" }
WordHunterWoW_QuestEN[67036] = { title = "Wrath of the Kirin Tor", description = "I've assembled the pieces of the device you recovered. \n\nPlace it near Khadgar and use it to repel the Primalists! \n\nWe just need to hold out a little longer until Kalecgos arrives.", objectives = "" }
WordHunterWoW_QuestEN[67039] = { title = "An Amazing Journey", description = "A few of the clan's pets ended up getting lost along the last journey between camps. They're not hunting animals so I doubt they can take care of themselves properly out there!\n\nDo you think you could go search for them? They may not be hunting partners, but they're important members of the clan regardless!", objectives = "" }
WordHunterWoW_QuestEN[67044] = { title = "Tale of a Hero: Yanikk", description = "Let me tell you the tale of Yanikk.", objectives = "" }
WordHunterWoW_QuestEN[67047] = { title = "Warm Away These Shivers", description = "I believe the plant you're looking for has a fine, narrow stem and red leaves all about it.\n\nYou'll be hard-pressed not to run into any of those dastardly crawlers while you're collecting flowers though. I'd advise you steer clear when you can, or ready a sharp weapon when you can't.\n\nAnd let your dragon friend know they can repay me in a cup or two of the stuff next time I'm in the city.", objectives = "" }
WordHunterWoW_QuestEN[67050] = { title = "Frostbite: Causes and Symptoms", description = "Elements live in the totems, {race}. Release them and break the ice. Free your tuskarr friends!", objectives = "" }
WordHunterWoW_QuestEN[67051] = { title = "Dragon Eyes", description = "We know the djaradin will attack us directly, but I'm worried about other dangers out there as well. Ones that aren't so obvious.\n\nI have dispatched three dragons to survey the surrounding area and pinpoint any potential threats.\n\nMeet with each of them. Collect their reports for me. Once you have gathered this information, return to me so we can best prepare for what the djaradin are planning.", objectives = "" }
WordHunterWoW_QuestEN[67053] = { title = "Give Peace a Chance", description = "Light be with you, {name}.\n\nThis expedition is under the protection of both the Horde and Alliance. Our orders are clear: give aid to any members of the expedition, regardless of their other allegiances.\n\nThe Horde's representatives, Warlord Grimaxe and her daughter Shuja, stand guard on the other side of camp.\n\nI fought with Warlord Grimaxe against the scourge. She is noble and will serve this expedition well.\n\nGo offer her your assistance. Show her that the Alliance honors its commitments.", objectives = "" }
WordHunterWoW_QuestEN[67063] = { title = "10,000 Years of Roasting", description = "Spices? Oh! Ya must be with da big 'ol dragon cook. Da one with a little duck chef on her head.\n\nDjaradin collect up a powder, Spicy Lava Spices, off da fiery elementals down below. \n\nDon' you look at me like dat! It's what da Djaradin be calling dem, not me!\n\nGood luck down there. I wouldn't go alone if was you.", objectives = "" }
WordHunterWoW_QuestEN[67064] = { title = "Rambling Delight", description = "Oh, Rumiastrasza! Myself and the dryad sisters, Celina and Felina, had a lovely evening cooking for her.\n\nThe kelp we ate is a unique strain called Glimmering Ramblekelp. Swarms of frillfish devour them all along the coast. I wouldn't be surprised if they attack you while you're plucking their food from the sea floor.\n\nPlease give the chefs my best when you see them. They're always welcome here in our sanctuary.", objectives = "" }
WordHunterWoW_QuestEN[67065] = { title = "Future-Fresh Fungi", description = "A delicious mushroom? Alternate futures are not pantries to be raided for midmorning snacks.\n\nBut still... I would be lying if I said I had never dreamed of eating Rumi and Morsel's cooking again.\n\nVery well! You have my permission to pass through the portal, though I advise you to find others to travel with.\n\nMy wardens have mentioned these dark mushrooms to me before. Apparently, they never stay in the same place for very long. Make of that what you will.", objectives = "" }
WordHunterWoW_QuestEN[67066] = { title = "Delights to Delve For", description = "Rumi and Morsel?\n\nGosh, that was quite a long time ago now. Eating a fish with a dragon and duck chef duo sounds like the beginning of a tale Elder Poa might tell for the younglings. We'd be hard-pressed to forget such a happening!\n\nThe fish was a Savory Deviant Dealfish, a top Tuskarr favorite! They're rare, but found just off the coast here.\n\nFair warning - it's azuretooth mating season. Those bloodthirsty fiends will take a chunk out of you for messing with their favorite snack.", objectives = "" }
WordHunterWoW_QuestEN[67067] = { title = "Navigating the Leapmaize", description = "There's a dragon chef in Valdrakken? Truly? I'll have to ask her to try my arclight bisque! It's an old family recipe.\n\nI know the plant you speak of. It grows around streams here, but it's caused some problems.\n\nThe stalks of leapmaize seem to be a natural feeding ground for beetles and small salamanthars, which are, in turn, natural prey of the hornswogs. That's fine if you can spot them out in the open, but there's a few here that are incredibly stealthy.\n\nI'd watch my back if I were you.", objectives = "" }
WordHunterWoW_QuestEN[67068] = { title = "Anything But a Breeze", description = "Breezehunters?! Oh, those falcons have been a problem. Just the other day, our stable master, Marren, almost fell to her death trying to tame one.\n\nShe's pretty proud, so she blamed it on the breezehunter itself. Told me that if it didn't think her eggs were being attacked, it wouldn't have been so aggressive as to bully her off the cliff's edge.\n\nI guess that means that you might find the eggs you're looking for out there? It was to the east, just around the mountainside here.", objectives = "" }
WordHunterWoW_QuestEN[67071] = { title = "What a Long, Sweet Trip It's Been", description = "{name}! Just who Morsel and I were looking for!\n\nFrom the bottom of both of our winged-hearts, we thank you dearly.\n\nWe started The Ruby Feast to share the Isles' culinary culture with all of Azeroth's races, and to learn from them too. We had you running from one end of our beloved continent to another, but you helped bring our dream vision of these gatherings to each honored visitor and guest here.\n\nAs friends, we would like to give you a gift. Grab the top journal from our hoard behind the cauldron.", objectives = "" }
WordHunterWoW_QuestEN[67073] = { title = "Red Dawn", description = "We've come so close to recovering our powers... should Raszageth succeed before our powers return, I fear that the timeways will bend to a dark future for all of Azeroth.\n\nWe must not allow this to occur, {name}!\n\nHurry, you must find and aid Alexstrasza before all is lost!", objectives = "" }
WordHunterWoW_QuestEN[67074] = { title = "The Gift of Silver", description = "Shortly before his passing, Keeper Tyr gifted us with a dragon scale forged of purest silver. We kept it in the vaults of Valdrakken during our absence, but I believe it is time to share it once more.\n\nThough we have no idea the purpose for this memento, it has always been a symbol of unity and friendship to us. As a true ally to dragonkind, we would like to share it with you. Speak to me when you are ready, {name}.", objectives = "" }
WordHunterWoW_QuestEN[67075] = { title = "The Magic Within", description = "Intriguing. There are many mysteries living within this citadel that no one, save Keeper Tyr himself, understand. If we are to unlock this further we shall have to explore more of Tyrhold. \n\nI believe that the scale will draw out secrets stored within this place.\n\nHowever. there is one complication. The guardians of Tyrhold are still... unstable. They may take your exploration as disruption and try to interfere. Take this conduit. It will help you should the guardians prove troublesome.", objectives = "" }
WordHunterWoW_QuestEN[67076] = { title = "A Spark of Discovery", description = "Though this spark is of peculiar origin, I sense it is familiar. I am not sure of its purpose, but I believe it may lead to your next step in unraveling this mystery.\n\nFollow it and see if you can learn more of its purpose, while I see what else I can discover in the meantime.", objectives = "" }
WordHunterWoW_QuestEN[67077] = { title = "Memories of the Past", description = "This place is where we last saw our friend, Tyr.\n\nWe did not understand the circumstances by which he had to leave, only that it was for something important.\n\nThough it may be difficult for our hearts to bear, I believe this spark called us here to witness that time once more. With Nozdormu's aid we may relive that moment and see if there was some other clue Tyr left behind for us.", objectives = "" }
WordHunterWoW_QuestEN[67078] = { title = "Parting Instructions", description = "<The echo speaks with an ancient voice.>\n\nTo my dear friends, I apologize for my sudden departure.\n\nBut, I promise that you are not without my aid. I know that you have come upon the time of great need, but to ensure this gift does not get misused I must ask you to perform a series of tasks.\n\nThe first is simple: reactivate the forge within Tyrhold. The Silver Scale is the key.", objectives = "" }
WordHunterWoW_QuestEN[67079] = { title = "Hard Lock Life", description = "The security in the forge is stricter than in any other area of Tyrhold. This will be quite a challenge for us, {class}.\n\nOnly certain units around the citadel have the capability to bypass this security, and the protocols to unlock require more than one code in case of corruption.\n\nThese units will not want to relinquish their overrides, you may have to take them by force. Be careful, {name}.", objectives = "" }
WordHunterWoW_QuestEN[67080] = { title = "Artisan's Supply: Dragon's Alchemical Solution", description = "Are you looking for work, alchemist?\n\nThe Artisan's Consortium has reached out to me with a \"crafting order\" for my alchemical solutions. I am as curious as the next dragonkin to find out more about these business practices, but I am simply too busy.\n\nPerhaps this is an opportunity for you, my apprentice. Create some alchemical solution by reclaiming your earlier concoctions, and bring it to Haephesta, just down the path.", objectives = "" }
WordHunterWoW_QuestEN[67081] = { title = "Halls of Infusion: An Infusion of Materials", description = "<The image of Tyr speaks again.>\n\nYou have reactivated the forge. The next task will not be as simple.\n\nTranscribed within the scale are schematics for something I require you to forge. I have entrusted one of my watchers, Irideus, with the necessary materials for this task. They are of special origin, and only few of them are left in existence.\n\nSeek Irideus within the Halls of Infusion, where I hope his careful watch has kept the facility operating in an orderly fashion.", objectives = "" }
WordHunterWoW_QuestEN[67084] = { title = "The Silver Purpose", description = "<The echo of Tyr activates to your presence.>\n\nYour task is at hand, my friends.\n\nCast the ingots into the fire and activate the forge. I have prepared the necessary procedures for you already.\n\nThe Silver Scale holds the schematic. Its purpose shall reveal itself to you.", objectives = "" }
WordHunterWoW_QuestEN[67093] = { title = "An Anomalous Shrine", description = "My research team located a strange sanctum nearby. We were able to make out some writing on the outside of it--titan runes, to be exact--which we believe reference Aman'Thul the Highfather, leader of the titans, in several places.\n\nWe tried to inspect more closely but must have triggered the sanctum's defenses. A massive sand amalgam blocked us off and we narrowly made it out alive.\n\nWe aren't certain what it's protecting, but it must be important. Can you investigate?", objectives = "" }
WordHunterWoW_QuestEN[67094] = { title = "A Dryad's Work Is Never Done", description = "It is wonderful to see Valdrakken so lively again, but there are so many things that have wilted under thousands of years of neglect - not the least of which are all of the adorable little city critters! Alas, we don't have enough dryads to go around tending to them all. \n\nSay, how would you like to be appointed Honorary Valdrakken Dryad? Some of the city's cutest little friends have gone far too long without their preferred snacks. Won't you help me tend to them?", objectives = "" }
WordHunterWoW_QuestEN[67095] = { title = "Flowing Forest Flight", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[67096] = { title = "Flowing Forest Flight - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[67099] = { title = "Dragon Eyes", description = "We know the djaradin will attack us directly, but I'm worried about other dangers out there as well. Ones that aren't so obvious.\n\nI have dispatched three dragons to survey the surrounding area and pinpoint any potential threats.\n\nMeet with each of them. Collect their reports for me. Once you have gathered this information, return to me so we can best prepare for what the djaradin are planning.", objectives = "" }
WordHunterWoW_QuestEN[67100] = { title = "A Gift for Miguel", description = "{name}, could you do me a favor?\n\nI want to get a gift for my husband, Miguel.\n\nHe means so much to me, but I've been so busy lately that I haven't had time to make him anything. \n\nCould you help me make him something high quality?", objectives = "" }
WordHunterWoW_QuestEN[67111] = { title = "The Ailing Apprentice", description = "This mission was a mistake from the beginning. Alia Sunsoar enlisted our aid to keep the Sundered Flame from acquiring a dangerous artifact. We had tracked it down to these ruins.\n\nBut the Sundered Flame beat us here and the area is infested with ice spiders. Alia was badly poisoned, and I fear she will not last long without the antidote.\n\nI can make it, but I need venom glands from the nearby spiders. I'm afraid to leave her. Will you find some for me?", objectives = "" }
WordHunterWoW_QuestEN[67137] = { title = "Professionally Equipped", description = "Say, I heard from Haephesta that you're a working artisan as well.\n\nWe'd like to get you set up with some professional equipment. Free of charge. That's what business partners are for, right?\n\nTalk to our tailor, Mahra Treebender, to get fitted.", objectives = "" }
WordHunterWoW_QuestEN[67142] = { title = "Wyrm Food", description = "It's hungry work, defending and fighting for the Obsidian Citadel, and dragons can eat a great deal. We need to replenish our stores.\n\nLurking beneath the hardened lava, squirming through the magma, are some very tasty worms. This may not appeal to you, but to a hungry dragon, they are delicious.\n\nTake our servant Gulchak and use his pointer to direct him towards disturbances in the lava. He will attract the worms for you to harvest.", objectives = "" }
WordHunterWoW_QuestEN[67143] = { title = "To Give One's Heart", description = "Now that we have the elemental essence gathered, do you think you could put them in this bottle?\n\nIt's a simple recipe that you can craft the same way as any other recipe.\n\nIf you lost, or use up the high-quality reagents, you can always get more from the elementals at Hornswog Hollow.", objectives = "" }
WordHunterWoW_QuestEN[67154] = { title = "Entropic Remnants", description = "When an entity passes through the timeways, the sands of time can sometimes accumulate on their body. \n\nTypically, this sand dissipates in short order--but sometimes, the entropic fluctuations inherent in time travel can cause that sand to vitrify. In these cases, it becomes rather difficult to remove. I've ruined several good pairs of shoes this way.\n\nVitrified sand can be quite powerful for our purposes. It would be in best interest to reclaim as much of it as we can.", objectives = "" }
WordHunterWoW_QuestEN[67167] = { title = "It's Time To Duel!", description = "With my deck back, I can focus on recruiting new members to my club! I was thinking about asking the dracthyr...\n\nOh, that is another thing you can help me out with, {name}! \n\nI am going to be a bit busy trying to get other dragons to join and I really want to get the dracthyr involved.\n\nDo you mind talking to them for me? Be warned; many of them have never played before.", objectives = "" }
WordHunterWoW_QuestEN[67174] = { title = "Arcane Detection", description = "Greetings! I am Miva Star-Eye, and I am conducting arcane investigations in this area. \n\nThe Azure Span has magic all around it. Some of it is benign... while some can be quite dangerous. \n\nI've been tasked with ensuring no arcane energies reside in anything the tuskarr possess. \n\nWe already had one incident in Camp Antonidas of a fishing box spontaneously combusting! \n\nCan you take my detector and examine a few objects here? I need to continue speaking with Julk over here.", objectives = "" }
WordHunterWoW_QuestEN[67175] = { title = "How To Stop An Exploding Toy Boat", description = "I am loathe to part a child from their toy, but it would be a great value to the Kirin Tor to study how it absorbed so much arcana.\n\nThen again... I do not want to slight our new tuskarr allies. I do have a wand that could dispel the magic...\n\nLet's speak with Toolk's mother, then decide what to do.", objectives = "" }
WordHunterWoW_QuestEN[67177] = { title = "WANTED: Gorger", description = "If you are going to be amongst the tuskarr, you would do well to lend a hand! \n\nAs of late, a beast we call Gorger has been making its home nearby. \n\nMore of its kind seem to be migrating to this area. This is something we can take advantage of.\n\nKill the Gorger and bring me its horns. We'll need them for building supplies to expand this outpost.", objectives = "" }
WordHunterWoW_QuestEN[67178] = { title = "White Eyes, Blue Dragon", description = "{class} can you make sure the match happens as fairly as possible?\n\nSetogosa is known for bending the rules to suit her whims. \n\nI would not wish to see Yumadormu lose due to cheating.", objectives = "" }
WordHunterWoW_QuestEN[67220] = { title = "10.0 [DNT] [GAMEPLAY TEST] - [SPAWNTRACKING] (JSS)", description = "", objectives = "" }
WordHunterWoW_QuestEN[67221] = { title = "A Head for Metal", description = "To fully utilize the potential of the Earth-Warder's forge, you must learn the basics of creating Obsidian Seared Alloy. Only then can you follow in the footsteps of Neltharion's greatest smiths.\n\nBring me a piece of Crystallized Draconium found deep within the Cindershard Seam. Then I shall gift you the knowledge you desire.", objectives = "" }
WordHunterWoW_QuestEN[67222] = { title = "Darkened Clouds", description = "The Primalists have infected Windsong Rise with their nonsense teachings. Our kin there are foolish to entertain their ideas.\n\nIf we assist with clearing this sacred ground of their presence, perhaps the other clans will come to our aid in time of need. Do you think you could assist?", objectives = "" }
WordHunterWoW_QuestEN[67295] = { title = "That's My Specialty", description = "So, you've started taking up a specialization, eh? 'Tis a glorious thing to have an exclusive skill you can call your own.\n\nAs a member of the Artisan's Consortium, I would be delighted to help you on your journey to honing your specialization.\n\nHave you a minute to listen to my words of wisdom, and perhaps learn something to help you on your adventures?", objectives = "" }
WordHunterWoW_QuestEN[67296] = { title = "Iskaara Tour", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[67297] = { title = "Iskaara Tour - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[67298] = { title = "The Wonders of the World", description = "My husband Thomas has gained many insights from exploring these primal lands.\n\nPerhaps following in his footsteps would similarly inspire you?", objectives = "" }
WordHunterWoW_QuestEN[67299] = { title = "Drakes be Gone", description = "The primalists have been ceaselessly attacking our camp with their drakes!\n\nWe've been able to keep them at bay with our shields, but we could use more aid in taking them out of the sky.\n\nUse one of our blasters to take those drakes down!", objectives = "" }
WordHunterWoW_QuestEN[67564] = { title = "Artisan's Courier", description = "Adventurer, are you headed into the Lifeshrine?\n\nWould you mind taking this invoice to Thomas Bright? He ordered a few custom-made bottles and our glassblower has finally returned with the price of materials required.\n\nHe should be just down the path there, likely gushing to some poor soul about how great his husband is...\n\nI am sure he will pay you for your time.", objectives = "" }
WordHunterWoW_QuestEN[67565] = { title = "Frostland Flyover", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[67566] = { title = "Frostland Flyover - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[67605] = { title = "Thundering Plains", description = "There is a great storm beast which wanders this ridge. Many a Shikaar hunter has attempted to take it down, only to fall to its ferocity.\n\nIf you wish for some hunting glory, you may attempt to bring down the beast. Bring back its horn as tribute.", objectives = "" }
WordHunterWoW_QuestEN[67606] = { title = "A Dryadic Remedy", description = "While you were gone, I heard from a dreamhare that one of the local ducklings is feeling rather down in the dumps. Luckily, I know exactly how to fix that!\n\nWhenever I'm feeling moody, I snack on something sweet and tasty! As an expert in cute, lovable creatures, I know that the same principle will surely apply here.\n\nThis particular duckling is fond of a local dessert known as a Tasty Hatchling's Treat. Won't you find one and bring it to the poor dear? It's the dryadic thing to do, after all!", objectives = "" }
WordHunterWoW_QuestEN[67700] = { title = "To the Dragon Isles!", description = "Great news, {name}! The spearhead of our expedition has made landfall in the Dragon Isles.\n\nThanks to the efforts of yerself and other Dragonscale Expedition members, we've established a protected landing site and made contact with the dragonflight's embassy.\n\nAre ye prepared to accompany us on our next voyage to the Dragon Isles?", objectives = "" }
WordHunterWoW_QuestEN[67722] = { title = "Break on Through", description = "Toddy and Naleidea are preparing to head out. Meet at the Sealed Titan Facility in Thaldraszus. Apparently they've made a breakthrough.\n\nBe sure to bring any pertinent information back for cataloging!", objectives = "" }
WordHunterWoW_QuestEN[67724] = { title = "The Fending Flames", description = "Kattigat and I came here to prove ourselves by stopping the Sundered Flame and recovering the Valthrux.\n\nNow we're stuck watching over this elf after she takes a few ice spider bites. We haven't even fought the Sundered Flame yet, and the spiders may do us in before we can!\n\nWe need to keep them at bay. \n\nThankfully, there's a natural way to repel them. Burning silk from their cocoons creates an aroma that repulses the spiders.\n\nGrab some silk and I'll throw it on the fire. It'll keep them away!", objectives = "" }
WordHunterWoW_QuestEN[67741] = { title = "Archive Ambit", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[67742] = { title = "Archive Ambit - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[67772] = { title = "The Trouble with Taivan", description = "Hello, friend. Welcome back to Maruukai. I am Selbekh, healer of Clan Teerai.\n\nAre you good with animals, {name}? Perhaps the influence of a newcomer is just what I need.\n\nTaivan here, while a very good companion, has become something of a burden on my clan. I'm afraid if we can't find a good use for him, I may have to send him away. Will you help me?", objectives = "" }
WordHunterWoW_QuestEN[67921] = { title = "The Hunting Hound", description = "Go and hunt the nearby beasts with your giant bakar. The bigger, the better. I will observe from here, and decide if he is worthy of Shikaar training. \n\nBe warned, I will only accept the best.", objectives = "" }
WordHunterWoW_QuestEN[68083] = { title = "Try Again, Taivan!", description = "Return to the Teerai and tell them that not even I can train Taivan to be a hunter. He simply does not have it in him.\n\nHe is the most un-ferocious bakar I have ever seen, and I bet he would even try to make friends with the wild game if we let him! Hah!", objectives = "" }
WordHunterWoW_QuestEN[68084] = { title = "The Gentle Giant", description = "If Taivan is really as \"un-ferocious\" as Jadar says he is, perhaps he'll be better suited as a herding bakar! \n\nThe Aylaag are expert argali shepherds, and aren't so proud that they require lavish gifts to help another clan. \n\nPlease send Taivan to Shepherd Tevatei at the Mallakh, a spot between two hills in the south-west where they train their bakar.\n\nOhn'ahra, please let this work. If it doesn't, I'm all out of ideas.", objectives = "" }
WordHunterWoW_QuestEN[68085] = { title = "Shaping a Shepherd", description = "You want me to train your bakar in shepherding? Well, that's certainly what we do here, but I've never trained one quite so BIG before...\n\nThe argali don't seem to be bothered by his presence, though, and they're very good judges of character. Trust me. \n\nI'm willing to give him a shot, but a herding bakar needs to not only be gentle, but smart, too. And if they aren't able to take charge of the herd, the argali won't obey them. It's harder than it looks! Go on and give it a try, I'll watch.", objectives = "" }
WordHunterWoW_QuestEN[68087] = { title = "Danger in Daruukhan", description = "I guess there's nothing to be done but send you and Taivan back to Maruukai. \n\nWait... who is that approaching? Not another stranger with a giant bakar, I hope!", objectives = "" }
WordHunterWoW_QuestEN[68639] = { title = "Prowling Polar Predators", description = "The species we've been sent to study is the frigidpelts.\n\nTheir hunting grounds have been tainted by ley lines. Arcane energies leech into the water and into the plants... and into prey species like the slyvern.\n\nBut unlike other organisms, the frigidpelts survive the process and gain power from it.\n\nThey also become aggressive--which is a problem. Engage a few, and I will take notes on their strength and aggression. \n\nMy report will help the Kirin Tor decide what to do for them.", objectives = "" }
WordHunterWoW_QuestEN[68640] = { title = "Sudden Isolation", description = "We used to trade frequently with the Uktulut tribe in the Waking Shores, but they haven't been sending or accepting shipments for months now. Our letters have gone unanswered. Naturally, we suspect the worst.\n\nTheir chieftain, Tutaqan, has always been the reasonable sort. Somewhat prone to strong emotions, but I can't imagine anything terrible could have happened under his leadership.\n\nCould you please check on them? If they need help, we'll happily provide.", objectives = "" }
WordHunterWoW_QuestEN[68641] = { title = "Mossing the Mark", description = "Poor girl...\n\nShe must have gotten sick after eating something tainted.\n\nLuckily, my grandfather was a druid and taught me how to treat arcane-based illnesses.\n\nI don't have all the components on me, but we can make do with what's around.\n\nFirst, I will need some drakmoss. It is a rare lichen that only grows on dragon bones.", objectives = "" }
WordHunterWoW_QuestEN[68642] = { title = "Needles to Say", description = "I want to help Sylvie, but I don't want to delay Cally any longer.\n\nTo give Sylvie the medicine, I need arcane-infused quills from the crystalpine. I'm sure they won't mind if you pluck a few off! \n\nAnd mind the bakar! They eat crystalpine and might get mad at you touching it. If you do have to defend yourself, you can collect some spines from them as well.\n\nBut... try not to do that, please.", objectives = "" }
WordHunterWoW_QuestEN[68643] = { title = "Vitamins and Minerals", description = "I suppose I should have expected that Steria would be upset at me asking you to fight animals...\n\nThere are of course alternative research methods.\n\nTake these vials and collect some water from the nearby ice crystals. \n\nI theorize that they contain minerals infused with ley crystal energy--and may be fueling the outbreak here.", objectives = "" }
WordHunterWoW_QuestEN[68644] = { title = "Sugar, Spice, and Everything Nice", description = "There! Now I have all I need for Sylvie!\n\nAnd just in time. I doubt she would have lasted much longer like this.\n\nBut... I need someone to help me. I'd ask Cally but... would you mind assisting me again?\n\nLet me know when or if you're ready, {name}.", objectives = "" }
WordHunterWoW_QuestEN[68794] = { title = "Ally of Dragons", description = "Your aid to the Dragon Isles has not gone unnoticed, {name}.\n\nThe Life-Binder herself wishes to show you something as a reward for your service to dragonkind.\n\nGo and speak to her at the top of the tower. All the Aspects await you.", objectives = "" }
WordHunterWoW_QuestEN[68795] = { title = "Skyriding", description = "One thing you may have already discovered about this place: the Dragon Isles are vast. \n\nSome of the drakes have an intense interest in exploring every corner and secret hiding place in this renewed land, even those places that are not readily reached from the ground. They are eager for a second set of eyes to aid them in their journey, and in trade will gladly bear a rider across the lands.\n\nSpeak with Lord Andestrasz, here in the Ruby Lifeshrine. He will explain more of what they intend.", objectives = "" }
WordHunterWoW_QuestEN[68796] = { title = "The Skytop Observatory", description = "Those are the basics of riding a drake! You are doing quite well.\n\nNow, I would like to introduce you to some of the others involved in this adventure. We have made a home for ourselves over at the Skytop Observatory.\n\nCelormu will be able to help guide you there. Speak to him when you feel ready to take to the skies!\n\nSee you there!", objectives = "" }
WordHunterWoW_QuestEN[68797] = { title = "A New Set of Horns", description = "Just as mortals do, dragons care very much about their appearance. Your drake is able to change as well, according to what you find and experience.\n\nSpeak to Glensera at the Rostrum of Transformation, and see for yourself!", objectives = "" }
WordHunterWoW_QuestEN[68798] = { title = "Skyriding Talents and You", description = "Obviously, it is not just Glensera and myself that are invested in these adventurers. Lithragosa is also excited to help you hone your dragonriding skills, and you have already met Celormu which is excellent.\n\nYour next stop is to speak to Lithragosa, who can show you what skills you can learn!", objectives = "" }
WordHunterWoW_QuestEN[68799] = { title = "Return to the Ruby Lifeshrine", description = "And this is just the beginning of your dragonriding journey! \n\nKeep your eyes open for new adventures and experiences throughout the Dragon Isles, and be sure to visit us in any of our outposts.\n\nFor now, return to Alexstrasza to continue your exploration in these lands.", objectives = "" }
WordHunterWoW_QuestEN[68863] = { title = "A Lost Tribe", description = "Hi, {name}!\n\nMurik wanted to talk to you about something real important back in Iskaara. You should go see what it is.", objectives = "" }
WordHunterWoW_QuestEN[69093] = { title = "A New Mystery", description = "<Doc Nanners looks out of breath as he hands you a letter inviting you back to the Dragonscale Expedition Basecamp. He eagerly tries to explain.>\n\nSealed door. Titan secrets. Yes?\n\n<Doc Nanners nods excitedly, awaiting your response.>", objectives = "" }
WordHunterWoW_QuestEN[69094] = { title = "Saving Centaur", description = "The treachery of the Nokhud knows no limits! Only craftsmen live in the village of Daruukhan. They stood no chance against the raiders.\n\nWe desperately need your help, {name}. The Nokhud are still nearby, and we must tend to the wounded!\n\nSearch the village, and carry any survivors you find to me. We will triage and stabilize who we can!", objectives = "" }
WordHunterWoW_QuestEN[69095] = { title = "Homeward Hound", description = "We have everyone stabilized, thanks to you and Taivan, but many of these villagers will need to heal for a while longer in Maruukai.\n\nWhy don't the two of you lead our train back? You are both the heroes of the day, after all!", objectives = "" }
WordHunterWoW_QuestEN[69096] = { title = "Taivan's Purpose", description = "Do you see that young one, sitting by themselves over on the bank of the stream?\n\n<She points to the northeast, where you see a young-looking Centaur staring at the water.>\n\nChimei lost both of their parents in the Nokhud attack. I have healed all of their physical wounds, but they have not eaten or said a word to anyone since we found them. They just sit and stare. \n\nThis is beyond my skills, and I am at a loss. Will you try to talk to them, {name}?", objectives = "" }
WordHunterWoW_QuestEN[69097] = { title = "A Vault Unsealed", description = "<Doc Nanners looks out of breath as he hands you a letter inviting you back to the Dragonscale Expedition Basecamp. He eagerly tries to explain.>\n\nLoud dwarf. Serious elf. Ready for you. Yes?\n\n<Doc Nanners nods excitedly, awaiting your response.>", objectives = "" }
WordHunterWoW_QuestEN[69855] = { title = "A Climber's Calling", description = "<Doc Nanners looks out of breath as he hands you a letter inviting you back to the Dragonscale Expedition Basecamp for training. He eagerly tries to explain.>\n\nFrom Big Jeb. Good friend. Climb now. Yes?\n\n<Doc Nanners nods excitedly, awaiting your response.>", objectives = "" }
WordHunterWoW_QuestEN[69862] = { title = "Save a Slyvern", description = "Now that she's healed, I think Sylvie wants to show us something. \n\nOur work isn't done yet, {name}! Let's see what's upsetting her.", objectives = "" }
WordHunterWoW_QuestEN[69869] = { title = "A Cataloger's Paradise", description = "<Doc Nanners looks out of breath as he hands you a letter inviting you back to the Dragonscale Expedition Basecamp for training. He eagerly tries to explain.>\n\nKind elf. Proud tiny-man. Many cameras. Yes?\n\n<Doc Nanners nods excitedly, awaiting your response.>", objectives = "" }
WordHunterWoW_QuestEN[69870] = { title = "Pictures with Purpose", description = "Pictures bring people together, {name}.\n\nOur catalogers are typically sent out in pairs for safety, and it has been lovely to see members of different factions and backgrounds working together in pursuit of knowledge on these incredible isles.\n\nOne such eager duo is currently charting one of the central rivers of the Waking Shores.\n\nIf you wish to aid our efforts, join them in cataloging the wildlife there.", objectives = "" }
WordHunterWoW_QuestEN[69888] = { title = "Unusual Suspects", description = "{name}, you're here. Good. Don't react, but our findings on the titan discs have just been stolen! Other than us, only the Sundered Flame know what we were up to in that facility.\n\nI need ye to take this device and scan some of the suspicious members that have joined us recently. Reveal the spy and recover the data if you can. We cannae allow it to fall into their hands!", objectives = "" }
WordHunterWoW_QuestEN[69896] = { title = "Disastrous Detour", description = "I knew joining the Dragonscale Expedition meant venturing into dangerous territory. But I was not expecting to fight off elementals!\n\nOur dig site at the Life Vault Ruins is in complete disarray! Stone monstrosities are rising up out of the ground! We called in an elementalist to consult, but I believe she will need all the help she can get.\n\nPerhaps you can help her? Our camp is just across the river.", objectives = "" }
WordHunterWoW_QuestEN[69897] = { title = "Behavior Analysis \"Homework\"", description = "I need to talk to someone who knows proto-whelps. Like the ones that live in the Wild Preserve! \n\nAre they as angry as the big ones? Do they bite or breathe fire at you?\n\nWhat if I... er... you petted a proto-whelp? Would they know that you're nice and trying to help them?\n\nI'm asking for science, of course. Tyrgon always tells us to test our hippa... no... hypo... hmph! Hyppotatotoast... ugh! THEORIES!\n\nI think they would like petting and it would make them feel good. Could you test that for me?", objectives = "" }
WordHunterWoW_QuestEN[69898] = { title = "Scientific Meat-thod", description = "So, I have, uh, more homework... Professor Tyrgon's lessons are super tough! He wants us to find out what proto-whelps, uh, eat! Yeah...\n\nI already know the answer! It's riverbeast meat! \n\nCan you bring me a piece of riverbeast meat? Some riverbeast meat would be a great \"visual aid\" for my project.\n\nBut it has to be a REALLY good piece, ok? Like... the ones from Pudgy Riverbeasts. One like a momma proto-drake would give their whelp to make them strong because, uh, it will make Mister Tyrgon happy.", objectives = "" }
WordHunterWoW_QuestEN[69899] = { title = "Secret Research", description = "I know.. I am acting weird. I'm sorry!\n\nYou probably guessed I am not being truthful.\n\nI can tell you my secret... if you like. But you will have to promise not to tell the adults!", objectives = "" }
WordHunterWoW_QuestEN[69900] = { title = "Identifying the Source", description = "Judging by what the children have said, we might have a primalist prowling the Wild Preserve.\n\nThis calls for immediate investigation.\n\nAccording to what other researchers have observed, Primalists like to steal eggs and whelps to infuse them with power and corrupt them. Those that don't acclimate to the process suffer a slow death... not that the primalists seem to care...\n\nWe need them out of the Preserve. Attend to that, and I will try to distract the children. They must not know of this.", objectives = "" }
WordHunterWoW_QuestEN[69901] = { title = "Bring In the Expert", description = "Did Iyali say how long this creature has been suffering? If it's too injured to eat, we need to treat it quickly.\n\nNormally a Dragonscale Expedition camp would have everything I need to help this whelp, but getting supplies to the \"frontier\" here on the Dragon Isles has proven tricky. There have been significant delays in our supply routes.\n\nBut, fear not. The land itself will provide! If you bring me Sunlight Flowers, I can craft a soothing balm that will calm the drake so I can heal it.", objectives = "" }
WordHunterWoW_QuestEN[69902] = { title = "Theory in Practice", description = "{name}, I require your assistance...\n\nI hope no one was expecting me to craft, subdue the whelp, heal, and teach these children all at once! Multitasking like that is certainly overrated. \n\nNow, you can start by using those flowers. I'll need a couple minutes to prepare myself to heal the proto-whelp. \n\nHopefully, the children will find this incident... instructional.", objectives = "" }
WordHunterWoW_QuestEN[69904] = { title = "Suspiciously Quiet", description = "Can you spare a minute, {name}? I haven't heard from my two apprentices, Scrumpy and Tucky, in some time. \n\nThis is concerning. \n\nI sent them to fetch us supplies for the inn. They couldn't have strayed too far...\n\nPlease find them, but I warn you... They're... quite the handful.", objectives = "" }
WordHunterWoW_QuestEN[69910] = { title = "Where is Wrathion?", description = "How unusual.\n\nEbyssian told us that Wrathion would be awaiting our arrival along with an ambassador for Alexstrasza the Life-Binder, Queen of the Dragons.\n\nIt isn't like a dragon to break a promise.\n\nAt least this eager drakonid is here to greet us. Would you kindly inquire into when the others shall arrive?", objectives = "" }
WordHunterWoW_QuestEN[69911] = { title = "Excuse the Mess", description = "I wish I knew more about how to welcome you to the Dragon Isles, but I'm only the sentry.\n\n<Sendrax motions to the tower behind her.>\n\nYou could try talking with Ambassador Fastrasz in the visitor center. He might be able to answer more of your questions before the dragons arrive.\n\nMind your step in there. He was clearing out rubble last I saw.", objectives = "" }
WordHunterWoW_QuestEN[69912] = { title = "My First Real Emergency!", description = "<Sendrax looks puzzled.>\n\nI have never known the majordomo to be late to anything, much less THIS late to something THIS important.\n\nMost unusual...\n\n<Sendrax perks up at a thought.>\n\nI could use my emergency signal flare to alert them to your arrival. Then they would come rushing to greet you immediately!\n\nI've never fired my emergency signal flare before, though...", objectives = "" }
WordHunterWoW_QuestEN[69914] = { title = "The Djaradin Have Awoken", description = "I wish we'd time for more pleasant introductions, but we can't all be Chronormu, can we?\n\nI am Selistra, majordomo to Alexstrasza the Life-Binder, Queen of the Dragons.\n\nQueen Alexstrasza asked me to convey her kindest regards and escort you to her at the Life Pools.\n\nBut I'm afraid I must ask for your assistance before we go meet her.\n\nOur ancient rivals, the djaradin, have awoken from their slumber under the earth and have already assaulted a nearby outpost!", objectives = "" }
WordHunterWoW_QuestEN[69915] = { title = "Targeted Ads", description = "Hi, hi, hi! You looking for a gig?\n\nWe're doing a BIG opening sale for our new Crafting Order service, and we need to draw attention! But the wind took my flyers and I think some of the local goats ran off with them.\n\nCould you get my flyers back?", objectives = "" }
WordHunterWoW_QuestEN[69918] = { title = "Shaking Our Foundations", description = "Djaradin stonebinders are threatening to break the very foundations of the Citadel! They have to be stopped!\n\nWe haven't even had a chance to reclaim the Citadel as our own and yet it might crumble beneath us. We can't let that happen.\n\nDo what you can, {name}... by that I mean kill them!", objectives = "" }
WordHunterWoW_QuestEN[69919] = { title = "A Craft in Need", description = "You seem like a skilled crafter. Would you like to fill some crafting orders for fellow adventurers and get rich, rich, rich?\n\nI'll tell you the rules of working with the Artisan's Consortium, then you can pick up Crafting Orders at any crafting station on the Dragon Isles!", objectives = "" }
WordHunterWoW_QuestEN[69923] = { title = "A Primal Threat", description = "Raszageth has wasted no time building up her Primalist forces.\n\nThe Kirin Tor have detected massive storms being unleashed at key points across Kalimdor and the Eastern Kingdoms.\n\nThe Primalists are unleashing the elements to add to their strength. It seems they plan to cause chaos not only in the Dragon Isles, but in the lands of the Alliance and Horde as well.\n\nSeek out the enemy and study their methods. We have to stop them before it's too late.", objectives = "" }
WordHunterWoW_QuestEN[69925] = { title = "Calming the Storms", description = "These Primalists are relentless, unleashing elemental devastation across the Eastern Kingdoms and Kalimdor.\n\nYou must show the same determination, {name}. It is the only way to stop them.\n\nFind their next incursion, remove the enemies within the primal storm area before it is too late and foil their efforts.\n\nWe must protect Azeroth!", objectives = "" }
WordHunterWoW_QuestEN[69926] = { title = "Becca Black and the Seven Gnomes", description = "The djaradin have ransacked the Obsidian Citadel and stolen a number of valuable artifacts.\n\nWrathion has tasked us to recover every item taken from the Citadel. My team has located several in the area, but we could use your help.", objectives = "" }
WordHunterWoW_QuestEN[69932] = { title = "Every Life Counts", description = "Making potions for Gelikyr means that I don't have time for my other duties.\n\nA duck landed in my garden with a broken rib. I've tended to the wound, but her dressing needs replacing. And since you're so eager to help...\n\n<Szareth shoves a list of ingredients into your hand.>\n\nThis is what you'll need. Bring the rest to me.", objectives = "" }
WordHunterWoW_QuestEN[69933] = { title = "Curiosity's Price", description = "Look across the ravine, {race}. Primalists attacked Gelikyr Post days ago, and the battle still rages.\n\nThose people need salves and stitching. I can make it for them, but my ingredients are running low. Since you've chosen to intrude upon my home, consider yourself volunteered.\n\nGo to my garden and find the largest vine you can. Snap it from the root, then bring it to me.", objectives = "" }
WordHunterWoW_QuestEN[69934] = { title = "Bleeding Hearts", description = "The potions are ready--now to deliver them.\n\nTake one crate to a small cave in the ravine below us. No one will be there to accept it, but you can trust it will be used well.\n\nTake another crate to the infirmary in Gelikyr Post. An old friend tends to the patients there.\n\nI... realize this is not your duty. Nor is it really mine. But you've been surprisingly helpful, and this medicine could save lives.", objectives = "" }
WordHunterWoW_QuestEN[69936] = { title = "Zambul, Head Vandal", description = "Good work. Those desecrators cannot force any more of my ancestors to fight for them. But the brute yelling out their orders must be handled.\n\nThat is their overseer, Zambul. He must be stopped.\n\nTake him down.", objectives = "" }
WordHunterWoW_QuestEN[69944] = { title = "Chasing Storms", description = "Well, that wizard certainly knows how to make an entrance, doesn't he?\n\nWe won't be able to set sail until someone gets those elemental storms under control.\n\nCheck-in with Storm Huntress Suhrakka. She's leading the expedition efforts to investigate the storms and can help outfit you with whatever gear you need.\n\nWhile you handle that, I'll coordinate the rest of the preparations. At least it'll give me some time to read a few more volumes on dragon history before we set sail.", objectives = "" }
WordHunterWoW_QuestEN[69946] = { title = "The Master of Their Craft", description = "While I was traveling through these plains, I met an old centaur in a cave up north. They had clearly mastered their craft and had wisdom to spare.\n\nThey helped me understand the knowledge I had gained from the Dragon Isles.\n\nIf you're curious about specializing in your profession, seek out the wisdom of this master. Khadin was their name, of Clan Teerai.", objectives = "" }
WordHunterWoW_QuestEN[69957] = { title = "Tyrhold Trial", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[69958] = { title = "Tyrhold Trial - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[69965] = { title = "Quality Assurance", description = "Are you looking for work, {class}?\n\nI represent a new trade company, the Artisan's Consortium, which matches artisans and clients through our crafting orders network.\n\nThe Dragonscale Expedition placed an order for some enchanted mining tools. The tools are crafted, but we would like to test them before completing the order.\n\nWe will pay you for your services, of course.", objectives = "" }
WordHunterWoW_QuestEN[69979] = { title = "A Worthy Hunt", description = "Wisdom is not gained. It is earned. If you wish to prove yourself worthy, you will do so in the manner of my people: learning as we act.\n\nFind and hunt Thousandmile, the Elderbull, he who has escaped the hunt for generations.\n\nFrom this, you will gain the wisdom you seek.", objectives = "" }
WordHunterWoW_QuestEN[69980] = { title = "Seavine: Fisherman Tinnak's Gift", description = "<You can see the poor fisherman's spectral hand is still gripping a thread woven of a very strong, yet light, kelp. Nunvuq in Iskaara might find a use for that.>", objectives = "" }
WordHunterWoW_QuestEN[69981] = { title = "Customer Satisfaction", description = "Hey {class}, got a tick to help with something?\n\nSome of our favorite customers placed recrafting orders through the Artisan's Consortium, but we haven't heard back from them.\n\nIf you run into them, can you check to make sure they're satisfied with their purchases? Gotta keep customers happy, happy, happy!", objectives = "" }
WordHunterWoW_QuestEN[69983] = { title = "Flamecarved Bone", description = "<Mysterious djaradin runes carved into a bone. Talonstalker Kavia might want to see this.>", objectives = "" }
WordHunterWoW_QuestEN[69984] = { title = "Gold-Banded Dragon Tooth", description = "<You have discovered the remnant of a fallen dragon. Exadria might want to see this.>", objectives = "" }
WordHunterWoW_QuestEN[69992] = { title = "Sigil of Storms", description = "<Someone with great knowledge of magic may be interested in studying a find such as this.>", objectives = "" }
WordHunterWoW_QuestEN[70025] = { title = "Artisan's Supply: Draconium Sickle", description = "You look like someone with nothing to do. How's about employment?\n\nI have a crafting order to fill for the Artisan's Consortium for a draconium sickle. Now I could easily take care of this, but as an apprentice I think it makes more sense for you to take this one on.\n\nCraft the sickle and bring it to the Ruby Lifeshrine, a draenei named Haephesta will pay you for it.", objectives = "" }
WordHunterWoW_QuestEN[70026] = { title = "Artisan's Supply: Lava Beetles", description = "Are you looking for work, herbalist? The Artisan's Consortium asked me to gather some beetles for their customers.\n\nThe land is plentiful, but not so much that I can simply step away and be back with their request.\n\nBut if you venture out, perhaps you could collect a few beetles on your way?", objectives = "" }
WordHunterWoW_QuestEN[70027] = { title = "Artisan's Supply: Surveyor's Cloth Bands", description = "Are you looking for work, tailor? The Artisan's Consortium asked me to craft some wristbands for their customers.\n\nWhile I appreciate that these explorers are trying to involve themselves with our weaving, I do not have time for such requests.\n\nPerhaps you would be interested in taking on this project?", objectives = "" }
WordHunterWoW_QuestEN[70028] = { title = "Artisan's Supply: Salt Deposits", description = "Are ye looking for work, miner?\n\nI was talkin' to Haephesta an' she says the Artisan's Consortium is needin' salt for their customers.\n\nNoo I'd do it meself, but, well, I dinna want to.\n\nBe a pal and fetch 'em for 'er, eh?", objectives = "" }
WordHunterWoW_QuestEN[70029] = { title = "Artisan's Supply: Runed Serevite Rods", description = "You seem to have a magical touch, enchanter. Would you be able to help with an order I've got?\n\nThe Artisan's Consortium has requested several rods made of Serevite for a customer, but enchanting rods aren't quite my specialty.\n\nIf you're willing, Haephesta at the Ruby Lifeshrine will compensate you for your time and effort!", objectives = "" }
WordHunterWoW_QuestEN[70030] = { title = "Artisan's Supply: Quality-Assured Optics", description = "Ah, an engineer! Excellent timing.\n\nI've got some schematics to fix, but some tall lady came by asking for a set of optics.\n\nYou know how to make those, right?\n\nTake 'em to the Ruby Lifeshrine when you have 'em crafted. I think she said she was with the Artisan's Consortium or something.", objectives = "" }
WordHunterWoW_QuestEN[70031] = { title = "Artisan's Supply: Chef's Smooth Rolling Pin", description = "Are you looking for work, scribe?\n\nI received an order from a company called the Artisan's Consortium.\n\nIt seems like a simple enough task for an apprentice crafter such as yourself.", objectives = "" }
WordHunterWoW_QuestEN[70032] = { title = "Artisan's Supply: Jeweler's Specs", description = "Are you looking for work, jewelcrafter? The Artisan's Consortium asked me to craft some spectacles for their customers. \n\nMe! Like I have time for this.\n\nYou can do it, yeah?", objectives = "" }
WordHunterWoW_QuestEN[70033] = { title = "Artisan's Supply: Pioneer's Leather Boots", description = "Are you looking for work, leatherworker? The Artisan's Consortium asked me to craft some boots for their customers.\n\nClearly they don't understand my popularity. Do you know how many explorers have come through today complaining of holes in their shoes?\n\nIf you have the time, take these measurements. Perhaps this Artisan's Consortium could be a promising business opportunity for you.", objectives = "" }
WordHunterWoW_QuestEN[70034] = { title = "Artisan's Supply: Salamanther Scales", description = "Are you looking for work, skinner? The Artisan's Consortium asked me to gather the scales of a salamanther for their customers.\n\nI may be an artisan, but I am no one's errand child!\n\nBut... ah, perhaps you could find some?", objectives = "" }
WordHunterWoW_QuestEN[70040] = { title = "Tumbling Through Time", description = "When the magic of Bronze and Infinite collided, it sent Chronormu and Eternus into an uncontrolled tumble through time.\n\nAs they fall, they rip the fabric of time itself, sending out countless ripples across time and space. We must locate them and bring them back. Only then will we be able to stop any further damage. I see that you will be the one to stop Chronormu's fall.\n\nI would ask that you to gather the allies you will need to save Chronormu, while I focus on her magic.", objectives = "" }
WordHunterWoW_QuestEN[70041] = { title = "The Storm-Eater's Fury", description = "Raszageth is attempting to rip all the arcane magic out of the tower so she can destroy it!\n\nKalecgos is doing what he can to hold her back, and I am using my magic to try to replenish the ley energy.\n\nI fear we will not last much longer. As we speak, more Primalists make their way up here to overwhelm us!\n\nTake my modified Arcane Disc. Hold off the incoming Primalists... and let us hope for a miracle.", objectives = "" }
WordHunterWoW_QuestEN[70042] = { title = "Opportunities Abound", description = "Ya scared me, thought I was nabbed!\n\nLook at all the brave explorers ready to conquer the Dragon Isles... packs bulging with tools and equipment.\n\nWe could get rich here!\n\nCheck around see if you can grab a few items, and I'll cut you in on the profits.", objectives = "" }
WordHunterWoW_QuestEN[70048] = { title = "A Primal Threat", description = "Raszageth has wasted no time building up her Primalist forces.\n\nThe Kirin Tor have detected massive storms being unleashed at key points across Kalimdor and the Eastern Kingdoms.\n\nThe Primalists are unleashing the elements to add to their strength. It seems they plan to cause chaos not only in the Dragon Isles, but in the lands of the Alliance and Horde as well.\n\nSeek out the enemy and study their methods. We have to stop them before it's too late.", objectives = "" }
WordHunterWoW_QuestEN[70049] = { title = "Calming the Storms", description = "These Primalists are relentless, unleashing elemental devastation across the Eastern Kingdoms and Kalimdor.\n\nYou must show the same determination, {name}. It is the only way to stop them.\n\nFind their next incursion, remove the enemies within the primal storm area before it is too late and foil their efforts.\n\nWe must protect Azeroth!", objectives = "" }
WordHunterWoW_QuestEN[70050] = { title = "Chasing Storms", description = "So the handsome fellas are sendin' ye on a wee adventure, eh?\n\nThat's fine. The expedition won't be able to set sail until someone gets those elemental storms under control anyway.\n\nCheck-in with Storm Hunter William. He's leading the expedition efforts to investigate the storms and can outfit ye with whatever gear you need.\n\nI'll coordinate the rest of the preparations here while ye have all the fun out there.\n\nYe'll owe me one, though!", objectives = "" }
WordHunterWoW_QuestEN[70051] = { title = "Cliffside Circuit", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[70052] = { title = "Cliffside Circuit - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[70055] = { title = "Sigil of Storms", description = "<Someone with great knowledge of magic may be interested in studying a find such as this.>", objectives = "" }
WordHunterWoW_QuestEN[70058] = { title = "Friend on the Mend", description = "Happy Duck got hurt while we were flying around... He was doing so good and then I... I hit a tree!\n\n<Lillistrasza gestures mournfully at the damaged duck plushie on her head.>\n\nHis stuffing is falling out! His feathers are all bent! One of his eyes is gone! Noooo!\n\nYou can help fix Happy Duck, right?", objectives = "" }
WordHunterWoW_QuestEN[70059] = { title = "Academy Ascent", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[70060] = { title = "Academy Ascent - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[70061] = { title = "Training Wings", description = "The dragons were gone from the Isles for quite some time, {name}. To tell the truth... some of our skills have atrophied as they were passed down from generation to generation.\n\nThese whelps should be easy to teach, yet we are having some trouble wrangling them.\n\nSay.\n\nI have seen that even Majordomo Selistra trusts you with the most crucial tasks. Would you lend us your aid and help one of our young?", objectives = "" }
WordHunterWoW_QuestEN[70062] = { title = "Some Call Me Bug Catcher", description = "Ah, young {race}, I could use your help. I have raised generations of life here. \n\nNone more my favorite than the ducklings. But my body has grown old and weak... still that does not stop the cycle.\n\nI need you to catch food for my brood.", objectives = "" }
WordHunterWoW_QuestEN[70069] = { title = "Others Call Me Duck Herder", description = "My days grow shorter... Still my duties are not done. \n\nThe brood should all be by the creek. I leave them there hoping they will grow more independent. Soon they will have to fend for themselves.\n\nToday they will rely on you. Please bring them the food you caught, and then the ducklings to me. Be wary of Pilot, she is always jumping off something.", objectives = "" }
WordHunterWoW_QuestEN[70070] = { title = "But... I Am the Hero of Ducks", description = "Hold on... there is something...\n\n<Gracus looks around.> \n\nFirequackers! The boy must have gone down the river again! No matter how often I tell him, he always tries to play with the hornswogs!\n\nI need you to go check on him. I hope he didn't get swallowed again.", objectives = "" }
WordHunterWoW_QuestEN[70122] = { title = "Explorers in Peril", description = "Don't mistake the expedition's scholarly pursuits as timidness, {name}.\n\nWe are not recluses studying books in far-off towers.\n\nWe are adventurers, hunting down knowledge first-hand in every corner of Azeroth!\n\nThat same passion for adventure often leads us into the path of perils and hazards, and a few expedition members have bitten off a little more than they could chew...\n\nBut, hey, the danger makes it more fun!", objectives = "" }
WordHunterWoW_QuestEN[70123] = { title = "Primal Pests", description = "<Azurathel glances suspiciously at the proto-dragons lurking on the ridge behind him.>\n\nI'd swear that those proto-dragons edge closer to camp every time I turn my back...\n\nThose are not the dragons Wrathion invited us here to meet.\n\nProto-dragons are ruthless predators who cannot be reasoned with. We must be ruthless in return.\n\nCull their numbers to keep their ambitions in check, or this expedition will be over before it begins.", objectives = "" }
WordHunterWoW_QuestEN[70124] = { title = "Practice Materials", description = "The proto-drakes here are unlike any I've seen before.\n\nTheir scales appear to be naturally flame-resistant, stronger than steel, and don't lose flexibility in the process. Incredible.\n\nThe artisans are clamoring to get their hands on some to work with.\n\nStart with the whelps. The smaller scales should be more pliable until we've mastered our techniques with 'em.", objectives = "" }
WordHunterWoW_QuestEN[70125] = { title = "Where is Wrathion?", description = "Hm, wonder where Wrathion is?\n\nHe said he'd be here waitin' for us with an ambassador for Alexstrasza the Life-Binder, Queen of the Dragons.\n\nIt does nae seem like a dragon to break a promise.\n\nWell! At least this eager wee drakonid is here to welcome us. Can you talk to 'em and find out when the others are gonna arrive?", objectives = "" }
WordHunterWoW_QuestEN[70126] = { title = "A Finishing Touch", description = "Ah, {name}, good to see you. \n\nYou've been an exceptional help for the Artisan's Consortium, and to Thomas and myself personally. Thank you.\n\nThere is one more thing you should know as a crafter, and that's building a rapport with your clients.\n\nI filled a crafting order for a customer today. Could you talk to him for me? Try to convince him to come to me for his future crafting needs. Remind him that he needs to come to me personally if he wants high-quality goods.", objectives = "" }
WordHunterWoW_QuestEN[70129] = { title = "Toejam the Terrible", description = "You're right, I'm not strong enough to take on this yeti... not alone! \n\nBut you're here!\n\nThe lair of the evil yeti, Toejam the Terrible, is just ahead. This cave is... big. Not scary! Maybe a little scary. \n\nCould you go in there and soften him up a bit? I'll... I'll be right behind you!", objectives = "" }
WordHunterWoW_QuestEN[70132] = { title = "Stay a While", description = "<The old dwarf doesn't react to your presence as you approach. As he gazes over the landscape, a deep frown is set in his face. It's a pleasant view. It might be nice to take a break and watch the landscape.>", objectives = "" }
WordHunterWoW_QuestEN[70134] = { title = "Memories", description = "Thank you for listening to me, young one. I have a favor to ask. \n\nDon't worry. No more stories.\n\nWhen we left this place, I left a... time capsule of sorts. Would you... would you be able to retrieve it for me? We left it at the bottom of the Ruby Life Shrine, hidden behind one of the pillars.\n\nI hid it with a sigil. If you activate it, you should see my time capsule.", objectives = "" }
WordHunterWoW_QuestEN[70135] = { title = "Encroaching Elementals", description = "The crafters, artisans, and explorers of the Dragonscale Expedition are ill-suited to the vigors of battle.\n\nBut not you and I, {name}.\n\nHere in the Dragon Isles, let us use that strength to protect those who can't protect themselves.\n\nClear out the elementals encroaching from the north, so that the expedition can focus on their noble pursuits.", objectives = "" }
WordHunterWoW_QuestEN[70136] = { title = "Haven't Got Time For the Pain", description = "Ugh... One moment...\n\nMy first assignment... Unstable temporal energy seeping into the forest... Affecting the wildlife... Need to assess the impact and collect that magic for the Timewalkers...\n\n<Zera shakes her head a moment.>\n\nI was examining a pack of vorquin when I was attacked by a crazed bear overflowing with time magic. It caught me off guard. I barely escaped.\n\nCould you find my missing gear for me, {class}? Uh, you might also have to deal with that bear.", objectives = "" }
WordHunterWoW_QuestEN[70139] = { title = "Where There's a Ward, There's a Way", description = "This reservoir used to be protected by three warding stones placed by Tyr. \n\nThey were meant to stabilize the elemental magic that is prevalent in the Dragon Isles. \n\nWhen you woke me, I sensed damage done to the west ward. I fear the Primalists may have done this to all of them. \n\nStill, we must assess the damage done in order to figure out what we should do next.", objectives = "" }
WordHunterWoW_QuestEN[70148] = { title = "Without Purpose", description = "Could I have a moment of your time? \n\nI'm worried about another dracthyr that passed through here. He asked my associates and me all kinds of questions, but seemed... disappointed with our answers.\n\nHe called himself \"Talon Ethrethi\". I believe that makes him quite junior amongst your ranks?\n\nI got the sense that he could use a hand. Mind helping me keep the peace?\n\nI saw him talking with Kholmar over there.", objectives = "" }
WordHunterWoW_QuestEN[70154] = { title = "A Gateway to Somewhere", description = "The enchantment will protect us from the unstable energy contained within.\n\nI will open the way to the nearest stone. \n\nOnce you pass through, stay close. I shall need your assistance when we arrive to power up the device.", objectives = "" }
WordHunterWoW_QuestEN[70155] = { title = "Look, Listen, and Breathe", description = "Hail, {race}. Few stop to say hello, let alone stay for a time. Most are in a rush to their next destination.\n\nWould you like to fish with me?", objectives = "" }
WordHunterWoW_QuestEN[70156] = { title = "An Ancient Awakening", description = "The waygate sits just behind me. There is no way to tell how long we have until the waning enchantment on this vessel fades, or even worse, breaks.\n\nThat amount of unstable energy being released could be catastrophic. \n\nShall we continue?", objectives = "" }
WordHunterWoW_QuestEN[70157] = { title = "Garden Gallivant", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[70158] = { title = "Garden Gallivant - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[70159] = { title = "A Taste of Home", description = "Oh, finally! Another dracthyr to lend a hand.\n\nMy brother and I have been trying to cook up some rations to eat, but...\n\n<Scaralesh gestures to his surroundings.>\n\nEverything is so different around here. It's hard to find the same ingredients we used to cook with.\n\nBut we can adapt. Go ask the Horde if they have anything we can substitute for vegetable matter, protein, and emulsifying fluid. Then we'll really have a meal.", objectives = "" }
WordHunterWoW_QuestEN[70161] = { title = "Caverns Criss-Cross", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[70163] = { title = "Caverns Criss-Cross - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[70164] = { title = "A Tinker's Chance", description = "If you have a moment, {name}, I am close to a breakthrough!\n\nAfter the creche collapsed, I lost more than my ability to fight. I lost my identity as a dracthyr. Perhaps you can understand.\n\nI have always enjoyed putting things together and taking them apart, so Expedition seemed like a good fit for me. But this artifact is giving me some trouble.\n\nWould you ask Phosildral and Sibrit to review my notes? I want to prove I am a capable tinker... to them and to myself.", objectives = "" }
WordHunterWoW_QuestEN[70166] = { title = "The Joy of Painting", description = "Do you like my collection? These are all the work of the greatest painter that ever lived, Hudson.\n\nThey're rare and probably valuable--he's a recluse and hasn't painted anything in awhile. Oh, but I'd love to meet him... Or to learn from him!\n\nYou... seem like the bold type. Would you find him for me? H-here! Take some of my work with you. Maybe he'll be impressed!\n\nOr maybe he'll think I'm terrible... oh dear.", objectives = "" }
WordHunterWoW_QuestEN[70168] = { title = "Sad Little Accidents", description = "You came all this way... I'm sorry.\n\nMy dear Hudson used to love painting. It was his life! I don't know what's caused this block. \n\nA few weeks ago on his way back from a painting trip, he took all his unfinished paintings and threw each away in a fit of rage. \n\nPlease, traveler, if you don't mind... could you find them? They may just give him back the spark he needs. \n\nHudson does not shy away from dangerous places to find the best vistas. I hope you are prepared.", objectives = "" }
WordHunterWoW_QuestEN[70169] = { title = "Even Trees Need Friends", description = "I know you and Ran are simply trying to be helpful. \n\nI don't think there's any helping me. My spark--my will to paint--is simply... gone. \n\nBut Ran is right. I owe you at least to try.\n\nBring this budding artist friend of yours to me.", objectives = "" }
WordHunterWoW_QuestEN[70170] = { title = "Beat the Demons Out of It", description = "He can be very stubborn, I'm afraid.\n\nBut I can't just give up on him. We'll just have to try again! \n\nThere are more paintings still out there he threw out. These were in even more dangerous locations, so I hope you are up for the challenge!", objectives = "" }
WordHunterWoW_QuestEN[70171] = { title = "Happy Little Accidents", description = "<Ranpiata's eyes look damp.>\n\nIs it me? Am I the reason he has lost his spark?\n\nHe says he loves me, but... you heard how not painting makes him feel.\n\nI want what is best for him. If he is better off... I will go. \n\nThere is one last piece he threw away. The last thing he tried to draw before giving up. \n\nI could not bear to see it go. I hid it away in our home. Please... bring it to him... as a memento.", objectives = "" }
WordHunterWoW_QuestEN[70174] = { title = "The Shikaar", description = "Sansok Khan is the most skilled hunter in our clan. Though she cannot hear, she proved her capabilities time and time again as both a hunter and a leader.\n\nShe is a mentor to us all, a trusted leader, and a fierce defender of the Maruuk.\n\nIt is an honor for you to speak with her.", objectives = "" }
WordHunterWoW_QuestEN[70175] = { title = "Broken Banding", description = "<This might be something Emila Bellocq is looking for.>", objectives = "" }
WordHunterWoW_QuestEN[70178] = { title = "Expedition Supply Kit", description = "Explorer, your discoveries have been invaluable.\n\nThere is even more out there to uncover and we have the tools to help you do it.\n\nCome back to the Dragonscale Basecamp and gear up using the Expedition Supply Kit.", objectives = "" }
WordHunterWoW_QuestEN[70179] = { title = "A Two for One Deal", description = "Greetings, adventurer! Say, you look like a capable person. Could you give me a hand?\n\nAzkra and I are charged with watching over this tower, which is in what I like to call \"an exciting state of pre-renovation.\" My problem is as we started repairs, the local earth elementals attacked us! \n\nSo I thought \"Zefren, why not take care of the earth elementals and get some building materials at the same time?\" Which is where you come in! Could you help?", objectives = "" }
WordHunterWoW_QuestEN[70180] = { title = "Jump-Start? Jump-Starting!", description = "Some folks in the city claim this here device was created by the legendary Titan Watcher Tyr. \n\nProblem is we can't get it to work! We tried all the usual tricks, dissemblin', gyroscopin', a little mild electrocution. None of it sides the electrocution worked. Actually... I just had a great idea.\n\nSee that gyrocopter over there? Hop in and let's see if we can give this titan thing a little more... juice.", objectives = "" }
WordHunterWoW_QuestEN[70181] = { title = "First Challenge of Tyr: Finesse", description = "<As you approach, the inscription on the statue emits a faint glow.>\n\n\"Wield the Keeper's power and carry its light to a better future for us all.\"", objectives = "" }
WordHunterWoW_QuestEN[70182] = { title = "The Sweet Taste of Victory", description = "There is great potential in small things. The Bottled Essence may feel light as a feather, but it holds immense power. \n\nTake it to the Engine of Innovation.", objectives = "" }
WordHunterWoW_QuestEN[70185] = { title = "Mysterious Beast", description = "<You find a large pawprint sunk into the dirt. Looking around, none of the nearby creatures have paws, let alone of that size.\n\nPerhaps the centaur will be impressed if you hunt this great beast.>", objectives = "" }
WordHunterWoW_QuestEN[70195] = { title = "Taken By Storm", description = "According to reports, the Nokhud were accompanied by an outsider wielding never-before-seen magic. This outsider tore through our ranks like a tempest. \n\nIf the Nokhud have allies who can wreak this much havoc, we must find out as much as we can about them.\n\nI have sent my ohuna, Altan, to find this outsider. She has not flown back, and I am concerned. {name}, can you search for clues about this outsider and see what has become of Altan?", objectives = "" }
WordHunterWoW_QuestEN[70197] = { title = "The Call of the Isles", description = "Are ye ready for the adventure of a lifetime? I know I sure am!\n\nOur allies have gathered and supplies are loaded. So what're you waiting for?\n\nMeet me at the Stormwind docks. It's time to set sail for the Dragon Isles!", objectives = "" }
WordHunterWoW_QuestEN[70198] = { title = "The Call of the Isles", description = "Our allies gather in Durotar. This is a very exciting time!\n\nJoin us, {name}! It's time to set sail for the Dragon Isles!", objectives = "" }
WordHunterWoW_QuestEN[70204] = { title = "Golden Claw", description = "<This might be something Emila Bellocq is looking for.>", objectives = "" }
WordHunterWoW_QuestEN[70207] = { title = "Tail Fragment", description = "<This might be something Emila Bellocq is looking for.>", objectives = "" }
WordHunterWoW_QuestEN[70210] = { title = "Tradition Not Forgotten", description = "One tradition for the Aylaag as we stay at this camp is for our members to make the pilgrimage to the Eternal Kurgans to ask for journeys safe from that which plagued our ancestors. The presence of the Nokhud has made this pilgrimage perilous.\n\nIf you do not mind, I would ask you would uphold our tradition for us.", objectives = "" }
WordHunterWoW_QuestEN[70211] = { title = "Stomping Explorers", description = "The influx of explorers to the Dragon Isles isn't letting up anytime soon. We need to replenish your stock of Explorer's Plate Boots. Even serevite can't withstand what is being asked of these boots. Get to work and see me when you have finished the job.", objectives = "" }
WordHunterWoW_QuestEN[70215] = { title = "Curiosity is Key", description = "My hesitation to discuss these symbols was not for a lack of trust in you, but rather the unknown nature of these symbols and the stones upon which they reside.\n\nYes, stones. Multiple, in fact. Scattered across the Isles.\n\n<Warpcaster Delandra glances at you. A hint of curiosity and excitement glows in her eyes.>\n\nYou did not know.\n\nVery well. Your persistence and willingness to seek me out shows that you are keen to understand your recent discovery. Perhaps it is time we discuss this at length.", objectives = "" }
WordHunterWoW_QuestEN[70220] = { title = "Shady Sanctuary", description = "We must inform the rest of the green dragonflight that the barrier to the Ancient Bough is under threat. Gerithus and I have much to discuss.\n\n{name}, I will place my mark upon you. The other dragons who see it will know that you are my trusted messenger.\n\nGo and rally my flight. They must know and prepare for the battle ahead.", objectives = "" }
WordHunterWoW_QuestEN[70221] = { title = "Show Your Mettle", description = "", objectives = "" }
WordHunterWoW_QuestEN[70229] = { title = "Boku the Mystic", description = "The mystics were called away to Ridgewater Retreat a few days ago, but one mystic remains. His name is Boku. He can be found on top of the hill at the Ohn'ahran shrine.\n\nHe's just an initiate, but he should be able to commune with Ohn'ahra and acquire her blessing. With Ohn'ahra on our side, we might be able to win this war before it starts.", objectives = "" }
WordHunterWoW_QuestEN[70233] = { title = "Axe Shortage", description = "A mix-up with orders resulted in a severe shortage of new axes for our explorers. We have an immediate need for more Draconium Axes and are looking for all blacksmiths to pitch in. In return, I will impart new Blacksmithing Knowledge to you to assist in making even more epic pieces.", objectives = "" }
WordHunterWoW_QuestEN[70234] = { title = "All this Hammering", description = "The anvils have not been quiet since the Dragon Isles awoke. The anvils are doing fine, but our hammers are starting to crack. To keep up with the demand, we need to restock.", objectives = "" }
WordHunterWoW_QuestEN[70235] = { title = "Repair Bill", description = "The Dragon Isles have not experienced conflict like this in millennia. Our work is not in dispute, but any good armor suffers from all of this constant use. I have a big order for Serevite Repair Hammers and I need everyone I can get to fill it. If you help out, I will again give you more information to expand your Dragon Isles Blacksmithing skills.", objectives = "" }
WordHunterWoW_QuestEN[70236] = { title = "Dislodged Dragoneye", description = "<This might be something Emila Bellocq is looking for.>", objectives = "" }
WordHunterWoW_QuestEN[70239] = { title = "Untold Regrets", description = "Duroz is old, sick, and stubborn as a kodo. There was no stopping him getting on the airship to come here. Best I could do was come be his walking stick.\n\nI've seen him in pain enough times on the battlefield to know when he's hiding it. He's been getting worse every day out here. Can you help me get him to the potion makers? Ale's not doing the trick anymore. \n\nIf you can carry our weapons, I can help him walk.", objectives = "" }
WordHunterWoW_QuestEN[70240] = { title = "Pain Management", description = "It is a good thing you brought him here when you did. I can tell he is in a great deal of pain, though he bears it well. So must we all when it comes time.\n\nI am afraid that it is age that ails him and not illness, but I may be able to relieve some portion of his suffering.\n\nWould you mind gathering some snapflowers, shallowlilies, and pure water from the garden nearby? I can create a pain medicine with these components, if you find enough.", objectives = "" }
WordHunterWoW_QuestEN[70241] = { title = "The Bitter End", description = "It just happened. I--He was sleeping and I looked away and-- We came back here every day, he just wanted to sit with the whelps, I didn't know he--\n\n<Kolgar's face is clearly tear-stained. He rubs his eyes with the back of his hand.>\n\nNo, I knew. I knew. But I don't know what to do now. What do I do with him?\n\nCan you-- Can you find Bathoras?", objectives = "" }
WordHunterWoW_QuestEN[70242] = { title = "Life After Life", description = "I could sense that his friend bore a deep scar. Something in this place reopened it--perhaps so that it could heal cleanly this time.\n\nNow it is Kolgar's time to heal.\n\nIn the terrace above us, you will find my friend Trellain working with the enchanters. Tell him that I require one of the vessels he uses in his work. He will give it to you freely.", objectives = "" }
WordHunterWoW_QuestEN[70244] = { title = "Nokhud Can Come of This", description = "For thousands of years, the Teerai have guarded the Horn of Drusahl, our most sacred relic. By sacking this village, Balakar has betrayed everything it means to be Maruuk. There can be no redemption for him now.\n\nWe must retake the Horn before Balakar can destroy it and rescue any Teerai who yet live. I am going with you to personally bring that false Khan to justice. The Nokhud will know the wrath of the Khanam Matra!", objectives = "" }
WordHunterWoW_QuestEN[70268] = { title = "Memories Revived", description = "You found a partially destroyed diary. It appears to be written from the view point of a young black dragon woman, before the corruption. \n\nWhile the back part of it is illegible, skimming through the first part, a name stands out to you. Veritistrasz.", objectives = "" }
WordHunterWoW_QuestEN[70279] = { title = "Blood of Dragons", description = "As you've no doubt seen, this land contains creatures which grow beyond their normal size.\n\nWe consider these beasts as blessed by the gods of the wild, and they are often considered honorable targets for hunters to prove their strength. One of these beasts, which we call Karkidan, is nearby. I would be most impressed if you managed to take it down.", objectives = "" }
WordHunterWoW_QuestEN[70299] = { title = "Draconic Defensive", description = "I've heard words on the wind of outsiders allying with Clan Nokhud in an effort to defeat our dragon neighbors. These Primalists are a blight on the plains of our ancestors.\n\nSlay them, and bring me the cores of the elementals they command.", objectives = "" }
WordHunterWoW_QuestEN[70319] = { title = "Nergazurai", description = "My uncle told me many tales of his battle with a hornstrider named Nergazurai. He told me of its fuchsia scales weaving through the hills of the plains as it seeks its prey, its razor-sharp talons and venomous bite.\n\nWhile I was out hunting I saw the flash, but it was too late; it left me with a nasty bite in my shoulder. He was as terrible as my uncle described, but I came out alive.\n\nI need to clean the infection from his bite. Please, collect the reagents I need. Time is of the essence.", objectives = "" }
WordHunterWoW_QuestEN[70335] = { title = "Simple Excavation Tools", description = "", objectives = "" }
WordHunterWoW_QuestEN[70337] = { title = "Emberwatch", description = "Hail, outsider.\n\nThe winds tell me of a group taking shelter in the ruins of Emberwatch. They seem only interested in the past while we centaur choose to live for the present under the grace of Ohn'ahra.\n\nNonetheless, they are guests in our home. I have fashioned for them these wind chimes so they may hear Ohn'ahra's presence. May it bring their hearth some joy and comfort.", objectives = "" }
WordHunterWoW_QuestEN[70338] = { title = "They Took the Kits", description = "If Sylvie is this distressed, that must mean it's her kits that are in there! \n\nWhile she was infected, the giants must have kit-napped her babies and she was too weak to save them.\n\nKits are energetic at this age, hopefully they've all been quick enough to evade the giants until now...\n\nHere, make use of my invisibility charm-- Quickly, you must save them before they're eaten!", objectives = "" }
WordHunterWoW_QuestEN[70339] = { title = "In Tyr's Footsteps: The Ohn'ahran Plains", description = "Though you have done well in your first challenge, do not think you shall surpass all so easily. Keeper Tyr meant the Engine of Innovation to be only for those worthy enough to use it wisely. \n\nIf you are undeterred, the next challenge shall be found in the Ohn'ahran Plains. I look forward to testing your capabilities, adventurer.", objectives = "" }
WordHunterWoW_QuestEN[70341] = { title = "Well-Earned Victory", description = "The smallest of things can contain the greatest of treasures.\n\nTake the essence to the Engine of Innovation.", objectives = "" }
WordHunterWoW_QuestEN[70351] = { title = "Garden Party", description = "I've been tending to this garden for years, preparing for the day I'd finally accept my Lifecalling. Now that day is here!\n\nI love flowers and all trees and plants--even the bugs that live amongst them. I can feel nature's spirit--the Great Dragon Spirit--when I tend the garden.\n\nThere's only one thing left to do. I'm going to invoke the Great Dragon Spirit, just like the legends.\n\n<Akora smiles brightly.>\n\nMeet me down in the garden by the pool where her bones rest. I'll explain more there.", objectives = "" }
WordHunterWoW_QuestEN[70352] = { title = "Scaling Ever Higher", description = "You there, outsider! You have killed proto dragons before, yes?\n\nSo it stands to reason that your experience combined with my hunting prowess, we can take down quite a few! There are springs around here that attract draconic beasts. \n\nHelp me prove to my foolish other half that I am the better hunter.", objectives = "" }
WordHunterWoW_QuestEN[70355] = { title = "Dragon Isles Alchemy", description = "", objectives = "" }
WordHunterWoW_QuestEN[70357] = { title = "Dragon Isles Blacksmithing", description = "", objectives = "" }
WordHunterWoW_QuestEN[70358] = { title = "Dragon Isles Blacksmithing", description = "", objectives = "" }
WordHunterWoW_QuestEN[70359] = { title = "Dragon Isles Engineering", description = "", objectives = "" }
WordHunterWoW_QuestEN[70360] = { title = "Dragon Isles Enchanting", description = "", objectives = "" }
WordHunterWoW_QuestEN[70361] = { title = "Dragon Isles Inscription", description = "", objectives = "" }
WordHunterWoW_QuestEN[70362] = { title = "Dragon Isles Leatherworking", description = "", objectives = "" }
WordHunterWoW_QuestEN[70363] = { title = "Dragon Isles Skinning", description = "", objectives = "" }
WordHunterWoW_QuestEN[70364] = { title = "Dragon Isles Herbalism", description = "", objectives = "" }
WordHunterWoW_QuestEN[70365] = { title = "Dragon Isles Jewelcrafting", description = "", objectives = "" }
WordHunterWoW_QuestEN[70366] = { title = "Dragon Isles Tailoring", description = "", objectives = "" }
WordHunterWoW_QuestEN[70368] = { title = "Occupation Examination", description = "Hello! Are you interested in working with the Artisan's Consortium to earn plentiful profits and provide valuable goods and services to clients across Azeroth?\n\n...Hmm? You have no professions? What a missed opportunity!\n\n<Haephesta ponders for a moment.>\n\nI know! I will ask you a series of questions about your personality, and we will find out together which profession best suits you! How does that sound?", objectives = "" }
WordHunterWoW_QuestEN[70370] = { title = "Occupation Examination", description = "Hello! Are you interested in working with the Artisan's Consortium to earn plentiful profits and provide valuable goods and services to clients across Azeroth?\n\nExcellent! Which two skills have you trained in?\n\n...Hmm? You have only one profession? What a missed opportunity!\n\n<Haephesta ponders for a moment.>\n\nI know! I will ask you a series of questions about your personality, and we will find out together which second profession best complements your first one! How does that sound?", objectives = "" }
WordHunterWoW_QuestEN[70371] = { title = "Deathwingurlugull!", description = "Deathwingurlugull! Deathwingurlugull! Deathwingurlugull delgrbrrl!!\n\nGrrrooooooooom blarglg!!\n\n<You don't need a translation to know that they want you to bring down their murloc version of Deathwing. Before you can agree or disagree, the roars of a machine engine make their way toward you!>", objectives = "" }
WordHunterWoW_QuestEN[70373] = { title = "Deathwingurlugull!", description = "Deathwingurlugull! Deathwingurlugull! Deathwingurlugull delgrbrrl!!\n\nGrrrooooooooom blarglg!!\n\n<You don't need a translation to know that they want you to bring down their murloc version of Deathwing. Before you can agree or disagree, the roars of a machine engine make their way toward you!>", objectives = "" }
WordHunterWoW_QuestEN[70374] = { title = "Himia, the Blessed", description = "The Elements lay claim to this land and do not welcome our intrusion.\n\nO, Elements, have you forgotten our protector--Air! Invisible, yet omnipresent and vital for all existence! Forgotten, as easy as you breathe it. After facing me, you will never forget again.", objectives = "" }
WordHunterWoW_QuestEN[70376] = { title = "Second Challenge of Tyr: Might", description = "<As you approach, an inscription on the statue lights up with a faint glow.>\n\n\"Wield the Keeper's power and show the undaunted determination of one who stands strong.\"", objectives = "" }
WordHunterWoW_QuestEN[70377] = { title = "Derelict Fashion", description = "<A disgusting set of sunglasses is dripping with slime, but they look extremely expensive.\n\nSomeone is definitely missing these. This style is very hot right now.>", objectives = "" }
WordHunterWoW_QuestEN[70414] = { title = "Shaky Grounds", description = "In the name of Khaz'goroth, what goes on here? \n\nThis magma works with a mind of its own, consuming these elemental cavestones from below. Tis more than chance causin' this... I aim to figure it out!\n\nPlace these Shattering Totems next to each trapped elemental to free them!", objectives = "" }
WordHunterWoW_QuestEN[70437] = { title = "To Tyrhold", description = "Centuries have passed since the flights last visited Tyrhold. \n\nNevertheless, we must travel there and investigate if the Mother Oathstone still functions.\n\nCome, speak with me at the Seat of the Aspects. We must learn about the dangers we may face at Tyr's former stronghold.", objectives = "" }
WordHunterWoW_QuestEN[70438] = { title = "Flying Fish", description = "The fish could be biting better, don't you think?\n\nYou know, that gives me an idea. Legend says these lakes and rivers did not always have fish. They say, these watering holes were stocked with fish when the dragons soaring overhead dropped them! Can you believe it?\n\nMaybe you and your drake could give it a try?", objectives = "" }
WordHunterWoW_QuestEN[70444] = { title = "The Fields of Ferocity", description = "To the bravest Shikaar! \n\nGather your best and head on over to the Fields of Ferocity. You could be crowned the fiercest of them all!\n\nProve your might. Show us your best fight!\n\nTerms and conditions apply.", objectives = "" }
WordHunterWoW_QuestEN[70446] = { title = "A Personal History", description = "In delving into the archives here, I've found threads that point towards the Obsidian Observatory as a place of personal importance to the Earth-Warder. I can only guess what knowledge it may contain about the history of our flight.\n\nGiven Emberthal's interest in the subject, I informed her of my discovery. I pray that wasn't a mistake.\n\nShe has gone ahead to scout. Please, keep an eye on her. She is a competent soldier, but this subject is... troubling. Who knows what truths you may uncover.", objectives = "" }
WordHunterWoW_QuestEN[70450] = { title = "Otter Devastation", description = "Hey there, friend. These here ottuks keep stealin' my catch!\n\nPersonally, I'd blow 'em up, but our Tuskarr friends don't seem too keen on that action. I made this here Ottuk Deterent Device MK-SH4RK, but... I aint a great swimmer.\n\nYou seem like you got the goods, why don't ya do us all a favor, activate the device, swimmy-swim around over there, and scare 'em off?", objectives = "" }
WordHunterWoW_QuestEN[70501] = { title = "License to Hunt", description = "Ah, finally ready to prove yourself as a hunter? Keep in mind this is not as simple as running around and hunting everything that moves. The Shikaar hunt with purpose. We hunt to feed and clothe the clan, to prove our strength against mighty foes, and to balance nature.\n\nWe do not hunt the land barren, we sow the seeds for future Grand Hunts as we go. Prove yourself capable of following these instructions and you may join us.\n\nHowever I do not have confidence in your friend there succeeding.", objectives = "" }
WordHunterWoW_QuestEN[70503] = { title = "The Vigilance of Tyr", description = "Bodies, broken gear, uncontrolled titan energy. What a disregard for safety, and... and protocol! It looks like they found the stone and it was unstable, bursting into pieces.\n\nFortunately, I'm particularly adept at repairing magical devices.\n\nBut before I can reform the stone we need to collect each and every piece.", objectives = "" }
WordHunterWoW_QuestEN[70507] = { title = "The Insight of Tyr", description = "Did ya see Szar Skeleth on your way in? It's that ruined tower to the northeast.\n\nWe've got a bit of a good news, bad news situation there. The good news is the stone's already been found. Bad news is it was found by the Sundered Flame, specifically a magic-using dracthyr named Makko. And they're using it to control gorlocs.\n\nDid I mention the dracthyr's misuse of the stone drove them mad?\n\nWell, good luck!", objectives = "" }
WordHunterWoW_QuestEN[70509] = { title = "Third Challenge of Tyr: Persistence", description = "<It seems those who have reawakened with the Isles have not been kind to Keeper Tyr's creations. Perhaps finding the missing pieces of the statue would help.>", objectives = "" }
WordHunterWoW_QuestEN[70510] = { title = "Victorious", description = "Once again I ask you to bring this essence to the Engine of Innovation.", objectives = "" }
WordHunterWoW_QuestEN[70526] = { title = "Ohn'ahran Plains Rally", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[70530] = { title = "Examination Week", description = "The students at Algeth'ar Academy ran out of solutions... again. Forgive me for asking, but could you gather more Dragon's Alchemical Solution so they can continue their studies?", objectives = "" }
WordHunterWoW_QuestEN[70531] = { title = "Mana Markets", description = "Demand for mana potions has increased dramatically this week, {name}. I will need your assistance filling customers' orders. Surely as a skilled alchemist you can spare a few, yes?", objectives = "" }
WordHunterWoW_QuestEN[70532] = { title = "Aiding the Raiding", description = "Oh {name}, I am glad to see you. Several champions have been injured in the latest assault against the Primalists. We are greatly in need of healing potions. As an adventurer yourself, I imagine you have several on hand already. We will need many.", objectives = "" }
WordHunterWoW_QuestEN[70533] = { title = "Draught, Oiled Again", description = "Did you know that Writhefire Oil is an excellent reagent for finishing your draughts? I did. And now I am out of it. I cannot work without a plentiful stock of oils. Please {name}, help me restock my laboratory.", objectives = "" }
WordHunterWoW_QuestEN[70539] = { title = "And You Thought They Did Nothing", description = "Hey sparky, you know what everyone forgets they need when they're flying around on dragons? Goggles.\n\nYou know what we sold out of today? Goggles.\n\nYou know what I need from you right now? You guessed it!", objectives = "" }
WordHunterWoW_QuestEN[70540] = { title = "An Engineer's Best Friend", description = "Hey sparky, have you seen my...\n\nErr... maybe hand me the...\n\nThat's it--I think it's time we start keeping a few more tools around this shop, you know what I'm saying?", objectives = "" }
WordHunterWoW_QuestEN[70541] = { title = "Hunting Tactics: Companion", description = "Your renown with the Maruuk grows. You may now hunt alongside a tenacious bakar or swift ohuna companion.", objectives = "" }
WordHunterWoW_QuestEN[70542] = { title = "Azure Span Rally", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[70545] = { title = "Blingtron 8000...?", description = "Hey sparky, I've got a secret project going on. People are going to go wild! But I've run out of the basics.... You wanna be a pal and get me some bolts?", objectives = "" }
WordHunterWoW_QuestEN[70550] = { title = "Welcome to the Assembly", description = "We could use your aid.\n\nThe Sundered Flame have taken control over most of the Cobalt Assembly. \n\nPlease help us in this fight against them. Our numbers are small, but there are a few things we can do to aid you.", objectives = "" }
WordHunterWoW_QuestEN[70557] = { title = "No Scopes", description = "Great gadgets, sparky, do I have a big one for you today!\n\nApparently, some firework fad caught on with the hunters. They try setting them off to scare the ducks into the air. Bet the ducks are way to smart for that, but it won't stop us from profiting! Think you're up to the task?", objectives = "" }
WordHunterWoW_QuestEN[70558] = { title = "Disillusioned Illusions", description = "My scribe apprentice, you could not have chosen better timing.\n\nThere has been a terrible accident! All of the Illusion Parchment I ordered turned out to be real! Can you believe it! Do they think this is some game? Someone might get hurt!\n\nDo you think you could rectify this situation and create some real illusions?", objectives = "" }
WordHunterWoW_QuestEN[70559] = { title = "Quill You Help?", description = "My scribe apprentice, I am delighted to see you.\n\nEarlier today I had a few novices come in to try their hand at inscription. They all wrote with too much force and snapped their quill nibs right off!\n\nI hate to ask, but could you craft a few more quills to keep in stock?", objectives = "" }
WordHunterWoW_QuestEN[70560] = { title = "The Most Powerful Tool: Good Documentation", description = "My scribe apprentice, do you feel ready for writing today? The Dragonscale Expedition has brought copious notes from their adventures, and they have asked that we compile their chicken-scratch penmanship into a suitable compendium for field-ready review. And oh, my hand is simply not up for the task today. Could I rely on you once more?", objectives = "" }
WordHunterWoW_QuestEN[70561] = { title = "A Scribe's Tragedy", description = "My scribe apprentice! It is awful, just terrible! I cannot fathom how I am to go on in my life!\n\n<Talendara begins weeping.>\n\n...I have run out of ink! Could you please bottle some more?", objectives = "" }
WordHunterWoW_QuestEN[70562] = { title = "The Plumbers, Mason", description = "Jewelcrafter, how would you feel about a chance to practice your prospecting techniques?\n\nThe architects and plumbers of the Dragonscale Expedition have requested that we acquire some stones for the construction of a new bath house. I think you will find this a suitable task to occupy you and practice your masonry.", objectives = "" }
WordHunterWoW_QuestEN[70563] = { title = "The Exhibition", description = "Oh jewelcrafter, how would you feel about a chance to practice your gemcutting?\n\nI was going to put on a display of various cuts, and I suppose I could exhibit your gems as well, so long as you hurry. Submit nothing less than the highest quality for this demonstration.", objectives = "" }
WordHunterWoW_QuestEN[70564] = { title = "Spectacular", description = "Jewelcrafter, there is an exhibition coming up, and I am concerned that the clients will not be able to see the beauty of each cut without the proper lenses.\n\nYou do not need anything fancy. Just make a few loupes so our customers can see clearly.", objectives = "" }
WordHunterWoW_QuestEN[70565] = { title = "Separation by Saturation", description = "Oh jewelcrafter, do you like my necklace?\n\nOf course you do. But I cannot show it off properly unless it stands out.\n\nI know! Why don't you make a few simple pendants and we shall flood the market. Once everyone is wearing your designs, my necklace will be a sparkling cut above the rest!", objectives = "" }
WordHunterWoW_QuestEN[70567] = { title = "When You Give Bakar a Bone", description = "I had some of the most beautiful bonewrought bows, but our bakar got to them before they could be put to use. Bakar love to chew bones, whether bow or not, and now they are ruined!\n\nCan you aid me in crafting replacements?", objectives = "" }
WordHunterWoW_QuestEN[70568] = { title = "Tipping the Scales", description = "Our scale bracers are finely crafted and highly in demand. I am finding it difficult to keep up with all of the orders! Would you lend your skill in replenishing my supply?", objectives = "" }
WordHunterWoW_QuestEN[70569] = { title = "For Trisket, a Task Kit", description = "I have many valued customers, but Trisket is one of my favorites. Most recently he came to me because his herbalist's pouch has worn out. \n\nI offered to make him a selection of baskets to replace his old pouch. \n\nWould you help me with these tasks, {name}? Trisket would be appreciative.", objectives = "" }
WordHunterWoW_QuestEN[70571] = { title = "Drums Here!", description = "We are known far and wide for our drums--the centaur have been honing these skills for generations. Unfortunately this means that our drums are in short supply these days.\n\nYou have skills of your own, I see. Perhaps you could help me craft a few drums for our stores?", objectives = "" }
WordHunterWoW_QuestEN[70572] = { title = "The Cold Does Bother Them, Actually", description = "If there is one thing I have learned in my years as a seamstress, {name}, it is that adventurers will always underestimate the cold.\n\nI have explorers in the Azure Span begging me for warmer robes.\n\nWould you take pity on them and craft a few?", objectives = "" }
WordHunterWoW_QuestEN[70582] = { title = "Weave Well Enough Alone", description = "If there is one thing I have learned in my years as a seamstress, {name}, it is the importance of practice.\n\nAlways be practicing your craft, even when you believe you have mastered everything. I want you to be able to weave with excellence without my supervision.\n\nWhy don't you practice this week? Make a few Wildercloth Bolts at the highest quality.", objectives = "" }
WordHunterWoW_QuestEN[70586] = { title = "Sew Many Cooks", description = "If there is one thing I have learned in my years as a seamstress, {name}, it is that too many cooks spoil everything.\n\nIn this case, I was going to go out for a drink and an order came in last minute for an entire wardrobe of chef's uniforms.\n\nIf you could sew the hats, I will take care of everything else.", objectives = "" }
WordHunterWoW_QuestEN[70587] = { title = "A Knapsack Problem", description = "If there is one thing I have learned in my years as a seamstress, {name}, it is that you can never have enough space for your reagents. In fact, we could use a few more bags around here to hold everything. Would you mind stitching another?", objectives = "" }
WordHunterWoW_QuestEN[70589] = { title = "Blacksmithing Services Requested", description = "Hi, hi, hi {name}! Crafting orders are coming in left and right!\n\nIf you're looking for work, the Artisan's Consortium always has orders to fill!\n\nYou can take a look at our public orders, or if you've built up a network of clients for yourself, fill some guild orders or personal orders! Just get it done, done, done!", objectives = "" }
WordHunterWoW_QuestEN[70591] = { title = "Engineering Services Requested", description = "Hi, hi, hi {name}! Crafting orders are coming in left and right!\n\nIf you're looking for work, the Artisan's Consortium always has orders to fill!\n\nYou can take a look at our public orders, or if you've built up a network of clients for yourself, fill some guild orders or personal orders! Just get it done, done, done!", objectives = "" }
WordHunterWoW_QuestEN[70592] = { title = "Inscription Services Requested", description = "Hi, hi, hi {name}! Crafting orders are coming in left and right!\n\nIf you're looking for work, the Artisan's Consortium always has orders to fill!\n\nYou can take a look at our public orders, or if you've built up a network of clients for yourself, fill some guild orders or personal orders! Just get it done, done, done!", objectives = "" }
WordHunterWoW_QuestEN[70593] = { title = "Jewelcrafting Services Requested", description = "Hi, hi, hi {name}! Crafting orders are coming in left and right!\n\nIf you're looking for work, the Artisan's Consortium always has orders to fill!\n\nYou can take a look at our public orders, or if you've built up a network of clients for yourself, fill some guild orders or personal orders! Just get it done, done, done!", objectives = "" }
WordHunterWoW_QuestEN[70594] = { title = "Leatherworking Services Requested", description = "Hi, hi, hi {name}! Crafting orders are coming in left and right!\n\nIf you're looking for work, the Artisan's Consortium always has orders to fill!\n\nYou can take a look at our public orders, or if you've built up a network of clients for yourself, fill some guild orders or personal orders! Just get it done, done, done!", objectives = "" }
WordHunterWoW_QuestEN[70595] = { title = "Tailoring Services Requested", description = "Hi, hi, hi {name}! Crafting orders are coming in left and right!\n\nIf you're looking for work, the Artisan's Consortium always has orders to fill!\n\nYou can take a look at our public orders, or if you've built up a network of clients for yourself, fill some guild orders or personal orders! Just get it done, done, done!", objectives = "" }
WordHunterWoW_QuestEN[70613] = { title = "Get Their Bark Before They Bite", description = "{name}, you are a skilled herbalist, are you not? I have alchemists nearly begging at my door... well, if I had a door... for more Writhebark. We have nearly sold out! \n\nWill you help me gather more? I fear if the alchemists cannot create the phials they need, they will begin experimenting with my belongings.", objectives = "" }
WordHunterWoW_QuestEN[70614] = { title = "Bubble Craze", description = "<Agrikus shouts at you.> I have no more poppy tea!\n\n...Oh, you're not one of them. Praise the Titans. Someone made \"Bubble Poppy Tea\" the most fashionable drink on the market this week and I've sold out of the herb completely. Please, could you bring more poppies before they return in droves?", objectives = "" }
WordHunterWoW_QuestEN[70615] = { title = "The Case of the Missing Herbs", description = "Aah, {name}! There you are!\n\nThey took it! They took my Saxifrage!\n\nI left for barely two hours, and when I returned, someone had taken my Saxifrage! All they left to show for their crimes was this heavy sack of gold coins. As if you could put a price on herbs!\n\n...Please {name}, I need more Saxifrage to replenish what that criminal took from me.", objectives = "" }
WordHunterWoW_QuestEN[70616] = { title = "How Many??", description = "<Agrikus is crying as you approach.>\n\nThey did it... I cannot believe they did it...\n\nSomeone has come here and asked for the delivery of ONE THOUSAND herbs!\n\nI cannot even fathom this! It is preposterous. Ridiculous! Ludicrous!!\n\n...Please help.", objectives = "" }
WordHunterWoW_QuestEN[70617] = { title = "All Mine, Mine, Mine", description = "There is nothing as useful as Draconium ore. So much can be done with it! It is the perfect ore, pure in every way.\n\nBring me Draconium. I must have it. You are a miner, yes? Then go mine!", objectives = "" }
WordHunterWoW_QuestEN[70618] = { title = "The Call of the Forge", description = "The forge... she calls to me. And she asks for Serevite. You there! Bring me Serevite! Yes, lots of Serevite! <Sekita begins laughing zealously.>", objectives = "" }
WordHunterWoW_QuestEN[70619] = { title = "A Study of Leather", description = "You there! Perhaps you can help me with my studies of this leather. Some of it is soft and pliable, yet other pieces have a more firm temper--the better for crafting armor, I suspect.\n\nBring me more leathers to investigate. I wish to continue my studies.", objectives = "" }
WordHunterWoW_QuestEN[70620] = { title = "Scaling Up", description = "Many people ask me how I became so good at skinning. To them I say: it is all in the scales. \n\nAre you curious to learn more? Bring me some scales, and I will show you what I mean.", objectives = "" }
WordHunterWoW_QuestEN[70621] = { title = "Third Challenge of Tyr: Persistence Embodied", description = "Your third challenge was meant to have you overcome unfavorable odds. It was to help show me your persistence in all matters.\n\nI believe fighting djaradin and fixing my statue with the expectation that I would issue you a challenge is more than sufficient to fulfill your victory condition. \n\n<You think you catch a small smile play across her lips.>", objectives = "" }
WordHunterWoW_QuestEN[70627] = { title = "What of the Winterpelt Clan?", description = "We could join another clan... if we knew it to be safe.\n\nI worry the Primalists tempted other clans as they did ours. \n\nThis \"Dragonscale Expedition\" tells me they have a clawhold near the Winterpelt clan.\n\nThey may be tainted. Or they may heed our warning. With either truth, they need us.\n\nThere is a \"furbolg expert,\" Sonova Snowden, in Theron's Watch. Please go to him and learn what he knows.", objectives = "" }
WordHunterWoW_QuestEN[70633] = { title = "Fueling the Engine", description = "You have done well to pass the first challenge that Keeper Tyr left behind. Though this is but the first step on your journey I have faith you shall do well. You have earned your chance at furthering yourself in unlocking the secrets of the Forge. \n\nAdd the Bottled Essence to the Engine of Innovation and see what occurs.", objectives = "" }
WordHunterWoW_QuestEN[70640] = { title = "WANTED: Boss", description = "<The page's script glows with a soft blue light.>\n\nPreviously a cherished plaything of Malygos, the elemental Frigellus suffered from his master's neglect. \n\nWhile this once-happy settlement crumbled apace, the churlish and playful creature grew warped and twisted by the evils that plague this land.\n\nPlease see that it is safely neutralized.\n\nBring word of your success to Custodian Cynegos.", objectives = "" }
WordHunterWoW_QuestEN[70641] = { title = "A Waking Oath", description = "Hold a moment, {name}. I wish to personally thank you for your aid in restoring our oathstone.\n\nI was not aware of the dracthyr until your reawakening on the Forbidden Reach. It was unclear what your arrival among us meant. Whether your kind would prove to be a boon to the defense of life... or a bane.\n\nI would encourage you to learn more about our oathstone. Speak with a few of my flight here at the Ruby Lifeshrine. Perhaps you will find familiarity among our tales.", objectives = "" }
WordHunterWoW_QuestEN[70642] = { title = "Pilfered Paraphernalia", description = "Another expedition, another misfortune...\n\nThe dwarves were boasting about how a \"real expeditioner\" can grab a ram by the horns. So, I decided to try it!\n\nI immediately received a horned headbutt to the noggin and was knocked out. And, when I came to, all my gear was missing. Again.\n\nI should stick to what I'm good at: observing creatures from a safe distance.\n\nPlease find my missing gear and uh... don't tell the dwarves.", objectives = "" }
WordHunterWoW_QuestEN[70643] = { title = "Arcane Explosives", description = "", objectives = "" }
WordHunterWoW_QuestEN[70644] = { title = "Taming the Wild Goat", description = "", objectives = "" }
WordHunterWoW_QuestEN[70647] = { title = "Oh Where, Oh Where Can He Be?", description = "{name}, I am glad to see you! I am worried sick and could use your help.\n\nRecently, I rescued an abandoned proto-drake whelp. I named him Lubbins because he is so lovely! I brought him here to care for him and hopefully find him a good home as someone's pet. \n\nBut now he is missing, and I am concerned that he is lost or hurt. I need to keep watch over the rest of my little ones, otherwise I would go searching for him myself. Would you please look for him?", objectives = "" }
WordHunterWoW_QuestEN[70650] = { title = "In Tyr's Footsteps: The Waking Shores", description = "You have proven yourself well so far, and though I have great faith you are worthy of the Engine I still must challenge you as is my designation. \n\nGo to the Waking Shores and find my statue and you shall receive further instructions.", objectives = "" }
WordHunterWoW_QuestEN[70697] = { title = "An Expert Opinion", description = "Lubbins' wounds may have healed, but I am afraid his confidence may still be injured. I believe it is time to call on others for help.\n\nFar to the southwest in a remote section of the Azure Span there is a pet trainer named Patchu. She is one of the world's foremost experts on these matters.\n\nPlease visit her, I am sure she can help Lubbins!", objectives = "" }
WordHunterWoW_QuestEN[70701] = { title = "Bakar Dream of Lost Argali", description = "Some of the clan's argali have wandered away from our flock again.\n\nThe ridge around us is too dangerous for our shepherds to search for them. It would be a great boon if you could take one of our bakar and bring back the argali. Our shepherds can point you in the right direction.", objectives = "" }
WordHunterWoW_QuestEN[70702] = { title = "Continued Waygate Exploration", description = "<The little messenger's loud, screeching call captures your attention. They hand you a note before running off.\n\nThe note is a request from Thaelin Darkanvil, seeking your assistance.>", objectives = "" }
WordHunterWoW_QuestEN[70703] = { title = "The Legacy of Tyrhold", description = "Keeper Tyr did love his mysteries. Clearly, there is deeper meaning to the gift he gave us. As he most likely forged this scale at his former citadel, perhaps it will be the key to helping unlock its secrets.\n\nGo with Koranos to Tyrhold, {name}. As a trusted advisor and watcher of this land, I am sure he will have insight into this matter.", objectives = "" }
WordHunterWoW_QuestEN[70706] = { title = "Waygate: Shady Sanctuary", description = "Our expedition reports a dormant stone out in the lush hillsides to the southwest. It's quite a journey, but worth sendin' someone with yer knowledge tae investigate.", objectives = "" }
WordHunterWoW_QuestEN[70707] = { title = "The Next Waygate", description = "I've been keepin' this here vessel from yer nightborne friend safe.\n\nWhat do ye say 'bout us puttin' it tae good use and pursuin' another of those old stones?", objectives = "" }
WordHunterWoW_QuestEN[70708] = { title = "Hollow", description = "Feels like it's been years. Also feels like it's been minutes. \n\nI could use someone to talk to, if you have time. \n\nYou wanna grab us a round of drinks? Get whatever you want. I'm paying.", objectives = "" }
WordHunterWoW_QuestEN[70710] = { title = "River Rapids Route", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[70711] = { title = "River Rapids Route - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[70713] = { title = "Highlands Fishing", description = "", objectives = "" }
WordHunterWoW_QuestEN[70715] = { title = "Dragonflight (70) E", description = "", objectives = "" }
WordHunterWoW_QuestEN[70721] = { title = "After My Ohn Heart", description = "There is a small pond by the Mirror of the Sky where Narman and I first met during my initiate training.\n\nInitiates travel up there to be closer to Ohn'ahra so they may feel the wind. I first saw him in the reflection of the water when a sudden breeze opened my eyes. It is the most beautiful sight in all of the plains.\n\nIt will be the perfect place for our proposal.", objectives = "" }
WordHunterWoW_QuestEN[70722] = { title = "What Lubbins Needs", description = "I think that I know what we gotta do, {name}. \n\nBut first, let's talk about it!\n\nI even have a gift to give you after we're done! Fun, right?", objectives = "" }
WordHunterWoW_QuestEN[70723] = { title = "Shattering the Earth Primalists", description = "Rethelshi in Valdrakken will be grateful to get this to aid his research on the Primalists.", objectives = "" }
WordHunterWoW_QuestEN[70730] = { title = "Shikaar Giver", description = "Oh, {name}.\n\nDo you feel comfort under the sun? Do you feel safe under its bright caress? Does each new day represent hope for the future and a chance to live your life as you've always dreamt it?\n\nThen you know love as I do.\n\nNarman of Clan Shikaar is my sun. He is my warmth. He is my light. He is my hope.\n\nA man like him deserves a proposal worthy of stature.\n\nWe must seek guidance from an Ohn.", objectives = "" }
WordHunterWoW_QuestEN[70732] = { title = "A Practice Bout", description = "All right! Now that you used that stone on Lubbins, let's have a practice bout to test out his skills! \n\nThere's a big ole Hornswog named Gwosh that lives on the shore to the north of here. Gwosh loves to fight! Well, play really. He's super good with other pets, too! \n\nIt'll be a perfect playtime... I mean fight... for Lubbins.", objectives = "" }
WordHunterWoW_QuestEN[70738] = { title = "The You-ga Class", description = "Everything was going so well, but now? Elementals are causing some, um, mild challenges.\n\nOur guests were enjoying the facilities when suddenly, all these elementals appeared! Those nasty fiends have disrupted everything. Probably even the new you-ga instructor. \n\nOh yes, you-ga is a new type of stretching that helps you meditate at the same time. I am sure both teacher and students are so relaxed they do not even notice the elementals.\n\nStill, better to be safe than sorry. Please, look for them.", objectives = "" }
WordHunterWoW_QuestEN[70739] = { title = "Bloodlines, Sweets, and Teerai", description = "I have hunted with khans, outrun our fastest bakar, and wrestled a full grown bruffalon bull bare-handed. As a hunter, I've nothing left to prove.\n\nHowever, as a partner, I still have much to learn. \n\nWindsage Dawa of Clan Ohn'ir is my heart and my joy. I wish only to prove worthy of his love, but I know nothing of traditions and rituals. I require the wisdom of the elders in Maruukai.", objectives = "" }
WordHunterWoW_QuestEN[70740] = { title = "Steam Cleaning", description = "Xijan seems to think the elemental invasion on our beautiful spa is only a minor problem, but this surge of flame and steam needs to be brought under control immediately.\n\nWe had booked musical acts to play in the lower area, but the elementals destroyed their gear. As we have never had such levels of elemental destruction in this area before, I suspect Primalist influences.\n\nIf you want to help, clear the elementals on the east side of the lower spa. That is where the first events are scheduled.", objectives = "" }
WordHunterWoW_QuestEN[70741] = { title = "Some Favorite Things", description = "<It looks like the you-ga class was interrupted, and the students' belongings are scattered everywhere. \n\nCollecting these items will certainly aid the Serene Dreams Spa.>", objectives = "" }
WordHunterWoW_QuestEN[70742] = { title = "Runs in the Family", description = "From the air, I scouted one of the artifacts Edress uncovered by the entrance of the ruins. Doubtless there are more inside.\n\nThey are warded somehow, though I will need to get closer before I can examine them. The magic here is very old.\n\nThe grounds appear deserted, but I wouldn't trust that to last long once we start meddling. Keep an eye out. We will uncover all we can.", objectives = "" }
WordHunterWoW_QuestEN[70743] = { title = "Precious Baby", description = "You there, {race}! Are you semi-competent?\n\nDo you have your priorities in check?\n\nGood!\n\nMy precious Baby is missing. Save her immediately. Be quick about it, she can't fend for herself in these horrible conditions.", objectives = "" }
WordHunterWoW_QuestEN[70744] = { title = "Look at the Bones!", description = "<Surely the spa manager would appreciate if there wasn't blood everywhere...>", objectives = "" }
WordHunterWoW_QuestEN[70745] = { title = "Enforced Relaxation", description = "Those Primalists that you saw certainly do not seem like the leadership type to me. Who would be afraid of a little dog? Hah!\n\nSo, if they mentioned Vadne, that sounds like their leader. She must be the one bringing in these elementals. We need to get rid of the summoner. They must be close by to be causing such trouble. Check the cave directly under us. I know it is where some of the less diligent employees like to take an extended break.", objectives = "" }
WordHunterWoW_QuestEN[70746] = { title = "Shades of Blue", description = "You there, {name}!\nIt's good to see a friendly face in these parts. Telash and I were just discussing reports we've heard of... newcomers, in the area.\n\n<Emberthal lowers her voice.>\n\nBlue dragons. \n\nGiven our... history, with the blues, Telash and I thought it necessary to assess the situation ourselves. \n\nPlease, join us.", objectives = "" }
WordHunterWoW_QuestEN[70747] = { title = "The Azure Wizard", description = "I do not have time to quibble with sorcerers. \n\nGo and treat with this \"Archmage\", {name}. Learn what you may, and be on your guard always. They might be allies still or enemies yet...\n\nOur reports indicate there's a large archival complex to the south of here. \n\nThat is where I'm going.", objectives = "" }
WordHunterWoW_QuestEN[70748] = { title = "For Blue Eyes Only", description = "It is no wonder your companions have yet to find anything. \n\nThese books were meant for blue eyes only. \n\nHowever, my presence should suffice in allowing for some of the more pertinent tomes to divulge their secrets.", objectives = "" }
WordHunterWoW_QuestEN[70750] = { title = "Aiding the Accord", description = "You there! Yes, I'm speaking to you. Who else do you see around here?\n\n<Therazal glances quickly at quite a few passers by.>\n\nIgnore them. They are not part of this request. It is you I've heard of, and you I wish to speak with!\n\nThe Valdrakken Accord has asked me to seek out those who have shown they are making a name for themselves across the Isles, and those who seek to ensure our allies and their safety remain the highest priority.\n\nDo what you do best, friend. You shall be rewarded handsomely.", objectives = "" }
WordHunterWoW_QuestEN[70752] = { title = "Vaporizing the Water Primalists", description = "Rethelshi in Valdrakken will be grateful to get this to aid his research on the Primalists.", objectives = "" }
WordHunterWoW_QuestEN[70753] = { title = "Dissipating the Air Primalists", description = "Rethelshi in Valdrakken will be grateful to get this to aid his research on the Primalists.", objectives = "" }
WordHunterWoW_QuestEN[70754] = { title = "Extinguishing the Fire Primalists", description = "Rethelshi in Valdrakken will be grateful to get this to aid his research on the Primalists.", objectives = "" }
WordHunterWoW_QuestEN[70766] = { title = "The Fractured Flame", description = "The gorloc clutches a journal, its cover marred by moisture and lack of care. The faded symbol of the Sundered Flame peeks proudly from behind the tears and discoloration.\n\nIf you find the missing pages, perhaps you can gain insight into Reclaimer Makko and the madness that has fractured her mind.", objectives = "" }
WordHunterWoW_QuestEN[70779] = { title = "Tarjin's Tales", description = "<Tarjin continues facing the distant island while he speaks to you.>\n\nYou think yourself worthy of the incredible legends and histories of the djaradin?\n\nYou, who are hardly the size of one of our weapons? Pfft.\n\nI doubt you have the stomach to carry the legacy of my people.\n\nProve me wrong, if you can. Seek out dragons, the only worthy rival on these isles.\n\nBring me trophies of your victory over their strongest.", objectives = "" }
WordHunterWoW_QuestEN[70781] = { title = "Out of the Blue", description = "Did you see that?!\n\nThis winged creature just fell from the sky! I don't know what sort of being it is, but it certainly isn't native to the Isles.\n\nWait... I do remember a punchy little goblin asking for directions to the Bluefeather Cliffs just above us. You think she would know anything about it?", objectives = "" }
WordHunterWoW_QuestEN[70784] = { title = "The Abandoned Outpost", description = "From what you mentioned, it appears the stone of Vigilance can be found at an abandoned station northeast of the Azure Archives. That must be Zelthrak Outpost.\n\nMeet up with me when you arrive, {name}, and we can find the stone together.", objectives = "" }
WordHunterWoW_QuestEN[70785] = { title = "The City of the Dead", description = "An ancient city of the dead can only mean one thing. The Veiled Ossuary off the coast of northern Thaldraszus.\n\nIt's extensive, remote, and hard to approach. The perfect place to hide something. I'm not sure what we'll find there, {name}. But you can bet that it won't appreciate our presence.", objectives = "" }
WordHunterWoW_QuestEN[70788] = { title = "Wrapped Gold Band", description = "<This might be something Emila Bellocq is looking for.>", objectives = "" }
WordHunterWoW_QuestEN[70789] = { title = "Finely Carved Wing", description = "<This might be something Emila Bellocq is looking for.>", objectives = "" }
WordHunterWoW_QuestEN[70790] = { title = "Stone Dragontooth", description = "<This might be something Emila Bellocq is looking for.>", objectives = "" }
