WordHunterWoW_QuestEN[70818] = { title = "New Dragonscale Equipment", description = "", objectives = "" }
WordHunterWoW_QuestEN[70819] = { title = "Renowned Explorer's Armor", description = "", objectives = "" }
WordHunterWoW_QuestEN[70820] = { title = "The Basecamp 'Pets'", description = "", objectives = "" }
WordHunterWoW_QuestEN[70821] = { title = "Skitterfly Riding", description = "", objectives = "" }
WordHunterWoW_QuestEN[70822] = { title = "Lost Expedition Scouts", description = "", objectives = "" }
WordHunterWoW_QuestEN[70828] = { title = "Wayfinder's Compass", description = "", objectives = "" }
WordHunterWoW_QuestEN[70829] = { title = "Cataloging Expeditions", description = "", objectives = "" }
WordHunterWoW_QuestEN[70830] = { title = "Packing for a Climb", description = "", objectives = "" }
WordHunterWoW_QuestEN[70831] = { title = "Researching in Comfort", description = "", objectives = "" }
WordHunterWoW_QuestEN[70832] = { title = "One of Us Now", description = "", objectives = "" }
WordHunterWoW_QuestEN[70833] = { title = "Rumors of the Jeweled Whelplings", description = "", objectives = "" }
WordHunterWoW_QuestEN[70834] = { title = "Titled Story", description = "", objectives = "" }
WordHunterWoW_QuestEN[70835] = { title = "Sturdy Expedition Shovel", description = "", objectives = "" }
WordHunterWoW_QuestEN[70836] = { title = "Siege on Dragonbane Keep", description = "Help the Obsidian Outcasts reclaim Dragonbane Keep.", objectives = "" }
WordHunterWoW_QuestEN[70837] = { title = "Follow the Clues", description = "<Investigator Erima reviews the map.>\n\nIt is clear what the X scrawled over the Seat of the Aspects represents.\n\nBut there is also a circle drawn around the Misty Vale. Perhaps this is the rebels' next target? Or a base of operations.\n\nOnly one way to find out. Meet me at the Vale.", objectives = "" }
WordHunterWoW_QuestEN[70838] = { title = "Rebels With a Cause", description = "The rebel staging ground... we have been looking for this very place. How fortunate for us that their saboteur's carelessness led us here.\n\nI cannot believe my brethren would stoop to working with the Primalists. We cannot let this stand. Take out the rebels and their Primalist friends before they can cause any further chaos.", objectives = "" }
WordHunterWoW_QuestEN[70839] = { title = "The Search for Titan Relics", description = "", objectives = "" }
WordHunterWoW_QuestEN[70842] = { title = "Detonation Locations", description = "I am sure that the rebels are documenting their plans for future attacks. We must find out what they are attempting to do before it happens.\n\nSearch their camp for any marked maps like the one we found in Valdrakken.", objectives = "" }
WordHunterWoW_QuestEN[70843] = { title = "Ruin the Runestones", description = "<This runestone is strikingly similar to the one a rebel tried to plant in Valdrakken.\n\nThough this stone is unfinished, you spy caches of completed runestones off in the distance.\n\nIf you destroy these caches the rebels will not be able to put them to use.>", objectives = "" }
WordHunterWoW_QuestEN[70845] = { title = "In Tyr's Footsteps", description = "Keeper Tyr planned for all eventualities. He suspected there would be a need to empower the craftspeople of the realm some day, thus he created the Engine of Innovation. It possesses the ability to create a unique material that can help an item achieve expertise beyond that of mortal ability.\n\nTo ensure his engine would not be misused he created me to oversee any who sought its power. Only those worthy will be able to unlock the engine's full potential. \n\nAre you equal to the challenge?", objectives = "" }
WordHunterWoW_QuestEN[70847] = { title = "Ancient Obsidian Charm", description = "<Talonstalker Kavia might want this.>", objectives = "" }
WordHunterWoW_QuestEN[70848] = { title = "Forgotten Dragon Crest", description = "<Exadria might want this.>", objectives = "" }
WordHunterWoW_QuestEN[70849] = { title = "This Calls for a Specialist", description = "Lubbins is doing lots better now, but I think he still needs some more help. \n\nA little bit ago I met a super smart Dragonscale Expedition explorer named Haniko who works with proto-drakes all the time. She's a pet trainer, too. I bet she could help Lubbins more! \n\nI think she was going to the Waking Shores. I bet if you go there you'll find her. \n\nI'm so happy I was able to help you! \n\n<she waves happily>\n\nGoodbye! Good luck, Lubbins.", objectives = "" }
WordHunterWoW_QuestEN[70850] = { title = "Maldra's in Hot Water", description = "Excellent work. While you were off disrupting things I was scouting the camp. I did not expect to find my old friend Maldra Flametongue.\n\nI knew she was missing, but the rumors said she had joined the rebels. From what I could see, though, she is their captive!\n\nWe cannot leave her here. Rescue her from the dragonspawn holding her captive!", objectives = "" }
WordHunterWoW_QuestEN[70851] = { title = "Born to Be Wilder", description = "There's a lot of information you need to know. Let's have a talk and then we can decide what's best for Lubbins.", objectives = "" }
WordHunterWoW_QuestEN[70853] = { title = "A Friend for Lubbins", description = "Like we talked about, Lubbins needs two things: a buddy and a battle.\n\nI think we can get him both at the same time.\n\nThis area is a prime mating ground for Shyflys. If you look around a bit, you're sure to find a bunch.\n\nRemember, you need to weaken it before you can capture it with your trap.\n\nCome back when you have one. It might be a bit bruised after your battle, but I've got some battle-training stones that will fix 'em right up!", objectives = "" }
WordHunterWoW_QuestEN[70854] = { title = "So How Did It Go?", description = "You've done well, {name}. Lubbins is doing much better and is in excellent spirits. \n\nJyhanna will want to know, so go back and give her the good news!", objectives = "" }
WordHunterWoW_QuestEN[70856] = { title = "Kill it with Fire", description = "These vile spiders lay their eggs in corpses.\n\nAnd sometimes the living.\n\nWe've seen several bodies of Sundered Flame who have fallen victim to them.\n\nWe can't let those eggs hatch if we want to survive here and defeat the Sundered Flame.\n\nTake this torch. It is imbued with the power of air and fire. Point it in the direction of what you want scorched, and it will do the rest.\n\nThe Tuskarr don't mess around with spiders. I came prepared.", objectives = "" }
WordHunterWoW_QuestEN[70858] = { title = "Back into the Action", description = "All right, the antidote is ready. I'll keep Alia steady. You pour what's in the vial into her mouth.\n\nI hope she will live... we'll need her magic to track down this artifact.", objectives = "" }
WordHunterWoW_QuestEN[70859] = { title = "What the Guardian Beholds", description = "I appreciate your aid, {class}. I was the Kirin Tor mage who first discovered this artifact, Valthrux, and the Sundered Flame's plans.\n\nThe retrieval and study of this supposedly sentient and powerful artifact is of the utmost importance, and mark my word, I shall be the one to do it.\n\nThe Sundered Flame guess at its location, but I've used my magic to find a path for us.\n\nThere is a corrupted guardian nearby that holds a magic shard connected to Valthrux. I can use it to find the rest of the artifact.", objectives = "" }
WordHunterWoW_QuestEN[70871] = { title = "Iskaaran Fishing Net", description = "I see you're getting along with the villagers.\n\nYou seek to learn more about our ways of fishing you say? Well, first of all no one fishes with their bare hands. I can craft you a good, strong net worthy of an Iskaaran.", objectives = "" }
WordHunterWoW_QuestEN[70873] = { title = "Chasing Waterfalls", description = "The real threat lies in the Emberslate Cavern. This is where they carve those runestones and infuse them with primal fire.\n\nNo doubt you noticed the blazing wall of flame that blocks the entrance. I cannot dispel it, however I may be able to do something to help. I believe that with the proper application of Fallingwater, we can pass through it safely.\n\nHarvest water motes from the nearby elementals.", objectives = "" }
WordHunterWoW_QuestEN[70874] = { title = "To Breach a Fire Wall", description = "The rebels inside the cavern have been imbued with an elemental blessing, allowing them to safely pass through the wall of flame. I can grant you that same boon.\n\nDo not worry; I have seen the blessing granted many times. It shouldn't be any problem to recreate it effectively.", objectives = "" }
WordHunterWoW_QuestEN[70875] = { title = "Worst of the Worst", description = "The rebels in the Emberslate Cavern have an unflinching loyalty to the Primalists, and are therefore the greatest threat to Valdrakken.\n\nEliminate them, and any elementals they have unleashed.", objectives = "" }
WordHunterWoW_QuestEN[70876] = { title = "Fracture the Foci", description = "If Maldra speaks the truth, the rebels are creating the runestones in the Emberslate Cavern.\n\nGiven the nature of these devices, we know there must be Primalist foci involved.\n\nDestroy the foci. You will know them when you see them.\n\nThe rebels cannot be allowed to create any more weapons of destruction.", objectives = "" }
WordHunterWoW_QuestEN[70877] = { title = "A Quack in Time", description = "<This duckling is despondent, quietly quacking to itself as its eyes dart around in fear.>\n\n<Maybe the ecologists would know how to help it?>", objectives = "" }
WordHunterWoW_QuestEN[70878] = { title = "Ring of Fire", description = "In the deepest recesses of the Emberslate Cavern, the Primalists erected a fiery portal from which they unleash elementals.\n\nI can seal it, but my actions will draw the ire of whatever is on the other side. Including the revenant Magmaticus the Primalists have been aiding.\n\nI will need your protection if we are to stop them.", objectives = "" }
WordHunterWoW_QuestEN[70879] = { title = "Report on the Rebels", description = "I am impressed with what you have accomplished today. I hope you agree, {name}.\n\nWe have successfully shut down the nefarious activities of these Primalist-allied rebels. For now at least. We will need to keep a close watch on any dissent going forward.\n\nReturn to Captain Drine at your earliest convenience. She will want our full report.", objectives = "" }
WordHunterWoW_QuestEN[70880] = { title = "To Cook With Finery", description = "", objectives = "" }
WordHunterWoW_QuestEN[70881] = { title = "Fourth Challenge of Tyr: Resourcefulness", description = "The engine is close to reaching its full potential. All it requires now is a power core to process any essence put into it more efficiently.\n\nTyr left the knowledge of such devices with Watcher Irideus. Go into the Halls of Infusion and find him. I am sure he will help you with whatever you need.", objectives = "" }
WordHunterWoW_QuestEN[70882] = { title = "Renown Supplies", description = "", objectives = "" }
WordHunterWoW_QuestEN[70883] = { title = "A Hand in Cultivation", description = "Greetings mortal, I have word from our Head Gardener Gryrmpech. The word is that the gardens are in a state of chaos, but I don't know if that is abnormal.\n\nThey assured me that they have it in hand--actually, 'in shovel' is the phrase they used. I am not sure what they are meaning; I am sure they will fill you in. Please, seek them out and they will outfit you appropriately for the situation.", objectives = "" }
WordHunterWoW_QuestEN[70884] = { title = "Taking Back", description = "", objectives = "" }
WordHunterWoW_QuestEN[70885] = { title = "Renown Supplies", description = "", objectives = "" }
WordHunterWoW_QuestEN[70886] = { title = "Now THIS is Dragon Racing!", description = "", objectives = "" }
WordHunterWoW_QuestEN[70887] = { title = "Feeling Freedom", description = "", objectives = "" }
WordHunterWoW_QuestEN[70888] = { title = "Rubbing Shoulders With The Best", description = "", objectives = "" }
WordHunterWoW_QuestEN[70889] = { title = "Crafting for Expertise", description = "", objectives = "" }
WordHunterWoW_QuestEN[70890] = { title = "I'm Going on an Adventure!", description = "", objectives = "" }
WordHunterWoW_QuestEN[70891] = { title = "Fitting In", description = "", objectives = "" }
WordHunterWoW_QuestEN[70892] = { title = "Crafting Your Start", description = "", objectives = "" }
WordHunterWoW_QuestEN[70893] = { title = "Community Feast", description = "Our community feast is happening RIGHT NOW! This is when everyone pitches in and makes the best soup we can.\n\nYou should join us!", objectives = "" }
WordHunterWoW_QuestEN[70895] = { title = "Soaring in Style", description = "", objectives = "" }
WordHunterWoW_QuestEN[70896] = { title = "Waist Not, Want Not", description = "", objectives = "" }
WordHunterWoW_QuestEN[70897] = { title = "A Coming of Age", description = "", objectives = "" }
WordHunterWoW_QuestEN[70899] = { title = "Fifth Challenge of Tyr: Ingenuity", description = "As this was not how the Power Core was supposed to be obtained, it requires a re-attunement to the energies of the Engine. The resonance frequencies of the denizens of Tyrhold should bring the core to its full potential once more.\n\nThough I do not wish to sacrifice more of my brethren, I believe this is the only way this challenge may be completed.", objectives = "" }
WordHunterWoW_QuestEN[70900] = { title = "Innovating the Engine", description = "Tyr believed that the Engine of Innovation would be necessary for the battles to come. \n\nYou have proven yourself worthy and overcome all the challenges set before you. You may now unlock the Engine's full potential.", objectives = "" }
WordHunterWoW_QuestEN[70901] = { title = "A Collection of Creatures", description = "", objectives = "" }
WordHunterWoW_QuestEN[70902] = { title = "Crafting for Expertise", description = "", objectives = "" }
WordHunterWoW_QuestEN[70903] = { title = "Wielding Titanic Might", description = "", objectives = "" }
WordHunterWoW_QuestEN[70904] = { title = "Variety is the Spice of Life", description = "", objectives = "" }
WordHunterWoW_QuestEN[70905] = { title = "Flying with Our Colors", description = "", objectives = "" }
WordHunterWoW_QuestEN[70909] = { title = "Crafting for Expertise", description = "", objectives = "" }
WordHunterWoW_QuestEN[70910] = { title = "Mysteries in Paper and Glass", description = "", objectives = "" }
WordHunterWoW_QuestEN[70911] = { title = "Armored and Ready", description = "", objectives = "" }
WordHunterWoW_QuestEN[70912] = { title = "The Accord's High Standards", description = "", objectives = "" }
WordHunterWoW_QuestEN[70913] = { title = "To Bear Our Mantle", description = "", objectives = "" }
WordHunterWoW_QuestEN[70914] = { title = "The Breadth of Dragon Weaponry", description = "", objectives = "" }
WordHunterWoW_QuestEN[70915] = { title = "Crowning Achievement", description = "", objectives = "" }
WordHunterWoW_QuestEN[70916] = { title = "Beknownst and Glorious", description = "", objectives = "" }
WordHunterWoW_QuestEN[70917] = { title = "A Shoulder to Quack On", description = "<This duckling is full of nervous energy. It seems eager to escape its current predicament.>\n\n<Maybe the ecologists would know how to help it?>", objectives = "" }
WordHunterWoW_QuestEN[70918] = { title = "Quack for Your Life", description = "<This duckling is quacking frantically. If someone doesn't help it, the gorlocs will surely get annoyed!>\n\n<Maybe the ecologists would know how to help it?>", objectives = "" }
WordHunterWoW_QuestEN[70919] = { title = "Quacking Out for a Hero", description = "<This duckling has been bubbled so long that it's fallen fast asleep. It quacks softly as it snores.>\n\n<Maybe the ecologists would know how to help it?>", objectives = "" }
WordHunterWoW_QuestEN[70930] = { title = "All Tea, No Shadeleaf", description = "Today is a celebration of tea - brewed, iced, and otherwise! Extravagant little cakes and biscuits too.\n\nBut there is a rare ingredient of the Isles I feel could add a whole new dimension of flavor! Deep within the crawler-infested domain of the Shiverweb Vale is a bush laden with the most wondrously uplifting leaf: Coldsnap Sagittate.\n\nThe Dragonscale Expedition was exploring that area recently. Perhaps one of them could assist?", objectives = "" }
WordHunterWoW_QuestEN[70931] = { title = "Whispered Fragments", description = "I believe Valthrux is trying to communicate to us through the shard we recovered.\n\nWe can use this to our advantage as long as we keep our minds guarded from the artifact's influence.\n\nI was wrong about the Sundered Flame. They have unfortunately collected several shard fragments already. \n\nValthrux's whispers claim they're close to finding its location.\n\nGo and recover the shards from the Sundered Flame before they reach the artifact!", objectives = "" }
WordHunterWoW_QuestEN[70932] = { title = "The Life of Spice", description = "To many, meat is essential for any true meal. But what is the essential for any true meat dish?\n\nSpice!!\n\nA spice that surpasses all others in terms of flavor, texture, and rarity lies within these Isles. Unfortunately, it can only be found on elementals that dwell in the depths of the Obsidian Stronghold. It's an area currently occupied by the Djaradin.\n\nPerhaps you can consult with a peculiar troll I met while passing through there. I believe his name was... Griftah.", objectives = "" }
WordHunterWoW_QuestEN[70936] = { title = "Stolen Tuskarr Totems", description = "Have you come to return our totems?", objectives = "" }
WordHunterWoW_QuestEN[70937] = { title = "What Valthrux Once Was", description = "<To'tik whispers to you.> \n\nI don't like this. Mysterious artifacts whispering promises of greatness does not sound good.\n\nBut we can't just walk away... otherwise the Sundered Flame will get their hands on it. Whatever \"it\" is...\n\nI'm familiar with ruins like this. The blue dragons often left behind notes on their work. Keep your eyes open, and you may find some around.\n\nWe can use whatever evidence you find to warn Alia and Kattigat.", objectives = "" }
WordHunterWoW_QuestEN[70938] = { title = "Community Feasts", description = "There you are, {name}! The soup's on! \n\nYou better hurry up and get to Iskaara. Big Kinook has been looking for you. \n\nOne time he told me to get a slimy, icky spinefish for the soup and I didn't want to, so I yelled: \"No, chef!\"\n\nHe was so mad I thought he was going to throw me in the soup!", objectives = "" }
WordHunterWoW_QuestEN[70939] = { title = "Cooking Utensils", description = "", objectives = "" }
WordHunterWoW_QuestEN[70940] = { title = "Tuskarr Champion's Tales", description = "", objectives = "" }
WordHunterWoW_QuestEN[70941] = { title = "Fishing Holes", description = "Hello again! Did you know I'm gonna be the bestest fisherman in the village? I caught a giant piranha once. It tried to eat my face!\n\n<Rowie looks around distractedly.>\n\nOh yeah! I have a message for you. Nunvuq, back in Iskaara, wants to tell you about fishing holes.", objectives = "" }
WordHunterWoW_QuestEN[70942] = { title = "Highland Fishing", description = "", objectives = "" }
WordHunterWoW_QuestEN[70943] = { title = "Harpooning", description = "", objectives = "" }
WordHunterWoW_QuestEN[70944] = { title = "Ice Fishing", description = "", objectives = "" }
WordHunterWoW_QuestEN[70945] = { title = "Netting More", description = "", objectives = "" }
WordHunterWoW_QuestEN[70946] = { title = "No One May Wield It", description = "What you found makes it sound like the artifact's power has doomed everyone who has used it so far.\n\nThe dragonspawn who lived here killed each other over it. The Sundered Flame seem like they're also getting corrupted by its influence too.\n\nThis isn't an artifact we need to recover. It's one that needs to be destroyed before it can harm anyone else.\n\nWe must convince Alia and Kattigat.", objectives = "" }
WordHunterWoW_QuestEN[70948] = { title = "Hook, Line, and Swelter!", description = "", objectives = "" }
WordHunterWoW_QuestEN[70950] = { title = "Skewering Even Bigger Fish", description = "", objectives = "" }
WordHunterWoW_QuestEN[70951] = { title = "Tackling the Tackle Box", description = "", objectives = "" }
WordHunterWoW_QuestEN[70952] = { title = "Abandoned... or Hidden Caches", description = "", objectives = "" }
WordHunterWoW_QuestEN[70953] = { title = "Tuskarr Headwear", description = "", objectives = "" }
WordHunterWoW_QuestEN[70954] = { title = "Mounting Curiosity", description = "", objectives = "" }
WordHunterWoW_QuestEN[70955] = { title = "Fascinating Fliers", description = "", objectives = "" }
WordHunterWoW_QuestEN[70956] = { title = "Of Azure Scales", description = "", objectives = "" }
WordHunterWoW_QuestEN[70957] = { title = "The Sea Out West", description = "Enjoying the greenery around our little scenery, {name}?\n\nIt reminds me of a dish I once tasted from a pair of dryad sisters and their kind treant friend. Sugarbough was their name! A resident of Shady Sanctuary on the western coast of the Plains.\n\nIt was a medley of fresh herbs, veggies, and spices. At the heart of this dish was the most delicious layer of sea kelp you have ever tasted!\n\nWhat? Never tasted sea kelp before? Well you simply must seek some out. And bring back enough to share, please!", objectives = "" }
WordHunterWoW_QuestEN[70958] = { title = "Finest Fungi at the Feast", description = "Fine dining is all about using the finest techniques on the finest ingredients, naturally. The food composed for fine dining is oft locked behind wealth and means, but we would never allow that at The Ruby Feast!\n\nMorsel has informed me of a perfect ingredient for today's theme. One so rare, so exquisite, that it... does not exist yet! Tantalizing, no?\n\nThe bronze have uncovered a portal to a dangerous future. One where a black truffle with untold flavor exists!\n\nYou must go!", objectives = "" }
WordHunterWoW_QuestEN[70959] = { title = "Cute and Cuddly", description = "", objectives = "" }
WordHunterWoW_QuestEN[70960] = { title = "Trader's Apparel", description = "", objectives = "" }
