WordHunterWoW_QuestEN[70965] = { title = "Wanted: Watcher's Golden Girdle", description = "<The posted sign is written in beautiful calligraphy.>\n\nThe archivists humbly request that all expedition members seek out the Watcher's Golden Girdle for our artifact archives.\n\nIf acquired, please deliver to Cataloger Jakes for processing and compensation.\n\nYou may wish to start your search at our northern dig site, where Elementalist Taiyang has reported a malfunctioning Watcher causing trouble.", objectives = "" }
WordHunterWoW_QuestEN[70966] = { title = "Trading Made Easier", description = "", objectives = "" }
WordHunterWoW_QuestEN[70967] = { title = "Fishy Entertainment", description = "", objectives = "" }
WordHunterWoW_QuestEN[70968] = { title = "Of the Cloth, of the Community", description = "", objectives = "" }
WordHunterWoW_QuestEN[70969] = { title = "Becoming One of Our Community", description = "", objectives = "" }
WordHunterWoW_QuestEN[70970] = { title = "Good Intentions", description = "I may know where the artifact is. Alia was whispering frantically when you brought all the shards back.\n\nShe kept saying something about a \"cave\" and how the spiders seemed attracted to it.\n\nThere's no cave in the area in front of us... which leads me to believe there might be one deeper in the ruins.\n\nWe'll stay here and keep your escape path open, {name}. Please save Alia and destroy this cursed artifact.", objectives = "" }
WordHunterWoW_QuestEN[70971] = { title = "Arms for Every Arm", description = "", objectives = "" }
WordHunterWoW_QuestEN[70972] = { title = "Our Loyal, Lanky Steeds", description = "", objectives = "" }
WordHunterWoW_QuestEN[70975] = { title = "Wanted: Everblazing Fireheart", description = "<The posted sign is written in beautiful calligraphy.>\n\nThe archivists humbly request that all expedition members seek out the Everblazing Fireheart for our artifact archives.\n\nIf acquired, please deliver to Cataloger Jakes for processing and compensation.\n\nSome expedition members have reported seeing a massive fire elemental under control of the Primalists in the north that may provide an opportunity to acquire one.", objectives = "" }
WordHunterWoW_QuestEN[70976] = { title = "Slacking and Sledding", description = "As you may know, the children of Iskaara are fiercely independent. They learn from a young age to fend for themselves.\n\nIt's a rite of passage for many of the older kids to sneak off to the iceberg southeast of here. Kiopo, the eldest of our children, is out there right now. Tell him I sent you, and he should offer you one of our sleds!\n\nAh, that reminds me of my younger days... out there with my friends...", objectives = "" }
WordHunterWoW_QuestEN[70977] = { title = "Scaps Packs", description = "", objectives = "" }
WordHunterWoW_QuestEN[70978] = { title = "Dragon Isles Champion's Tales", description = "", objectives = "" }
WordHunterWoW_QuestEN[70981] = { title = "Savory Seas", description = "The smell of the sea! Do you smell it, {name}? Do you smell the multitude of minerals, laden with thick sea salt? Do you??\n\nSuspiciously absent from the delights here today is a rare variety of fish I once tasted near the Iskaara's home in Azure Span. Two Tuskarr fellows were simply roasting one over a fire, and it filled that glacial tundra with the most savory aroma!\n\nSee if you can not find one for us. I know our patrons will be just as ensorcelled by the sea's flavor as I was that day.", objectives = "" }
WordHunterWoW_QuestEN[70985] = { title = "The Lonely Scout", description = "I know, I know, it's silly. A centaur and a dryad, right? We can't be more different.\n\nBut ever since I first laid eyes on the Emerald Gardens, I really have wanted to get to know one better. I just can't seem to say or do anything to keep them interested in me.\n\nI've heard they're into... plants. And cute baby animals. And maybe killing poachers, but I don't even know where to start.\n\nPlease, you can talk to them, right? Could you ask around and find out what they like? Then maybe I can have a shot.", objectives = "" }
WordHunterWoW_QuestEN[70987] = { title = "Hearts of Starch", description = "What could be better than a meal you can carry while you explore?\n\nStreet foods are the essence of busy cities this great world over. But not every meal is set for mobility. The core of great on-the-go cuisines is a starch that will hold strong while moving. Breads, potatoes, rices, and beyond are the heart of hand-sized dining.\n\nI would like to treat my Pandaren peer here to a flavorful specimen known as Leapmaize. Morsel introduced it to me when we first met near the titan ruins in the Waking Shores.", objectives = "" }
WordHunterWoW_QuestEN[70988] = { title = "The Egg's the Thing", description = "\"All the world's an egg.\" That is how the saying goes, right?\n\nEggs! They are the core of confections, and one of the great catalysts of culinary creation! They are the fat that puts acids, heats, and salts on their highest pedestals, to their highest potentials!\n\nOur Isles are teeming with fowl of immense strength, but the Breezehunters of the Plains lay eggs primed with flavor!\n\nThey often nest on the Eastern side of the Plains, so ask around the outpost in Rusza'thar Reach.", objectives = "" }
WordHunterWoW_QuestEN[70989] = { title = "Part of a Pack", description = "Perhaps your bakar needs to be shown the proper way to hunt by his own kind.\n\nYou may borrow some of our trained bakar. Take them and bring down the drake that circles the area. \n\nLet us see how Taivan behaves in a pack!", objectives = "" }
WordHunterWoW_QuestEN[70990] = { title = "If There's Wool There's a Way", description = "While most of our wool comes from our own argali flocks, we do sometimes need to pull from the land when the flock grows thin.\n\nThe nearby plains are home to wild argali - they tend to be more temperamental than our clan's flock. If you could take this blade and attempt to shear their wool, it would be a great service to Aylaag.", objectives = "" }
WordHunterWoW_QuestEN[70992] = { title = "Wanted: Lost Tuskarr Kite", description = "<The posted sign is written in beautiful calligraphy.>\n\nThe archivists humbly request that all expedition members seek out the Lost Tuskarr Kite for our artifact archives.\n\nIf acquired, please deliver to Cataloger Jakes for processing and compensation.\n\nSome expedition members have reported seeing such a kite attached to a tuskarr transport along the western coast, but none have been able to reach it as the transport keeps it aloft and out of reach when traveling.", objectives = "" }
WordHunterWoW_QuestEN[70994] = { title = "Drainage Solutions", description = "Want the honor of assisting world-renowned Head Geologist of the Dragonscale Expedition? That's right. I'm exactly who you think I am. And I'm in a bind!\n\nI was perusing this river for new sedimentary samples, but then the water started to walk away with the most interesting pieces of silt!\n\nI have here my patented water entrapment device, but it's in desperate need of someone to march around and siphon those elementals into it.\n\nThink you're up to the task?", objectives = "" }
WordHunterWoW_QuestEN[70995] = { title = "Wanted: Fenistrasza's Skull", description = "<The posted sign is written in beautiful calligraphy.>\n\nThe archivists humbly request that all expedition members seek out Fenistrasza's Skull for our artifact archives.\n\nIf acquired, please deliver to Cataloger Jakes for processing and compensation.\n\nSome expedition members have reported seeing it in the possession of an outcast djaradin in the western mountains, but no one has been able to convince him to part with it yet.", objectives = "" }
WordHunterWoW_QuestEN[70996] = { title = "A Little Kelp for My Friends", description = "Well gosh, it sure sounds like Grimtusk is in a pickle. I'd say I'm done with conflicts on the mainland, but...\n\nFrostbite and I have got a history. And a score to settle.\n\nOh, fiddle! I can't leave the others here undefended... We've an issue with an elemental causing trouble at the beach. I'm the only one who can keep him at bay. Slippery fella... literally.\n\nTell you what. If you will deal with the elemental for me, I'll mosey on over to Grimtusk's camp.\n\nWhaddaya say, champ?", objectives = "" }
WordHunterWoW_QuestEN[70997] = { title = "Wanted: Ruby Lifeband", description = "<The posted sign is written in hasty scratches.>\n\nExpedition members have reported a Primalist attack on the Ruby Life Pools, threatening the destruction of countless artifacts stored by our dragon allies there.\n\nToddy and Naleidea urge all combat-ready members to join the fight, and seek out the Ruby Lifeband if you are able.\n\nIt is a unique, priceless artifact that must be preserved.\n\nIf acquired, please deliver to Cataloger Jakes for safekeeping until the dragons may safely retrieve it.", objectives = "" }
WordHunterWoW_QuestEN[71000] = { title = "Barst Recruited", description = "Well a deal's a deal. If Grimtusk needs a hand killing Frostbite once and for all, then I'm in.\n\nWhat hate I have left in me I reserve for Frostbite. Did Grimtusk tell you what happened? \n\nAll of us who hunted with Grimtusk thought we were unstoppable. Until we met Frostbite. \n\nFrostbite didn't just defeat us. He humiliated us in front of everyone in the hideaway. \n\nWe were all defeated and left bloodied and battered at the hideaway. Frostbite used us as an example.\n\nNow it's time for payback.", objectives = "" }
WordHunterWoW_QuestEN[71001] = { title = "Wanted: Earthbound Primordial Core", description = "<The posted sign is written in beautiful calligraphy.>\n\nThe archivists humbly request that all expedition members seek out the Earthbound Primordial Core for our artifact archives.\n\nIf acquired, please deliver to Cataloger Jakes for processing and compensation.\n\nRecent learnings from records recovered from the Obsidian Citadel indicate it may have once been stored in the Dragon's Hoard of Neltharus, although it's current location is unclear.", objectives = "" }
WordHunterWoW_QuestEN[71002] = { title = "Best Spell Ever", description = "<Gently levitating and emanating with arcane magic, this enchanted book contains countless spells and enchantments created by the chaotic yet beautiful mind of Millhouse Manastorm.>", objectives = "" }
WordHunterWoW_QuestEN[71004] = { title = "Wanted: Ohuna Mass-Binding Totem", description = "<The posted sign is written in beautiful calligraphy.>\n\nThe archivists humbly request that all expedition members seek out the Ohuna Mass-Binding Totem for our artifact archives.\n\nIf acquired, please deliver to Cataloger Jakes for processing and compensation.\n\nExpedition members have reported a particularly powerful Primalist in the Windsong Rise of the Ohn'ahran Plains, who appears to wield the rumored powers of this totem.", objectives = "" }
WordHunterWoW_QuestEN[71005] = { title = "Wanted: Fangfall", description = "<The posted sign is written in beautiful calligraphy.>\n\nThe archivists humbly request that all expedition members seek out the legendary blade Fangfall for our artifact archives.\n\nIf acquired, please deliver to Cataloger Jakes for processing and compensation.\n\nThe sword was reportedly fractured long ago, but expedition members have reported that the Sundered Flame is recovering fragments of it in ruins of the Ohn'aran Plains.", objectives = "" }
WordHunterWoW_QuestEN[71007] = { title = "Wanted: Disoriented Wishtail", description = "<The posted sign is written in beautiful calligraphy.>\n\nThe archivists humbly request that all expedition members seek out the legendary Wishtail for our artifact archives.\n\nIf acquired, please deliver to Cataloger Jakes for processing and compensation.\n\nExpedition members have reported seeing a colorful fish matching its purported appearance inside a massive water elemental in Azure Span.", objectives = "" }
WordHunterWoW_QuestEN[71008] = { title = "Wanted: Stoneheart's Stone Heart", description = "<The posted sign is written in beautiful calligraphy.>\n\nThe archivists humbly request that all expedition members seek out Stoneheart's Stone Heart for our artifact archives.\n\nIf acquired, please deliver to Cataloger Jakes for processing and compensation.\n\nExpedition members have reported seeing Stoneheart in a cave of central Azure Span.", objectives = "" }
WordHunterWoW_QuestEN[71009] = { title = "Elementary, My Dear Drakonid", description = "Grimtusk wants to take another crack at Frostbite, eh? I hate to turn him down, but I left that life behind for the life of a scholar.\n\nI'm trying to uncover the history--and make history. But I'm stumped by this esoteric riddle here in these ancient ruins. \n\nThe riddle is this: if you touch a nearby crystal, it says \"follow the pattern.\" But I haven't the faintest idea what that means!\n\nTell you what. If you can help me crack this riddle, I'll go help Grimtusk finish Frostbite off once and for all.", objectives = "" }
WordHunterWoW_QuestEN[71010] = { title = "Wanted: Temporal Spyglass", description = "<The posted sign is written in beautiful calligraphy.>\n\nThe archivists humbly request that all expedition members seek out the Temporal Spyglass for our artifact archives.\n\nIf acquired, please deliver to Cataloger Jakes for processing and compensation.\n\nExpedition members have reported overhearing a dwarf bragging about his magical spyglass in the inns of Southern Thaldraszus. We recommend focusing your search in that region.", objectives = "" }
WordHunterWoW_QuestEN[71011] = { title = "Wanted: Torrential Lily", description = "<The posted sign is written in beautiful calligraphy.>\n\nThe archivists humbly request that all expedition members seek out the Torrential Lily for our artifact archives.\n\nIf acquired, please deliver to Cataloger Jakes for processing and compensation.\n\nExpedition members have reported seeing a powerful Primalist in Gelikyr Overlook of Thaldraszus with a magical flower pinned to her collar. It is unknown if that is the legendary Torrential Lily, but it is a good place to start your search.", objectives = "" }
WordHunterWoW_QuestEN[71012] = { title = "Varsek Recruited", description = "Seems like I'll be able to solve the mysteries of this place just fine in the future. \n\nLet's just never speak of this to Old Grimtusk, OK?\n\nI'll make my way to his hideaway. I think I'll enjoy taking out some pent up aggression on Frostbite.", objectives = "" }
WordHunterWoW_QuestEN[71013] = { title = "No Vengeance on an Empty Stomach", description = "Now that we've gotten back to what we aimed to do, we need to have a talk tusk to tusk. That gnoll Frostbite? The one you spoke to?\n\nWe've got a history with him.\n\nThis may take awhile to explain. You go and get some fish while I talk, pup. We need to feed everyone. They need their strength for what's next.", objectives = "" }
WordHunterWoW_QuestEN[71014] = { title = "A Far Furbolg Friend", description = "Barst was one of the toughest furbolgs I've ever known. It says something about Frostbite that his pack beat him in a fight.\n\nLast I heard, Barst left for some island off the coast of Iskaara. Called it his \"retirement\" or some other garbage.\n\nTell Barst it's time to get back into action. \n\nOh, and don't be fooled by the way he talks. He'll tear you in two if you look at him wrong.", objectives = "" }
WordHunterWoW_QuestEN[71015] = { title = "All Brawn, No Brains", description = "Varsek is one of the toughest drakonids you'll ever meet. One of the dumbest ones too, but he'll never admit that.\n\nHe got spooked after Frostbite and started re-evaluating his life or... something. Said he never got to study the ruins left behind by his ancestors. Ran off to be a \"scholar\".\n\nGet Varsek back here. He doesn't belong there anyhow!", objectives = "" }
WordHunterWoW_QuestEN[71016] = { title = "Grimtusk's Sister", description = "Last is my sister, Naluki. She helps run the inn at Iskaara now.\n\nJust give her this letter. \n\nDon't open it.", objectives = "" }
WordHunterWoW_QuestEN[71017] = { title = "Naluki's Letter", description = "Let me guess, Grim told you not to open the letter, right?\n\nLooks like you did as you were told. No wonder he trusts you so much! \n\nGive him this fish head for me. He'll know what it means.", objectives = "" }
WordHunterWoW_QuestEN[71018] = { title = "Vault of the Incarnates: Break a Few Eggs", description = "Broodkeeper Diurna is somewhere within this fortress, no doubt watching over the vault from her chamber. If you can claim pieces of her greatstaff, it should allow us to assault her lair directly.\n\nThree should be enough. Four seems excessive.", objectives = "" }
WordHunterWoW_QuestEN[71019] = { title = "Vault of the Incarnates: Break a Few Eggs", description = "Broodkeeper Diurna is somewhere within this fortress, no doubt watching over the vault from her chamber. If you can claim pieces of her greatstaff, it should allow us to assault her lair directly.\n\nThree should be enough. Four seems excessive.", objectives = "" }
WordHunterWoW_QuestEN[71020] = { title = "Vault of the Incarnates: Break a Few Eggs", description = "Broodkeeper Diurna is somewhere within this fortress, no doubt watching over the vault from her chamber. If you can claim pieces of her greatstaff, it should allow us to assault her lair directly.\n\nThree should be enough. Four seems excessive.", objectives = "" }
WordHunterWoW_QuestEN[71022] = { title = "Reign of the Ram", description = "Since the argali don't seem to have much respect for Taivan, we should see if he can handle the herd's ram next.\n\nHe's the boss of all the argali here, and quite the stubborn thing. If Taivan can assert dominance over the ram, the herd will start obeying him.\n\nYou can find him just over there, on the hill. Good luck, Taivan. If this doesn't work, I'm afraid there's not much hope for him being a herder!", objectives = "" }
WordHunterWoW_QuestEN[71024] = { title = "Chaos and Commotion", description = "{name}! Did you hear the noise? There has been an incident on the bottom floor.\n\nOne of my trusted investigators, Erima, was there first. He will require assistance gathering evidence while he tries to interview the crowd.", objectives = "" }
WordHunterWoW_QuestEN[71025] = { title = "Against Overwhelming Odds", description = "Though you puny mortals have come to a truce, I have heard rumor that some of you still harbor grudges.\n\nIf you gather some friends, I know a place you can show the other side who is truly superior.\n\nAnd to make it interesting, if you are successful I have a prize for you.", objectives = "" }
WordHunterWoW_QuestEN[71026] = { title = "Against Overwhelming Odds", description = "Though you puny mortals have come to a truce, I have heard rumor that some of you still harbor grudges.\n\nIf you gather some friends, I know a place you can show the other side who is truly superior.\n\nAnd to make it interesting, if you are successful I have a prize for you.", objectives = "" }
WordHunterWoW_QuestEN[71027] = { title = "WANTED: Mara'nar the Thunderous", description = "Looking for a mighty hunter to take down a rampaging beast!\n\nA thunder lizard named Mara'nar the Thunderous worked his way from Thunderspine Thicket to Primordial Vale, disrupting local wildlife. It has electrified water, knocked down trees, and broken duck nests.\n\nThis menace must be stopped. Slay him and bring one of his plates to Khansguard Jebotai as proof.\n\nMay Ohn'ahra guide you.", objectives = "" }
WordHunterWoW_QuestEN[71028] = { title = "Hunting Tactics: Blessing of Ohn'ahra", description = "Your renown with the Maruuk grows. Listen closely, and I will teach you to call upon a blessing of Ohn'ahra to protect you and your allies.", objectives = "" }
WordHunterWoW_QuestEN[71029] = { title = "Hunting Tactics: Companion Training", description = "Your renown with the Maruuk grows once more. For your efforts, I will teach you to command your hunting companion more effectively in combat.", objectives = "" }
WordHunterWoW_QuestEN[71030] = { title = "Hunting Tactics: Shikaar Mentorship", description = "", objectives = "" }
WordHunterWoW_QuestEN[71031] = { title = "Hunting Tactics: Proof of Prowess", description = "", objectives = "" }
WordHunterWoW_QuestEN[71032] = { title = "Hunting Tactics: Apex Hunter", description = "", objectives = "" }
WordHunterWoW_QuestEN[71053] = { title = "Hermit Kill Quest", description = "Help! all these bunnies are eating my flesh! Please, kill them before they kill us all!", objectives = "" }
WordHunterWoW_QuestEN[71058] = { title = "Observing the Wind", description = "", objectives = "" }
WordHunterWoW_QuestEN[71060] = { title = "To Adorn Your Head", description = "", objectives = "" }
WordHunterWoW_QuestEN[71066] = { title = "A Useful Curiosity", description = "", objectives = "" }
WordHunterWoW_QuestEN[71067] = { title = "Whistling Rocks", description = "", objectives = "" }
WordHunterWoW_QuestEN[71073] = { title = "Mantle of Friendship", description = "", objectives = "" }
WordHunterWoW_QuestEN[71074] = { title = "Befriending Wings and Wind", description = "", objectives = "" }
WordHunterWoW_QuestEN[71075] = { title = "Understanding Their Grace", description = "", objectives = "" }
WordHunterWoW_QuestEN[71079] = { title = "Getting to the Point", description = "", objectives = "" }
WordHunterWoW_QuestEN[71083] = { title = "An Expected Unexpected Gift", description = "", objectives = "" }
WordHunterWoW_QuestEN[71085] = { title = "Representation Matters", description = "", objectives = "" }
WordHunterWoW_QuestEN[71089] = { title = "Get on the Horn", description = "", objectives = "" }
WordHunterWoW_QuestEN[71090] = { title = "From the Heart, For the Heart", description = "", objectives = "" }
WordHunterWoW_QuestEN[71091] = { title = "The Highest Honor", description = "", objectives = "" }
WordHunterWoW_QuestEN[71093] = { title = "Legacy of Tyr: Secrets of the Past", description = "To stop Raszageth from freeing the other Incarnates, the power of the Aspects must be restored.\n\nInconveniently, the Titans are rather preoccupied and Keeper Tyr is long dead.\n\nQueen Alexstrasza has suggested a plan. In the depths of the Badlands lies a Titan facility called Uldaman. Apparently allies of Tyr may have hidden a disc of his memories there.\n \nWord is that the place has been overrun by troggs. Gather your allies, head to Uldaman, and seize the disc in the name of the Dragon Queen!", objectives = "" }
WordHunterWoW_QuestEN[71094] = { title = "Help Is Our Way!", description = "Hiya! \n\nAre you also here to help? You look very helpful!\n\n<Heleth points to the injured dracthyr.>\n\nThat guy hurt his wing trying to fly all the way up here! He looks like one of those bad guys from downstairs, but I'm not scared of him! I'm gonna help him out anyway, because that's our way!\n\n<Heleth puffs out their chest.> \n\nI'll stand guard over him, while you go find some bandages!", objectives = "" }
WordHunterWoW_QuestEN[71095] = { title = "A Claw in Need", description = "Let's see what we can do to help this guy!\n\n<Heleth leans in close and whispers.>\n\nDon't worry, we aren't gonna let him take anything or stuff like that. Let's just have some fun!\n\nIt's been ages since anyone has come up here to check up on us. We're SO bored!\n\n<Heleth winks at you.> \n\nWhy don't you ask him what he wants?", objectives = "" }
WordHunterWoW_QuestEN[71096] = { title = "Is A Claw Indeed", description = "<Venderthven rubs his eyes and groans in pain.>\n\nFine. If you won't give it to me, you can do the work of figuring out how to make it work. \n\nI'll just take it from you when you're done. By force, if necessary.\n\nSo go ahead. Give it a shake or something.", objectives = "" }
WordHunterWoW_QuestEN[71097] = { title = "A Helping Claw", description = "Alright, you've charged the artifact. Let's turn it on.\n\nAnd stop giving me that look. Don't pretend like you aren't curious to see if it works. \n\nJust give that thing another shake, back away slowly, and let me finish the job.", objectives = "" }
WordHunterWoW_QuestEN[71135] = { title = "Loose Ends", description = "If there's anything I learned from my time out in the wilderness, it's that if you don't deal with an evil when you find it--if you don't break its bones and dig up its roots, it'll keep growing. And then it'll be harder to kill.\n\nThese mountains were plagued with Frostbite's existence when I was a young pup like you, and it will only get worse once he takes full control of the Snowhide tribe. \n\nI should have done something about him long ago, but we're the only ones who can right that mistake now.", objectives = "" }
WordHunterWoW_QuestEN[71138] = { title = "Waygate: Rusza'thar Reach", description = "An expeditionary member reported a dormant stone sighting atop a lookout in the Ohn'ahran Plains.\n\nUp fer an adventure?", objectives = "" }
WordHunterWoW_QuestEN[71139] = { title = "Glowing Arcane Jewel", description = "<This jewel seems to be quite powerful. There is an eerie glow to it.\n\nPerhaps it's best to deliver it to the Kirin Tor for it to be placed in a safe spot.>", objectives = "" }
WordHunterWoW_QuestEN[71141] = { title = "Gills with Gall", description = "Kad'irsza is reckless, but she knows her crabs. The gorlocs have gone too far!\n\nI noticed the gorlocs going to Gurblbrblr for everything. Notably, he is instructing them to take crabs prisoner. We cannot allow this to continue, for the balance of life, and for the safety of those who tend it.\n\nDefeat Gurblbrblr. Remove their means of expanding beyond this river!", objectives = "" }
WordHunterWoW_QuestEN[71143] = { title = "The Horde Slayer", description = "Wow! Keep it up, soldier! \n\nSlay a bit more Horde and you will go down in the record books among the Alliance. \n\nBut it won't be easy, the Horde have put a bounty on your head, so watch it!\n\nFor the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[71144] = { title = "The Alliance Slayer", description = "Yes! Keep going, keep slaying those Alliance dogs!\n\nSlay a bit more Alliance and you may set a new record, {class}.\n\nBut it won't be easy, the Alliance have put a bounty on your head, so watch it!\n\nFor the Horde!", objectives = "" }
WordHunterWoW_QuestEN[71146] = { title = "Continued Waygate Exploration", description = "<The explorer-in-training hands you a taut, rolled note. Upon investigating, it appears to be from an old friend, Thaelin Darkanvil, seeking your aid.\n\nBefore scurrying off, the critter extends its hand as if it were seeking a treat. Moments later, a loud screech rings out as the curious creature storms off empty handed.>", objectives = "" }
WordHunterWoW_QuestEN[71148] = { title = "Continued Waygate Exploration", description = "<The curious creature before you presents a note--signed and sealed by the Dragonscale Expedition.\n\nA call for assistance from a famed explorer, perhaps.>", objectives = "" }
WordHunterWoW_QuestEN[71149] = { title = "Continued Waygate Exploration", description = "<Surprisingly, the messenger did not leave you with a satchel or a note this time, rather a single item from Thaelin's personal collection.\n\nUpon further investigation, a tiny little message from Thaelin seeks your assistance once again.>", objectives = "" }
WordHunterWoW_QuestEN[71150] = { title = "Continued Waygate Exploration", description = "<The parchment emits an unpleasant, mold-like smell. After struggling to regain focus, it becomes clear Thaelin needs your assistance in seeking answers to newly discovered findings.\n\nThe only question that remains is what to do with this parchment of intolerable odor.>", objectives = "" }
WordHunterWoW_QuestEN[71151] = { title = "Continued Waygate Exploration", description = "<The letter is clean, crisp and bears the seal of the Dragonscale Expedition.\n\nThaelin Darkanvil requests your presence.>", objectives = "" }
WordHunterWoW_QuestEN[71152] = { title = "Back to the Main Hall", description = "Now that we've accessed the override consoles, we should be able to get past that barrier.\n\nI'll meet ye back in the main hall and we'll see this through!", objectives = "" }
WordHunterWoW_QuestEN[71155] = { title = "The Azure Vaults", description = "We have a problem, {name}.\n\nBeneath the Azure Archives rests the Azure Vault. In my life, I stored many important and dangerous magical curiosities in it.\n\nA large group of Sundered Flame have broken into the vault, convinced it holds some kind of secrets.\n\nPlease, you must go in there and stop this brazen assault before they unleash dangers they do not comprehend.\n\nThese thieves know not what lies within.", objectives = "" }
WordHunterWoW_QuestEN[71157] = { title = "Waygate: Skytop Observatory", description = "Word from some of our northern explorers is there's another o' those stones high atop the spire to the northeast.\n\nHeard it's quite difficult tae reach bein' so high up and all, but I'm sure ye can find a way!", objectives = "" }
WordHunterWoW_QuestEN[71161] = { title = "Waygate: Vakthros", description = "Received a report of another of them dormant stones in the wintry region tae the southeast.\n\nNow before ye go gettin' all excited just know this isn't a place most go willingly, but if ye feel the need fer adventure and possible death, this is fer you!\n\nSold ye on it enough yet? Good!\n\nToss on yer warmest attire, then head east until the chill of the wind tickles yer nose and keep goin'. You'll know yer close when ye start feelin' the toughness in yer breath and the chill in yer bones.", objectives = "" }
WordHunterWoW_QuestEN[71162] = { title = "Waygate: Algeth'era", description = "Another stone. Another spire.\n\nBest be gettin' along on yer journey. This one's quite a trek and dangerous tae boot! At least accordin' tae the ones who discovered it.\n\nAre ye up fer it?", objectives = "" }
WordHunterWoW_QuestEN[71165] = { title = "Waygate: Eon's Fringe", description = "Far across the land in the mountainous regions of Thaldraszus sits a little inn nestled on the mountainside. Just inside the entryway sits a long-forgotten, dormant stone.\n\nWhat say ye? Up fer another adventure, {name}?", objectives = "" }
WordHunterWoW_QuestEN[71178] = { title = "Waygate: Shady Sanctuary", description = "Our expedition reports a dormant stone out in the lush hillsides to the southwest. It's quite a journey, but worth sendin' someone with yer knowledge tae investigate.", objectives = "" }
WordHunterWoW_QuestEN[71179] = { title = "Look to the Overlook", description = "{name}, I have another task for you.\n\nThere have been reports of Primalist activity near the Gelikyr Post that threaten our control of Tyrhold.\n\nSpeak with Commander Thadezus and see how you can assist.", objectives = "" }
WordHunterWoW_QuestEN[71182] = { title = "Wayward Archivists", description = "You, dracthyr. \n\nTwo of your kin have been searching the archives just south of here. I have yet to introduce myself, and would appreciate the company.\n\nIf you have the time, I can meet you in the upper archive.", objectives = "" }
WordHunterWoW_QuestEN[71191] = { title = "Net Worth", description = "Alas, my fishing net was carried away by the stream. <Sigh> I'm not too keen to use fishing poles like my friends...\nIf you happen to find my fishing net around, bring it back to me.", objectives = "" }
WordHunterWoW_QuestEN[71192] = { title = "Predator Control", description = "Greetings friend!\n\nI've been looking for a good place to set up fishing nets around here, but it seems like the population of waddlers around here is too dense - they're eating away most of the juvenile fish before they get a chance to mature.\n\nI've made some effigies to scare at least some of those ravenous birds away. This will help us sustain the abundance of fish across the Dragonsprings. \n\nCan you help me set those up?", objectives = "" }
WordHunterWoW_QuestEN[71193] = { title = "Underwater Menace", description = "Did you see that? Underwater! A huge, armored, hungry beast! No way I'm getting near water with my net while that monstrosity lurks below. If you want, you can likely lure it out with a handful of Ominous Conches. Those shouldn't be too hard to catch.\n\nTo gain conchs, be sure to have your Iskaaran Harpoon handy as you fish in the Dragon Isles.", objectives = "" }
WordHunterWoW_QuestEN[71194] = { title = "Frogs of Fire", description = "I found a perfect spot for a fishing net, one problem bothers me though... Those Hornspikes. I'm pretty sure they will ravage the nets as soon as it's left alone. What do we do?\n\n...I've got an idea. We treat our lava fishing nets with Icicle Brew to make them heat-resistant. We just need to teach those hornspikes to keep away from that smell.\n\nToss a flask of Icicle Brew at a hornspike, and then deal some damage to them. Just make sure not to kill them, they won't learn if they're dead, would they?", objectives = "" }
WordHunterWoW_QuestEN[71195] = { title = "To Tame A Thunderspine", description = "I guess this is Lizi's new favorite spot. She hasn't been interested in coming back home. After all, she is a wild beast.\n\nI have to tell you... I haven't spoken to Meluun since we saved Lizi. I know she was right, but I don't know how to approach her. She doesn't seem to approve of anything I do. I know I have to focus more on my training.\n\nMeluun makes a stomping good curry that Lizi would love. Do you think you could ask her for it? She's usually working in the Ohn's house west of the springs.", objectives = "" }
WordHunterWoW_QuestEN[71196] = { title = "To Tame A Thunderspine", description = "I'm so happy that Lizi is safe and sound with us.\n\nHowever, her wounds are healing slower than expected. I hope that the magic inflicted upon her didn't cause permanent damage.\n\nCould you help me gather insect ichor? I know, it sounds gross! It's actually the base of many healing ointments.", objectives = "" }
WordHunterWoW_QuestEN[71197] = { title = "To Tame A Thunderspine", description = "Lizi is healed, but she's still nervous about leaving her spot. In the wild, she'd forage about a musken's weight of plants a day. It's impossible for me to do that! We need her to move out of the water and to the grasses.\n\nI'll keep trying to coax her out, but in the meantime, could you help me forage? I hear there are especially nutritious high-fiber leaves in the Emerald Gardens. Please bring back any you can find!", objectives = "" }
WordHunterWoW_QuestEN[71198] = { title = "To Tame A Thunderspine", description = "Lizi's doing so much better. She's moving around with ease and consuming everything edible in sight.\n\nI learned today that thunderspines enjoy eating fish--especially piranhas! How fascinating! It is how they keep the piranha population in check at home.\n\nWill you go fish some? Mind your fingers!", objectives = "" }
WordHunterWoW_QuestEN[71199] = { title = "To Tame A Thunderspine", description = "Everyone is curious about Lizi, but the truth is, she sticks out like a sore hoof. Lizi herself is starting to wander more and more, as if she's looking for something.\n\nShe mostly rests by the water on the mud. I'm sure it's fine, but I know thunderspines like to make a bedding from grasses.\n\nI've got an idea better than grasses. Will you help me gather wool from the plains? I'll weave her a blanket and some toys.", objectives = "" }
WordHunterWoW_QuestEN[71209] = { title = "Beast of the Plains", description = "I think Lizi is ready to be a beast of the plains again. She's so friendly to you and I now, but I can tell she wants to return to the wild.\n\nOne day, when I am a Windsage, I will explore all of the world beyond these springs. But first--my midseason initiate trials! How time flies.\n\nI made a saddle and reins from the wool you gathered. Lizi will be happy to come at your call.\n\nPlease take her on all the adventures, {name}.", objectives = "" }
WordHunterWoW_QuestEN[71210] = { title = "To Dragonbane Keep!", description = "<Flaps drops a slightly singed note into your hand.>\n\n{name}, the Obsidian Outcasts have heard tales of your bravery. Our former home, Dragonbane Keep, has fallen into djaradin hands. We can't let that stand. Join us in reclaiming our territory.\n\n- Boss", objectives = "" }
WordHunterWoW_QuestEN[71219] = { title = "The Wayward Waywatcher", description = "It seems some of our younger Waywatchers have grown lax in their duties of late.\n\nWaywatcher Nori has asked me to check in on her younger sister Alvi, who is stationed at the mouth of the Passage of Time. Apparently her recent performance has been less than satisfactory.\n\nIf you head east and happen to encounter Waywatcher Alvi, please remind her of the importance of her position, and let her know that her sister is rather worried about her.", objectives = "" }
WordHunterWoW_QuestEN[71226] = { title = "Kill  Rock Snails", description = "Help! all these bunnies are eating my flesh! Please, kill them before they kill us all!", objectives = "" }
WordHunterWoW_QuestEN[71227] = { title = "Aerial Challenges", description = "<Flaps flaps his wings excitedly, dropping both a note and a singed rodent at your feet.>\n\nDragonrider! Your flight prowess has become well known. Come test yourself in Aerial Challenges across the Dragon Isles.\n\nSpeak to any Bronze Timekeeper to get started.", objectives = "" }
WordHunterWoW_QuestEN[71229] = { title = "Call of the Plains", description = "<Roki drops a message into your hand.>\n\n{name}, Clan Aylaag has heard tales of your great deeds. We invite you to meet our clan and share our ways.\n\nHadari Khan", objectives = "" }
WordHunterWoW_QuestEN[71230] = { title = "Tuskarr Fishing Gear", description = "Hi again, {name}.\n\n<Rowie looks around and hums a little tune.>\n\nOh right! Tavio was making me a new net and said she could make you one too. She can make some other fishing gear too if you bring her all the stuff.\n\nYou should go talk to her.", objectives = "" }
WordHunterWoW_QuestEN[71231] = { title = "Call of the Hunt", description = "<Roki drops the note into your hand>\n\n{name}, Clan Shikaar invites you to the Grand Hunt. Meet with Trainer Frodrum in the Ohn'ahran Plains.", objectives = "" }
WordHunterWoW_QuestEN[71232] = { title = "Renown of the Dragon Isles", description = "There is still much that must be done to aid the Dragon Isles.\n\nI would ask you speak with Koszaru. He has much information regarding who needs help within this land.", objectives = "" }
WordHunterWoW_QuestEN[71233] = { title = "Falling Water", description = "I love waterfalls. \n\nWant to know what's better than a waterfall? \n\nTwo waterfalls. \n\nAnd the only thing better than that is... well, check out Three-Falls to the west of here and you'll see!\n\nThe innkeeper there is quite nice.", objectives = "" }
WordHunterWoW_QuestEN[71234] = { title = "Nook News", description = "You there, {race}. \n\nYou look well-travelled. \n\nMy cousin Wayun was bringing a catch over from Whaler's Nook and mentioned that some... strange folk have set up camp over there.\n\nThey appear to be behaving themselves, but would you mind checking in on Wayun?\n\nHe can be a bit salty.", objectives = "" }
WordHunterWoW_QuestEN[71235] = { title = "Field Mages", description = "Lok'tar, {race}. \n\nIf you have the time, we have two mages doing fieldwork nearby who I'm sure could use a hand.\n\nThis is a dangerous land in the best of times. \n\nThese are not the best of times.", objectives = "" }
WordHunterWoW_QuestEN[71238] = { title = "The Ruby Feast!", description = "Attention to all aspiring culinarians!\n\nDoes your heart desire the ultimate flavors of this world? Do you seek out opportunities for grand exploration? Are you willing to risk life and limb for complete strangers?\n\nIf this is you, come speak with the eminently distinguished, world-renowned chef duo, Rumiastrasza and Morsel! Currently hosting The Ruby Feast in the city of Valdrakken!", objectives = "" }
WordHunterWoW_QuestEN[71239] = { title = "Lost to the Skies", description = "I need a favor, and you look like the favor-doing type.\n\nAn ol' pal of mine, Harleen Chirpsnide, was supposed to meet me in the city a few days ago. We was planning to eat our way through The Ruby Feast, get a trim at the barbershop, then visit that swanky auction house they got here.\n\nBut she ain't shown up. She gets lost in her work plenty, but I'd feel a lot more comfortable knowing where she was.\n\nTry the mountains south of here. She mentioned she'd be swinging by on her way in.", objectives = "" }
WordHunterWoW_QuestEN[71241] = { title = "Duck, Duck, Trap", description = "The grove called the Primordial Vale is rich with the magic of the old dragons. A type of slyvern there are prized by my kin for their fur, but they are elusive and hard to find.\n\nInstead of having you try to track them down, you can find some of our hunting traps in the area. Use meat from the nearby waterfowl to reset them - I will send some of our clan to retrieve whatever gets caught.", objectives = "" }
WordHunterWoW_QuestEN[71242] = { title = "Supporting the Storm Researchers", description = "This looks like a large cluster of overflowing power from creatures within the Primalist Storm.\n\nThere's bound to be a researcher in Valdrakken who'll want this.", objectives = "" }
WordHunterWoW_QuestEN[72038] = { title = "Dragon Isles Supplies", description = "", objectives = "" }
WordHunterWoW_QuestEN[72048] = { title = "Dragon Isles Supplies", description = "", objectives = "" }
WordHunterWoW_QuestEN[72052] = { title = "Ruby Lifeshrine Loop - Reverse", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[72060] = { title = "Special Treatment", description = "<The mud mask looks curious about your intentions, but it is cornered on this branch!>", objectives = "" }
WordHunterWoW_QuestEN[72062] = { title = "Valducken", description = "Quack! Quack!\n\n<The mother duck is alerted to your presence.>\n\nQuack quack quack quack! Quack quack quack! Quack quack quack quack quack.\n\n<A gurgling noise from the duck's stomach interrupts her intense quacking. She does not have much food around for her ducklings as she attends to her nest. Perhaps addressing this problem will warm her up to you?>", objectives = "" }
WordHunterWoW_QuestEN[72063] = { title = "Return Yennu's Toy Boat", description = "<This hand made toy boat resembles the ships of the Tuskarr. Yennu, the young Tuskarr, was musing about a boat, it must belong to him>", objectives = "" }
WordHunterWoW_QuestEN[72067] = { title = "Relaxation Time!", description = "You there! \n\nYou look exhausted. Worn down. In extreme need of some R&R. I have just the thing! The Serene Dreams Spa is the place for you!\n\nEnjoy our new you-ga classes, they are AMAZING! Or perhaps a mud mask facial treatment is more your speed? I recommend both!\n\nTo get to the spa, head north just out of the city!", objectives = "" }
WordHunterWoW_QuestEN[72068] = { title = "Aiding the Accord: A Feast For All", description = "Our allies require your aid, {name}!\n\nYour efforts throughout the Isles have not gone unnoticed. Our trusted allies to the south, the Iskaara Tuskarr, seek to celebrate your accomplishments with a feast of all feasts!\n\nJourney to the lands of Iskaara whilst continuing your work alongside the allies of the Accord. When you reach the shimmering waters of the southern lands do not hesitate to participate in the celebrations!", objectives = "" }
WordHunterWoW_QuestEN[72069] = { title = "Subglacial Refill", description = "The fish could be biting better, don't you think?\n\nYou know, that gives me an idea. Seems we have caught almost all the fish under the ice. Could you catch some more from the Timbertooth Trail downstream, bring it here, and drop it into an ice hole?", objectives = "" }
WordHunterWoW_QuestEN[72071] = { title = "Round Two, Fish!", description = "How do you feel about doing a little fishing, then, {name}?\n\nThere's a school of bait fish just offshore that the dumb beast attacks whenever they gather, forgetting that it's already dead.\n\nSwim out there and wave that lure around, maybe do your best impression of a wounded seal, and it won't be able to resist.", objectives = "" }
WordHunterWoW_QuestEN[72072] = { title = "Dragonsprings Drop", description = "The fish could be biting better, don't you think?\n\nYou know, that gives me an idea. Legend says these lakes and rivers did not always have fish. They say, these watering holes were stocked with fish when the dragons soaring overhead dropped them! Can you believe it?\n\nMaybe you and your drake could give it a try?", objectives = "" }
WordHunterWoW_QuestEN[72074] = { title = "Highland Habitat", description = "The fish could be biting better, don't you think?\n\nYou know, that gives me an idea. Legend says these lakes and rivers did not always have fish. They say, these watering holes were stocked with fish when the dragons soaring overhead dropped them! Can you believe it?\n\nMaybe you and your drake could give it a try?", objectives = "" }
WordHunterWoW_QuestEN[72075] = { title = "Hot Stock", description = "The fish could be biting better, don't you think?\n\nYou know, that gives me an idea. Legend says these lava lakes are not always abundant with hot-loving fish. They say, pools were stocked with fish when the dragons soaring overhead dropped them! Can you believe it?\n\nMaybe you and your drake could give it a try?", objectives = "" }
WordHunterWoW_QuestEN[72083] = { title = "Me Lucky Lure", description = "Ya find me in a low place, {race}, and it's not because I'm dead.\n\nI died on the hunt, making sure the beast that killed me crew wouldn't live to kill again. There's nothing wrong with that, it's what me Pa would have wanted.\n\nNo, the problem is that the fight was a draw!\n\nThe beast's spirit is still out there, as sure as I stand here before ya. But, being a ghost, I can't even reclaim me lucky lure from the critters that picked me body clean to have another go!\n\nWould ya mind helping me out?", objectives = "" }
WordHunterWoW_QuestEN[72113] = { title = "Shapes Beyond the Veil", description = "", objectives = "" }
WordHunterWoW_QuestEN[72117] = { title = "Cultural Exchange", description = "", objectives = "" }
WordHunterWoW_QuestEN[72122] = { title = "Erstwhile Ecologists", description = "The wounded are stabilized, but something still troubles me, {name}.\n\nA pair of dragonspawn ecologists had come to the outpost to study the wetlands. I haven't seen scale nor claw of them since the attack, and it's become worrisome.\n\nIf you're venturing out, would you mind keeping an eye out, and making sure they're safe?\n\nAnd do take care. Rumor has it those wetlands are gorloc-infested.", objectives = "" }
WordHunterWoW_QuestEN[72129] = { title = "Aiding Khadgar", description = "Welcome to Dalaran, {name}. I'm glad you made it through safely.\n\nSpeak to me within the Violet Citadel. There's much to do.", objectives = "" }
WordHunterWoW_QuestEN[72134] = { title = "An Adventurer's Aid", description = "We've discovered that there are many issues around the land which we float above, the Broken Isles.\n\nWe'll do what we can from here. I want you to look at the nearby map to see who you can aid first.", objectives = "" }
WordHunterWoW_QuestEN[72135] = { title = "Neltharus: Secrets Within", description = "We have a problem, traveler. The djaradin first emerged from within Neltharus, which means they must be ransacking the halls! \n\nNeltharus contains many treasures. But more importantly, it contains knowledge: the history of our flight and its fall from grace. Both Sabellian and Wrathion have been looking for more information regarding Neltharion's life and work.\n\nGo! See what you can recover before the djaradin plunder it all!", objectives = "" }
WordHunterWoW_QuestEN[72137] = { title = "Hatchling Plans", description = "", objectives = "" }
WordHunterWoW_QuestEN[72155] = { title = "Spread the Enchantment", description = "Algeth'ar Academy has put in an order for more enchanting rods. We need everyone to pitch in if we are going to fill the order on time. Could you be of assistance?", objectives = "" }
WordHunterWoW_QuestEN[72156] = { title = "A Fiery Flight", description = "The forge is cooling! Quick, can you help me? Bring me some Rousing Fire. Perhaps it will help!", objectives = "" }
WordHunterWoW_QuestEN[72157] = { title = "The Weight of Earth", description = "I have an order for several hundred tons of Primal Molten Alloy, but I have run out of Rousing Earth. I know it's a heavy ask, but I can make it worth your while!", objectives = "" }
WordHunterWoW_QuestEN[72158] = { title = "A Dense Delivery", description = "Our scales are tough, but we can always use more protection. Only the densest of hides will do for our armor--a challenge to gather, but perhaps one you are up to?\n\nI've seen your skills. Go and gather some hides for our stores.", objectives = "" }
WordHunterWoW_QuestEN[72159] = { title = "Scaling Down", description = "Scales have a multitude of purposes--they offer protection, but in some cases, they also offer a keen reflective surface. Many of our finest mirrors are in fact scales.\n\nThose mirrors also happen to be in high demand. Gather some scaled hides for me, and I'll share some of my crafting secrets.", objectives = "" }
WordHunterWoW_QuestEN[72172] = { title = "Essence, Shards, and Chromatic Dust", description = "We seem to be in constant need of basic components. Essence, shards... and our stock of Chromatic Dust is almost always depleted.\n\nIf you wouldn't mind helping us stock up, perhaps we can make it more than a day into the week without needing to replenish our supply.", objectives = "" }
WordHunterWoW_QuestEN[72173] = { title = "Braced for Enchantment", description = "The Dragonscale Expedition has requested some enchantments for their gear.\n\nThe Dragon Isles can be a treacherous place. I don't blame them for needing some bracer upgrades.", objectives = "" }
WordHunterWoW_QuestEN[72175] = { title = "A Scept-acular Time", description = "There are some exciting orders to fill this week! The students at Algeth'ar Academy have been going horns over heels for these fun scepters.\n\nWhy don't you assist with some of the scepters?", objectives = "" }
WordHunterWoW_QuestEN[72189] = { title = "Garden Variety", description = "Are you enjoying the butterfly garden?\n\nYou know, there's a much larger garden just to the south of here. An older drakonid by the name of Gryrmpech tends to it.\n\nHe could always use an extra pair of hands. He has an 'assistant', but I've never actually seen him. I can't imagine he's of much help.\n\nIf you stop by, be sure to let him know that Xina sent you.", objectives = "" }
WordHunterWoW_QuestEN[72190] = { title = "Reservoir Reservations", description = "{class}! I know someone who is in dire need of your skills.\n\nTyrhold Reservoir has just been attacked by Primalists. I was lucky to make my escape when I did. I fear the others may not be so lucky.\n\nIt's just to the north of here. Find Zuttiki, she'll be able to fill you in on the details.\n\nIf she's still alive, that is.", objectives = "" }
WordHunterWoW_QuestEN[72191] = { title = "Short-Supply Reward", description = "", objectives = "" }
WordHunterWoW_QuestEN[72192] = { title = "Halls of Infusion: Entropy to Order", description = "The Primalists wish to bring elemental chaos back to this world and will stop at nothing to see their goal accomplished.\n\nI have received disturbing news that they have infiltrated the Halls of Infusion deep below Tyrhold. They attempt to disrupt the works of Keeper Tyr for their own nefarious purposes.\n\nPlease, you must put an end to any Primalist threat within those sacred halls, {name}.", objectives = "" }
WordHunterWoW_QuestEN[72193] = { title = "The Algeth'ar Academy", description = "I understand that the Algeth'ar Academy is open to the world once more. \n\nLong ago, its sacred halls were only open to dragons, but in the years that have passed the Headteacher has seen the wisdom of welcoming any who wish to learn. She has asked for my recommendation on any promising new students. \n\nAs a great ally to dragonkind, it would be an honor to have you attend our great academy. I leave the decision to enroll up to you, but I am sure Doragosa would love to at least give you a tour.", objectives = "" }
WordHunterWoW_QuestEN[72240] = { title = "The Obsidian Warders", description = "This Toddy's enthusiasm is admirable. But I hope it does not blind her to the dangers awaiting us in the Dragon Isles.\n\nRegardless, the Obsidian Warders are duty-bound to protect the expedition.\n\nI must speak with Wrathion and the Lord Commander about the mission ahead.\n\nMy fellow dracthyr are exploring the city. Seek out Dervishian, my trusted lieutenant, and inform her that we are to rally at the docks. She will relay my orders to the rest.", objectives = "" }
WordHunterWoW_QuestEN[72241] = { title = "Lessons From Our Past", description = "I am Emberthal, a scalecommander of the dracthyr. Wrathion aided us after we awakened from our long stasis, and now it is my turn to help him.\n\nNo doubt you have questions about my people and our history. Until recently, I did as well. \n\nBut Nozdormu, the Timeless One, has revealed lost truths about the dracthyr. He granted me a vision of our origins... and why we were locked away. \n\nLet me tell you of the things I have seen.", objectives = "" }
WordHunterWoW_QuestEN[72242] = { title = "Dragon Isles Engineering", description = "", objectives = "" }
WordHunterWoW_QuestEN[72243] = { title = "Dragon Isles Herbalism", description = "", objectives = "" }
WordHunterWoW_QuestEN[72244] = { title = "Dragon Isles Inscription", description = "", objectives = "" }
WordHunterWoW_QuestEN[72245] = { title = "Dragon Isles Alchemy", description = "", objectives = "" }
WordHunterWoW_QuestEN[72246] = { title = "Serene Dreams", description = "Welcome to the Serene Dreams Spa!\n\nI must apologize. We are not able to admit new guests at this time due to circumstances beyond our control.\n\nLet me refer you to the Spa Manager, Xijan Thornpaw. He is qualified to answer all your questions.", objectives = "" }
WordHunterWoW_QuestEN[72247] = { title = "Dragon Isles Jewelcrafting", description = "", objectives = "" }
WordHunterWoW_QuestEN[72249] = { title = "Dragon Isles Tailoring", description = "", objectives = "" }
WordHunterWoW_QuestEN[72250] = { title = "Dragon Isles Cooking", description = "", objectives = "" }
WordHunterWoW_QuestEN[72251] = { title = "Dragon Isles Cooking", description = "", objectives = "" }
WordHunterWoW_QuestEN[72252] = { title = "Dragon Isles Fishing", description = "", objectives = "" }
WordHunterWoW_QuestEN[72253] = { title = "Dragon Isles Fishing", description = "", objectives = "" }
WordHunterWoW_QuestEN[72256] = { title = "The Dark Talons", description = "Naleidea is enthusiastic, but she's a historian, not a soldier. She knows nothing of the dangers we'll face in the Dragon Isles.\n\nNot that anyone needs to worry. After all, the Dark Talons will be protecting the expedition.\n\nI'm going to discuss mission logistics with Ebyssian and your Horde leaders.\n\nMy lieutenant, Kodethi, is exploring the city along with the other dracthyr. Be a good soldier and let him know we are going to rally at the zeppelin tower. He'll relay my orders to the others.", objectives = "" }
WordHunterWoW_QuestEN[72261] = { title = "More Than a Prison?", description = "<The ancient artifact appears elemental in nature. Lillian Brightmoon in Valdrakken might be able to tell more.>", objectives = "" }
WordHunterWoW_QuestEN[72263] = { title = "Cavalry Has Its Place", description = "Evoker! This place still has herds of vorquin!\n\nI managed to round a few up that could be used as mounts for when your wings are tired. Remember how to ride?\n\nThis one is to be issued to you as the scalecommanders are ordering you all over the place. Please take good care of it.", objectives = "" }
WordHunterWoW_QuestEN[72266] = { title = "The Waking Shores", description = "The drakonid Sendrax is looking for help in aiding all of the newcomers within the Waking Shores.", objectives = "" }
WordHunterWoW_QuestEN[72267] = { title = "Ohn'ahran Plains", description = "The green dragonflight needs the aid of adventurers. To do so, you must ally with the centaur of the plains.\n\nAmbassador Taurasza can be of aid.", objectives = "" }
WordHunterWoW_QuestEN[72268] = { title = "Azure Span", description = "The Kirin Tor need all the help they can get tracking down the Blue Dragon Oathstone.\n\nSome of their mages have been spotted in the Ohn'ahran Plains looking for help.", objectives = "" }
WordHunterWoW_QuestEN[72269] = { title = "Thaldraszus", description = "Alexstrasza the Life-Binder is arranging a meeting of the Seat of the Aspects to discuss the threat of the Primalists.\n\nShe has put out a call for any willing adventurers to come help.", objectives = "" }
WordHunterWoW_QuestEN[72291] = { title = "Story of a Memorable Victory", description = "That was a good fight! \n\nElder Poa in Iskaara will be interested in listening to the story of that victory.", objectives = "" }
WordHunterWoW_QuestEN[72292] = { title = "Story of a Spectacular Victory", description = "That was a majestic fight!\n\nElder Poa in Iskaara will be interested in listening to the story of that impressive victory.", objectives = "" }
WordHunterWoW_QuestEN[72293] = { title = "Adventuring in the Dragon Isles", description = "Oh, I know what you can do!\n\nThe Dragonscale Expedition has posted a very fine looking map of the Dragon Isles nearby. \n\nTheir drawings are quite accurate and detailed, if I do say so myself. Sorry, you're not here for an art review.\n\nYou should go check it out to see what areas of the Dragon Isles could use your help!", objectives = "" }
