WordHunterWoW_QuestEN[72338] = { title = "Greater Obsidian Key", description = "Bring me an assembled Key", objectives = "" }
WordHunterWoW_QuestEN[72339] = { title = "Engine of Innovation", description = "Tyr believed that the Engine of Innovation would be necessary for the battles to come. \n\nYou have proven yourself worthy and overcome all the challenges set before you. You may now unlock Engine's full potential.", objectives = "" }
WordHunterWoW_QuestEN[72354] = { title = "The Great Vault", description = "Over the years, the Aspects and their kin acquired many remarkable artifacts and armaments. The Aspects ordered the construction of an enchanted vault where they could be stored for safe-keeping until such a time as a worthy soul came in search of that which lay within.\n\nYou will find this Great Vault within the walls of the bank. Perhaps, if you prove your mettle, it will grant you a piece of the Aspects' ancient hoard.", objectives = "" }
WordHunterWoW_QuestEN[72363] = { title = "Good at Doings, Not Understandings", description = "", objectives = "" }
WordHunterWoW_QuestEN[72365] = { title = "[test] Learn to spend talent points", description = "", objectives = "" }
WordHunterWoW_QuestEN[72372] = { title = "Taming the Dragon...kin", description = "", objectives = "" }
WordHunterWoW_QuestEN[72373] = { title = "Aiding the Accord: The Hunt is On", description = "Our allies from the Ohn'ahran Plains have sent word-a request-for any and all who hunt these lands to lend their aid to their cause.\n\nWhilst continuing your efforts across these Isles, pay a visit to our allies at one of their hunting camps and assist in their efforts.\n\nThere is much to be done. Best not delay.", objectives = "" }
WordHunterWoW_QuestEN[72374] = { title = "Aiding the Accord: Dragonbane Keep", description = "Our allies once again seek your assistance as our efforts continue across the Isles. Words within the walls of Valdrakken whisper a resounding comfort knowing your efforts have helped shape our future.\n\nNow then, to business.\n\nA lingering djaradin threat moves upon the Waking Shores deep within the smoldering inferno of Dragonbane Keep. We must move to disrupt their advances.\n\nWe await your return, {name}.", objectives = "" }
WordHunterWoW_QuestEN[72375] = { title = "Aiding the Accord: The Isles Call", description = "Your actions have not gone unnoticed.\n\nAcross the Isles, our allies seek to ensure the safety of all who venture throughout these lands. There are, however, some who would seek to end your... work, as it impedes in their plans.\n\nDo what you must to ensure our allies are protected.", objectives = "" }
WordHunterWoW_QuestEN[72380] = { title = "Together We Are Unstoppable", description = "{name}, you must tell Alexstrasza and Nozdormu what has happened.\n\nKhadgar and I will meet you at the Seat of the Aspects momentarily.", objectives = "" }
WordHunterWoW_QuestEN[72384] = { title = "Valdrakken Tour", description = "Fly through the checkpoint rings marking the course.", objectives = "" }
WordHunterWoW_QuestEN[72392] = { title = "Dragon Isles Supplies", description = "", objectives = "" }
WordHunterWoW_QuestEN[72396] = { title = "Horns of Plenty", description = "Many of our inventions rely on using a sturdy and springy material. Fortunately, vorquin horns have served as the perfect product for many of our modern creations.\n\nEven more fortunate for us, the Dragon Isles are swarmed with vorquin. It should be a simple task for you to gather some springy horns from the vorquin for us.", objectives = "" }
WordHunterWoW_QuestEN[72397] = { title = "Orientation: Dragonscale Basecamp", description = "Welcome to basecamp, {name}.\n\nIt took Toddy and me awhile to settle on the perfect site to establish camp, but I couldn't be happier with our selection.\n\nEasy access to ruins, proto-dragon breeding grounds, and of course the dragonflights.\n\nWhy not take a few minutes to explore the camp and meet some of the suppliers helping to fuel the expedition?", objectives = "" }
WordHunterWoW_QuestEN[72398] = { title = "Rock and Stone", description = "Earth elementals in the Dragon Isles are composed of various rocks and minerals. Our blacksmiths are thoroughly fascinated with the unique tools they are able to manufacture from smelting such materials. In fact, they appear to have smelted the last of their samples.\n\nI would hate to ruin their fun. Would you mind replenishing the supply?", objectives = "" }
WordHunterWoW_QuestEN[72399] = { title = "The Hermit's Garden", description = "Our parents always say we shouldn't visit the gardens above Gelikyr. They think the gardener is mean and dangerous. \n\nThat's not true, though! They're a bit grumpy, but they're really nice! \n\nNone of us have been up there since the Primalists showed up. It's way too dangerous now. Still, I hope the gardener is okay. Could you go and check on them, since we can't visit anymore?", objectives = "" }
WordHunterWoW_QuestEN[72405] = { title = "An Unlikely Informant", description = "This is a top secret mission, {name}.\n\nWe've had a break in.\n\nA powerful historical artifact was stolen from the Keep... and it looks like the Defias Brotherhood is to blame. We caught one thief, but the other got away.\n\nBut I don't like it, {name}... my gut tells me there's more. \n\nI've called in a... specialist on the Brotherhood. Meet us in the basement of the Lion's Pride Inn in Goldshire.", objectives = "" }
WordHunterWoW_QuestEN[72406] = { title = "Orientation: Valdrakken", description = "Welcome to Valdrakken, {name}. I am Unatos, Keeper of Renown for the Valdrakken Accord.\n\nIn recognition of your assistance to the dragonflights, a number of suppliers around the city have been authorized to supply you with some of our finest wares.\n\nWhy not take some time to familiarize yourself with their locations and wares?", objectives = "" }
WordHunterWoW_QuestEN[72407] = { title = "Soaked in Success", description = "Fishermen of our tribe are constantly plagued with waterlogged packs and boots. Lately, the riverbeasts have been swarming fishing spots and causing even more mayhem.\n\nThe hide of the riverbeasts are quite slick and water-resistant. Perhaps we can handle two problems at once. If you could help handle the over abundance of riverbeasts and bring back their hides, our fishers would be quite pleased.", objectives = "" }
WordHunterWoW_QuestEN[72408] = { title = "A Window to the Past", description = "In this, I trust Vanessa's word. I do not believe she knows what the Drakefire Amulet is. Some of the story about Onyxia was made public, but not all.\n\nPerhaps even you do not know. \n\nI will explain everything, for both of you.", objectives = "" }
WordHunterWoW_QuestEN[72409] = { title = "Rotten Old Memories", description = "Whatever is going on, I don't like it. Last thing we need is this dragon lady's power corrupting everyone again. \n\nWhoever did this must have known much about Onyxia. Shaw mentioned this... Reginald Windsor. He was the only one to suspect Lady Prestor. Well, maybe his friends in the Burning Steppes have more of his information. \n\nShe must have had allies. Anything that points us to people close to her would help. \n\nCheck it out, will you?", objectives = "" }
WordHunterWoW_QuestEN[72410] = { title = "Pincers and Needles", description = "We've been running low on needles for tailoring lately. Those darn things keep snapping in two!\n\nSome pointy parts from the scythid in the area might serve as good replacements.", objectives = "" }
WordHunterWoW_QuestEN[72411] = { title = "Cause Without a Rebel", description = "Good to see you again, {name}! Alexstrasza doesn't think we can stop the rebels effectively through force, despite the successes you've had.\n\nTo find other ways forward, Alexstrasza has called Maldra Flametongue here to talk about the rebellion and what drew her to it.\n\nPerhaps it would be helpful to join the conversation, and see what Maldra has to say. To avoid prying rebel eyes and ears, they will be meeting below us, on the second level of the Seat of the Aspects.", objectives = "" }
WordHunterWoW_QuestEN[72412] = { title = "Explosive Interruption", description = "I managed to infiltrate a rebel camp, down in Scalewatch Cavern. It seemed like any other camp, except for frequent wagons coming into camp with their contents covered.\n\nEventually, I was able to discreetly make my way to where the wagons would be unloaded. The rebels are stockpiling bombs, but it's even worse!\n\nThey're piling the bombs against a pillar directly underneath the aqueduct from Tyrhold.\n\nMeet me down there, and we'll find a way to stop this!", objectives = "" }
WordHunterWoW_QuestEN[72413] = { title = "Irreconcilable Differences", description = "I wish we never had to raise arms against fellow dragonkin, {name}. We should be allies, not enemies. Unfortunately, their leader, Agitator Zoralek, made the choice for us when he threatened the aqueduct.\n\nFight your way inside the cave, and put a stop to Agitator Zoralek by any means necessary, before he can set off those bombs. Then bring back his detonator so we can secure it. Once we have that, the Scalesworn will be able to remove the bombs safely.", objectives = "" }
WordHunterWoW_QuestEN[72414] = { title = "Know Prisoners!", description = "If Alexstrasza truly wants to find the causes of this rebellion, we need to hear out the rebels.\n   \nTo do that, we have to safely detain rebels who want to kill us. Well, you. That's much harder than resorting to violence, and more dangerous as well.\n\nBut I've experienced this when I left the rebels. Orian Darkwater cast a spell to bind me totally. It worked, and I paid close attention.\n\nI've imbued that spell into a ring. You can use it to bind them safely. It should work, anyway!", objectives = "" }
WordHunterWoW_QuestEN[72415] = { title = "Rebel Rousing Writings", description = "The rebels seem to have a lot of signs and flyers around the cave. They probably use it as a way to keep everyone aligned to their purpose, and motivated to fight.\n\nIt's hard to keep a large group united around a cause - especially if you use detestable methods like bombing civilians or destroying a water source - without a steady stream of reinforcement.\n\nLet's get a bunch of their propaganda. It may tell us a lot about what they're thinking, or who's telling them what to think.", objectives = "" }
WordHunterWoW_QuestEN[72416] = { title = "Temporary Accommodations", description = "We've been sending the rebel prisoners to Steelcliff Rampart. It's the barracks where Valdrakken's city guard, the Scalesworn, are based.\n\nSo there are plenty of guards to keep them from causing harm or escaping.\n\nHead over there and we'll see what the next steps are in putting a permanent stop to this rebellion.", objectives = "" }
WordHunterWoW_QuestEN[72417] = { title = "Persistent Dissidents", description = "My goal is to see this rebellion brought to an end, with as little violence as possible. To do that, I need to understand the root causes of this rebellion.\n\nThe rebels have clearly come to resent the Aspects and the dragonflights. And while we had to use force to protect Valdrakken, that hasn't brought about an end to the rebellion.\n\nI'd like you to speak to the prisoners, and ask why they rebelled. I'll accompany you to hear their reasons.", objectives = "" }
WordHunterWoW_QuestEN[72418] = { title = "Solicited Opinions", description = "That was enlightening, to say the least. The rebels we talked to had a lot to say which I wouldn't have anticipated.\n\nI have my thoughts on the situation, but what did you think of their grievances?\n\nAs neither a dragon nor dragonkin, you bring a certain objectivity to the matter.", objectives = "" }
WordHunterWoW_QuestEN[72419] = { title = "Cleaning up the Cliffraff", description = "{name}! Maldra has been going through the propaganda you retrieved, using ciphers she knew from her days as a rebel.\n\nShe found a coded message that led her to another rebel camp, where Belaphon is stirring up rebellion among anyone she can.\n\nMaldra and Inspector Erima are already there - go join them and let's see if we can finally put a stop to this rebellion!", objectives = "" }
WordHunterWoW_QuestEN[72420] = { title = "Wreckonciliation", description = "Captain Drine informed me that Alexstrasza wants this done as peacefully as possible. And I've heard Alexstrasza is considering granting the Dragonkin more rights. Or even freedom.\n\nInstead of fighting our way through all these rebels when peace may be on the horizon, let's spread the word! Tell the dragonkin here that things are changing. Perhaps some will lay down their arms or choose to leave.\n\nBut be prepared to deal with those who insist on fighting.", objectives = "" }
WordHunterWoW_QuestEN[72421] = { title = "The Quill to Power", description = "{name}, we need to stop the quills from inciting the rebels long enough for us to be heard. \n\nTheir leader, Belaphon, seems to be giving the quills a degree of autonomy with that glowing staff. Gather up as many as you can, so they can't keep reproducing her words.\n\nOnce they're out of commission, we'll confront her directly - but we don't want the quills to scatter and continue spreading these messages.", objectives = "" }
WordHunterWoW_QuestEN[72422] = { title = "Stop the Presses", description = "This is it, {name}. As the one propagating the ideas that drive the rebellion, if we can stop Belaphon, we'll see the end of the rebellion.\n\nTry to bind her with my ring, though you'll likely need to weaken her first. If she's willing to surrender, we'll bring her to Alexstrasza.\n\nI imagine the Queen of Dragons will have a lot of very choice words when they meet.", objectives = "" }
WordHunterWoW_QuestEN[72423] = { title = "Weathering the Storm", description = "Ah, you have arrived just in time! We've heard tales that the Nokhud centaur have powerful, dangerous weaponry infused with storm enchantments. We would like to bring some samples to our enchanters for study.\n\nAt the very least, we can decommission the weapons and put them to better use.", objectives = "" }
WordHunterWoW_QuestEN[72424] = { title = "Looking for Something Specific", description = "<Ragged John blinks blearily up at you.> \n\nSo ye took down that ol' worg, didye? Well aren't ye the biggest strongest human I seen since ol' Windsor. \n\n<Ragged John sighs.>\n\n...Well? What're ye still doing here? Go take what ye found to whoever sent ye here in the first place!", objectives = "" }
WordHunterWoW_QuestEN[72426] = { title = "The New Clessington Estate", description = "Excellent, {name}. Finally, something we can work with. \n\nCount Clessington is a member of the House of Nobles and a powerful mage. He has fallen on hard times since Anduin cracked down on corruption in Stormwind.\n\nI would not put it past him to have something to do with this.\n\nHe recently purchased an old manor in Duskwood. I will contact my sources and see what other information I can find. You and Vanessa should go to the manor and investigate.", objectives = "" }
WordHunterWoW_QuestEN[72427] = { title = "Animated Infusion", description = "I have a simple request for you today.\n\nThe alchemists are short on an ingredient used in a particularly tricky brew. The herb is easy enough to retrieve. You'll just need to find some aggressive plants to extract samples from. Think you can handle that?", objectives = "" }
WordHunterWoW_QuestEN[72428] = { title = "Hornswog Hoarders", description = "It's no secret that the hornswogs in these lands have a fascination for gems, jewels, and all things shiny. Why, even the other day I found a very rare jewel in some hornswog droppings!\n\nWell, it might not be the most appealing task, but it seems the hornswog have a habit of not only collecting, but also consuming valuables.", objectives = "" }
WordHunterWoW_QuestEN[72429] = { title = "Orientation: Maruukai", description = "<As Sansok Khan signs, Okir vocalizes for her.>\n\nThe Maruuk as a people are not staunchly against outsiders, but we do require any potential allies to prove their worth. As you meet the clans and aid in our ventures, word will spread of your support.\n\nOn the lower level of the krutal on the hill you will find one of the Khanam Matra's daughters, who can help you see where you stand with our people. Be sure to introduce yourself.", objectives = "" }
WordHunterWoW_QuestEN[72430] = { title = "Misdeeds in Moonbrook", description = "Moonbrook? What is this Count Clessington doing at my home?!\n\nIt can't be anything good. I'll signal Shaw.\n\n<Vanessa glances at Cecilia Clessington.>\n\nShe might make for a good hostage. Let's bring the rich girl, too.\n\nMeet us there.", objectives = "" }
WordHunterWoW_QuestEN[72431] = { title = "A Hungry Heritage", description = "It's been a while since I've been home. \n\nSomething isn't right. My people should be here. \n\nI'm going in... but I won't turn down some back up. \n\n... I never should've left for so long.", objectives = "" }
WordHunterWoW_QuestEN[72432] = { title = "Supply Only the Finest Goons", description = "These \"attendants\" of my father's attacked us the moment we arrived!\n\nThese are certainly not the kindly servants I had as a child. These are hired killers!\n\nIf my father is planning what I think he's planning... we can't let them do this. They will kill everyone in their way.\n\n<Cecilia winces.>\n\nIf it's kill or be killed...", objectives = "" }
WordHunterWoW_QuestEN[72434] = { title = "Ruby Lifeshrine Loop", description = "They say I'm not big enough to fly some of these courses yet. \n\nBut I can still watch others do it. You should race! Then I can watch you race.", objectives = "" }
WordHunterWoW_QuestEN[72435] = { title = "Orientation: Iskaara", description = "Welcome to Iskaara, friend.\n\nWord of your exploits in Brackenhide has already spread among our people. You have already met many of us, and there are more who would like the chance to exchange knowledge and wares with you.\n\nPlease, take a moment to familiarize yourself with some of the friendly faces around Iskaara. We are a community that supports one another, so just as you have much to offer us, many of our people have much to offer you in return.", objectives = "" }
WordHunterWoW_QuestEN[72438] = { title = "Tarasek Intentions", description = "When the tarasek accepted power from the Primalists, they stole many ancient scrolls and tomes to combine with their newfound magic. We need help getting these scrolls back in our possession.", objectives = "" }
WordHunterWoW_QuestEN[72440] = { title = "Silver Mettle", description = "I believe the Silver Scale may still be of some use to us. During my observations, I felt an... energy in it that transcends time and seems to be attuned to Tyr. It also has the same architecture as the disc.\n\nIt stands to reason we may use the Silver Scale to collect one of Tyr's memories that he did not commit to the disc.\n\nThough it seems macabre, going to his tomb in Tirisfal may allow us to at least partially restore him.\n\nAlexstrasza can tell you more, {name}.", objectives = "" }
WordHunterWoW_QuestEN[72441] = { title = "Breaching the Tomb", description = "Something recently activated the tomb's titan defense system. I had not seen titan constructs here before.\n\nI was investigating why they appeared when I was locked out of the tomb. Perhaps your mission awakened them.\n\nShould we intend to venture forth, we must disarm the new defenses. The glowing orbs flanking the doors might be the key. If only they weren't damaged...", objectives = "" }
WordHunterWoW_QuestEN[72442] = { title = "The Remains of Tyr", description = "As Nozdormu could sense power lingering in the scale, I can sense Tyr here. It is in the very stones of this place.\n\nI suspect the other constructs can sense it as well. They must have come here when Tyr was reforged. We must be on the right track.\n\nIf something of his presence still remains, the scale should be able to gather it--with the help of this console. But the constructs may interpret our collection of Tyr's last memories as us trying to destroy them. \n\nKeep them away if they awaken.", objectives = "" }
WordHunterWoW_QuestEN[72443] = { title = "Tyr's Fall", description = "This console will allow us to examine the scale's contents, but I do not know what we will find. \n\nThe other titan servants here should leave us alone; accessing it should not be as disruptive as transferring what we sensed of Tyr. \n\nSomething is making Travard uneasy. Be prepared for anything, {name}.\n\nPlace the Silver Scale in the console when you are ready to proceed.", objectives = "" }
WordHunterWoW_QuestEN[72444] = { title = "A Sliver of Silver", description = "Tyr's final memories are in our hands. This is not a responsibility to be taken lightly.\n\nLet us take the Silver Scale to Nozdormu in Tyrhold. We will attempt to use the console there to awaken him. \n\nIf he is whole again, there will be much to discuss.", objectives = "" }
WordHunterWoW_QuestEN[72445] = { title = "To Northshire", description = "Vanessa's care for her people deserves better than a brotherhood of bandits. I am glad to see them part ways. \n\nAnd as spymaster, I'm in no small part relieved.\n\nNow, Northshire. Peasants can become heroes, there. Perhaps your own journey began in that abbey?\n\nIt's also a strong, defensible position to attack Stormwind from. We cannot let it fall!\n\nHurry, to Northshire!", objectives = "" }
WordHunterWoW_QuestEN[72446] = { title = "What's Their Problem?", description = "Good to see you again, recruit. Wish it were in better circumstances.\n\nWhatever this \"influence\" is, anybody with half a grudge now thinks it's worth spilling blood over!\n\nNot to mention all the Defias bandits! And the hired thugs! At this rate, more soldiers from Stormwind will only create more confusion.\n\nFrom what I've seen, you can knock the sense back into most of these people. If they keep fighting you after their eyes have cleared... do what you must. They have made their choice.", objectives = "" }
WordHunterWoW_QuestEN[72447] = { title = "Greatest of Threats", description = "Powerful djaradin and other creatures threaten both the Obsidian Citadel and the safety of my flight. \n\nThis cannot stand.\n\nHelp secure the area. Seek out and eliminate two of our most powerful enemies.", objectives = "" }
WordHunterWoW_QuestEN[72448] = { title = "Securing Our Legacy", description = "I have not worked this hard and come this far to lose the Citadel now! \n\nUnfortunately, new threats have emerged. Can I count on your assistance to deal with them? \n\nHelp secure the area. Seek out and eliminate two of our most powerful enemies.", objectives = "" }
WordHunterWoW_QuestEN[72449] = { title = "Knock It Off!", description = "We're too late, {name}. \n\nClessington has holed himself up inside the abbey and is spreading the chaotic influence of the amulet all over Northshire! \n\nI don't think most of the people here know the difference between friend and foe, anymore.\n\nThis man seems like the type to have a backup plan. Those agents must have a way to get past Clessington's barrier. Take them out and look for anything useful!", objectives = "" }
WordHunterWoW_QuestEN[72450] = { title = "The Clessington Will", description = "I'm no great mage like my father, but I do know a few of his tricks. \n\nI saw those signets you got off the enforcers. My father's private chambers were locked by a similar magical trinket, which can be broken apart into pieces. \n\nLet me put those signets back together into an arcane key. That should get us past the barrier.\n\nThen... I can only hope we can talk some sense into him.", objectives = "" }
WordHunterWoW_QuestEN[72451] = { title = "Will to Survive", description = "... So it is done. \n\nI would have liked to have questioned the man more. But the power was too much for him. \n\nWe cannot allow the amulet to end up in anyone else's hands. Claim it, {name}, and we shall ensure its safe return to Stormwind, together.", objectives = "" }
WordHunterWoW_QuestEN[72452] = { title = "Go with Honor, Friend", description = "This mission ended up being far more than any of us expected, {name}, and you did very well. I shudder to think of what would have happened without you here. \n\nSome time back, the King commissioned a set of armor be made. Armor to adorn our greatest heroes. \n\nYou have proven yourself more than deserving of such honor.\n\nMeet me in the Valley of Heroes, {name}.", objectives = "" }
WordHunterWoW_QuestEN[72453] = { title = "Betrayal of the Brotherhood", description = "I should have known. I lost control of the Brotherhood the moment those pardons were offered. Anyone with principle is long gone. \n\nIt's only the brutes left, now. And Duncon Ratsbon was always the biggest brute of them all.\n\nLet's get out of here, {name}. If any of these fools try to get in our way, let's teach them a lesson about standing in the path of a VanCleef.", objectives = "" }
WordHunterWoW_QuestEN[72454] = { title = "The Obsidian Hatchling", description = "An egg from the black dragonflight is ready to hatch.\n\nReport to Mother Elion in the Ruby Lifeshrine to pick up the egg. Then, I request that you bring the egg to the Obsidian Oathstone to hatch in a location strong with their flight's power.\n\nOnce this is complete, return here with the hatchling, where we will further take care of it.", objectives = "" }
WordHunterWoW_QuestEN[72455] = { title = "Warmth and Comfort", description = "In order for the obsidian hatchling to be comfortable, we must build them a proper nest.\n\nYou will need to build their nest from Obsidian Citadel coal to make sure it is warm and suitable. Secondly, Archivist Edress will be able to assist you in finding something that ties them to their people.\n\nWe will want to gather something from Zaralek Cavern as well, as much of their flight's history is rooted there. Surely somebody in Loamm can help.", objectives = "" }
WordHunterWoW_QuestEN[72456] = { title = "Tomes Of Trust", description = "Despite securing the upper ramparts of the Obsidian Citadel, the djaradin forces continue to pillage the courtyard. The area is full of priceless historical records! We must act quickly to secure anything that documents the lineage of the black dragonflight.\n\nBoth Wrathion and Sabellian desire this information, so you can curry favor by procuring a tome for each of them.\n\nTravel to the collapsed tower of the citadel. You should find something worth recovering.", objectives = "" }
WordHunterWoW_QuestEN[72457] = { title = "A Home-Cooked Meal", description = "Black dragon whelps need to grow up to be big and strong. Our hatchling here seems quite small, so I believe she will require something hearty and nutritious to help her along her way.\n\nRoast duck is not only good for your stamina, but also your brain. I think it would be the perfect meal for our young hatchling.", objectives = "" }
WordHunterWoW_QuestEN[72458] = { title = "Tag, You're Anxious", description = "Every whelp needs some playtime to get out their energy. Our new obsidian friend is no exception.\n\nThe hatchlings love playing a good game of tag. See if she would like to play with you!", objectives = "" }
WordHunterWoW_QuestEN[72459] = { title = "What's a Duck?", description = "I will be honest with you, {name}.\n\nIt has been such a long time since we dealt with the black dragonflight that I could not quite tell you much about them. I do know that they are strong warriors, brave protectors of us all.\n\nRusziona is still quite young, but perhaps we should see how well she does with battle? Take her to practice on some ducks in the Ohn'ahran Plains. Let us see her baseline.", objectives = "" }
WordHunterWoW_QuestEN[72460] = { title = "A Solid Pet", description = "I worry about Ruszi. She is incredibly nervous and insecure, and she jumps at nearly anything! I have never heard of a black dragon so terrified of the world.\n\nI believe the best way for us to build her confidence is to find her a companion. Something sturdy and strong that does not move quickly or suddenly.\n\nThe black dragonflight's charge is the protection of earth. Perhaps a small elemental will suit her well.\n\nSpeak to Lysindra at the pet shop in Valdrakken. She should have something suitable.", objectives = "" }
WordHunterWoW_QuestEN[72461] = { title = "Anatidaephobia", description = "The time has come, {name}. Her new pet Iggy has been doing wonders for Rusziona's confidence, and now I think she's ready to face her biggest fear.\n\nDucks.\n\nThere is a tauren in the Waking Shores who is an expert at using pets to help heal trauma. I think she might be just what we need.\n\nLasztak and Rusziona will meet you there.", objectives = "" }
WordHunterWoW_QuestEN[72462] = { title = "A People in Need of Healing", description = "It is strange, {name}. Despite the years of peace, I am restless. Despite having the Horde and my son, I am lonely. You feel the same, don't you? I see it in your eyes, and in the eyes of many orcs.\n\nI feel perhaps that while we have found our way on Azeroth, we have lost our way as orcs.\n\nCome with me. I wish to speak with an old friend about these troubles, and I would like you by my side.", objectives = "" }
WordHunterWoW_QuestEN[72463] = { title = "Galgar's Cactus Apple Surprise...", description = "<The young orc's last words were a request to deliver these Cactus Apples to Galgar.\n\nWill you honor her request?>", objectives = "" }
WordHunterWoW_QuestEN[72464] = { title = "The Kosh'harg", description = "The Kosh'harg will be held in Razor Hill. Go'el and Eitrigg are gathering the clans as we speak.\n\nWe will have to part ways for now. You must begin mentally preparing yourself for the om'gora--the rite of honor. It is my task to make sure it is a worthy challenge, even for you.\n\nI will call our wind riders to carry my family to the Kosh'harg. You may travel with them, or meet us there.", objectives = "" }
WordHunterWoW_QuestEN[72465] = { title = "The Blessing of the Land", description = "To earn the blessing of the land, a young orc must learn respect for the spirits that dwell alongside us. If we do not live in balance with the elements and life around us, it can lead to calamity.\n\nI will call to the spirits, and they will guide us to where your aid is needed. It is up to you to complete the task before you.", objectives = "" }
WordHunterWoW_QuestEN[72466] = { title = "The Spirit of Thunder Ridge", description = "Life can only thrive when a delicate balance is maintained. The arrival of your people and the humans was but the first link in the chain that led to desolation.\n\nYou yourself are not to blame, but you can be the force that restores what once was.\n\nDive into the waters below and recover the seeds buried in the silt. They are a memory of the ancient forest that once grew in harmony with my people.\n\nBeware, the elements are not at peace here.", objectives = "" }
WordHunterWoW_QuestEN[72467] = { title = "The Blessing of the Clan", description = "To earn the blessing of the clan, a young orc must learn that the clan is only as strong as its members. Prove your strength, and worth, to the living orcs.\n\nSince you were not born into a clan, you must first choose a clan to champion, and be accepted by the clan's chieftain.\n\nThe chieftains have gathered in the barracks. Join a clan, and complete the task given to you.", objectives = "" }
WordHunterWoW_QuestEN[72474] = { title = "Tracking a Killer", description = "Gor'krosh, the Long Knives, has been terrorizing the Valley of Trials for weeks. Orcs have been going missing, and many of our young trainees have been injured.\n\nThe peons took to calling the mysterious attacker the Long Knives because the few bodies we have found all have long, terrible gashes across their backs. They're terrified, and refusing to work!\n\nWe have no idea who or what Gor'krosh really is, but they are clearly very dangerous. Please, find this monster and end this madness!", objectives = "" }
WordHunterWoW_QuestEN[72475] = { title = "Cornering Gor'krosh", description = "If Gor'krosh is a truly a raptor, you should be able to track it down just like any other animal.\n\nSee if you can find its trail. We know it's been around here recently. Corner it in its lair and end this once and for all!\n\nMake sure you return to Razor Hill straight away once you make the kill. The Farseer will need proof of the deed.\n\nThank you, {name}. May the spirits guide your blade. Lok-tar!", objectives = "" }
WordHunterWoW_QuestEN[72476] = { title = "The Blessing of the Ancestors", description = "The blessing of the ancestors is meant to teach young orcs that the living owe everything to those that came before. We must honor the ancestors, seek their wisdom, and live up to their expectations.\n\nYour task is to craft an offering worthy of the honored dead, and worthy of being the centerpiece at the offering stone of the first Kosh'harg of Azeroth! You must put all of your energy into its construction, or it will not be enough.\n\nCook Torka will guide you. The ancestors will be watching.", objectives = "" }
WordHunterWoW_QuestEN[72477] = { title = "Orcish Groceries", description = "In here is a recipe for the traditional feast left for the ancestors at the Kosh'harg by the clans. We're going to have to substitute some ingredients that, you know, no longer exist... \n\nBut it will for the better! We'll bring some Azeroth flair to this traditional dish!\n\nI will teach you each piece of the recipe, but it will be up to you to gather the ingredients and actually cook it. Orc traders have come from all over, so you should be able to find everything you need right here in Razor Hill.", objectives = "" }
WordHunterWoW_QuestEN[72478] = { title = "Honor and Glory", description = "You have successfully completed the om'gora! Congratulations, {name}.\n\nNow it is time for us to celebrate! We have prepared a feast for all in attendance, in your honor!\n\nGo, revel in the glory you have earned. Enjoy yourself. If any of these orcs get out of line, remind them why you were the one who was chosen to complete the new rite first!", objectives = "" }
WordHunterWoW_QuestEN[72479] = { title = "Aka'magosh", description = "The Kosh'harg has been a great success, in no small part thanks to you, {name}.\n\nAll that is left is for Aggra to perform the ceremony to bring the festival to an official close.\n\nI wish to speak to the crowd before we all disperse again, on some things long overdue in being said.", objectives = "" }
WordHunterWoW_QuestEN[72481] = { title = "The Waking Shores Tour", description = "And what is the most fun about dragonriding? Races! \n\nMy bronze colleagues have mapped out race courses all over the Dragon Isles. It is such a varied and dynamic landscape that it just begs to be explored at top speed.\n\nIf you find yourself near one of our race courses in The Waking Shores, why not give it a go?", objectives = "" }
WordHunterWoW_QuestEN[72482] = { title = "The Waking Shores Advanced Tour", description = "Now that you've flown the basic courses all over the Dragon Isles and proved your ability, how about a new challenge?\n\nThe advanced race courses are similar to the standard courses you have flown, but many have adjusted flight paths or extra obstacles to test your skill.\n\nLet us start with the courses in the Waking Shores!", objectives = "" }
WordHunterWoW_QuestEN[72483] = { title = "The Ohn'ahran Plains Tour", description = "Ah, the Ohn'ahran Plains. Wide open spaces, gusting winds, endless vistas... and more race courses!\n\nJust as in the Waking Shores, if you find any of my bronze colleagues, speak to them about their race course.", objectives = "" }
WordHunterWoW_QuestEN[72484] = { title = "The Ohn'ahran Plains Advanced Tour", description = "The advanced courses should be more challenging, but I am sure it is nothing you cannot handle!\n\nMy bronze colleagues have set up advanced courses in the Ohn'ahran Plains that have a few obstacles and surprises thrown in them. You can also compete against your own best times!\n\nGood luck!", objectives = "" }
WordHunterWoW_QuestEN[72485] = { title = "The Azure Span Tour", description = "Azure Span courses are a unique experience. Their high peaks, snowy terrain, and dense forest present plenty of interesting obstacles--and challenges!\n\nWhile you are there, seek out my bronze colleagues and give their courses a try!", objectives = "" }
WordHunterWoW_QuestEN[72486] = { title = "The Azure Span Advanced Tour", description = "The advanced courses in the Azure Span are designed to elevate your dragon riding skills to new heights! \n\nJust... make sure you don't fall from them!\n\nWhen you're ready, seek out my bronze colleagues and fly those courses!", objectives = "" }
WordHunterWoW_QuestEN[72487] = { title = "The Thaldraszus Tour", description = "Thaldraszus. It is the home of the Seat of the Aspects and much of dragonkind's history. \n\nIt is also home to soaring heights and steep deep ravines just waiting to be flown over!\n\nAs before, my bronze colleagues have set up race courses in Thaldraszus to fly while you explore. \n\nWhy not give them a try and complete your Dragon Isles racing tour?", objectives = "" }
WordHunterWoW_QuestEN[72488] = { title = "The Thaldraszus Advanced Tour", description = "Once more to Thaldraszus with its peaks and valleys and courses ready and waiting for you to race!\n\nSeek out my bronze colleagues to fly the advanced courses and finish your racing tour of the Dragon Isles!", objectives = "" }
WordHunterWoW_QuestEN[72512] = { title = "A Whispering Breeze", description = "<Godoloto cocks her head quizzically, nods at you, and finally holds your gaze. After a long moment, she casts her eyes up towards the sky... and the mountain just beside Maruukai. You sense that she wants you to travel up to Ohn'ahra's Roost.>", objectives = "" }
WordHunterWoW_QuestEN[72513] = { title = "Our Destiny", description = "Evoker! You might have felt a disturbance just recently.\n\nEbyssian and I have begun to unbind the ancient siphons that were extracting the black dragonflight essence from dracthyr. I suspect that only the fully trained evokers like yourself are tuned enough to feel the change.\n\nThere is more, though. Please, come join Ebyssian and myself at the High Creche in the Forbidden Reach. We have a dragon to unchain.", objectives = "" }
WordHunterWoW_QuestEN[72514] = { title = "The High Creche", description = "Have you felt it?\n\nWe have already started bringing the barrier down. This prison for Adamanthia held so much power.\n\nAnd now I can augment again! A fully trained evoker was always intended to empower their allies, as much as healing or devastation. I remember that now... and more.\n\nI am starting to remember who this imprisoned black dragon was... who she was to all dracthyr.\n\nPlease, {name}, help me remove these shackles.", objectives = "" }
WordHunterWoW_QuestEN[72515] = { title = "Augmenting a Dragon", description = "Adamanthia!\n\nShe has been imprisoned for ages, trapped in torment. While the dracthyr slept, she suffered.\n\nI can only hope she has not given in to Deathwing's madness during her long imprisonment. The passage of time may have shattered her mind.\n\nBe ready, champion. Should she lash out, aid Ebyssian. Augment his abilities, so he can subdue Adamanthia instead of slaying her.\n\nShe has earned a chance. We must give it to her.", objectives = "" }
WordHunterWoW_QuestEN[72519] = { title = "Temporal Two-ning", description = "I see... They are falling through possibilities as well as time.\n\nHurry, I have located another point in the timeline where we might catch them. It is... unusual, but do not let the strangeness of this world slow you down. Chronormu's fate is in your hands.", objectives = "" }
WordHunterWoW_QuestEN[72524] = { title = "Basic Climbing Gear", description = "<Pathfinder Jeb motions to the supply kit next to him.>\n\nYou're going to need supplies to survive out there.\n\nLet's get you what you need to start climbing.", objectives = "" }
WordHunterWoW_QuestEN[72525] = { title = "Basic Cataloging Gear", description = "Every expedition cataloger deserves their very own camera!\n\nYou don't need to give yours a special name, but I highly encourage it. It's far more fun.\n\nAnyway, Pathfinder Jeb should be able to get you everything you need.\n\nI've yet to need a single thing that he hasn't brought along with him. He's incredible!", objectives = "" }
WordHunterWoW_QuestEN[72526] = { title = "Keeper's Rest", description = "I do not enjoy seeing others forged by Tyr disabled. They went through such effort to keep the tomb from collapsing, and now it will languish devoid of even what was left of Tyr's light.\n\n<Koranos gestures to the Silver Scale.>\n\nI hope whatever is in the scale is worth their destruction. Let us find another console to see what, if anything, is on the scale.", objectives = "" }
WordHunterWoW_QuestEN[72527] = { title = "No Such Thing as Bad Luck", description = "Look, believe it or not, I'd be in the Isles already if it wasn't for unfinished business. Recent events have not been kind to me. I owe the Baron, and nobody owes the Baron for long. He will absolutely find and skin me if I don't pay up.\n\nI invested his money in these magic crystals, but their price just crashed on the market because of the front page ripper in the Booty Bay Journal. And the shipment of crystals is missing!\n\nSomeone must be plotting my demise. Perhaps the Goodstitches will help me.", objectives = "" }
WordHunterWoW_QuestEN[72529] = { title = "Information is King", description = "Information ain't cheap. Outta everyone, Zeros should know that best.\n\nPeople have sighted dangerous crocolisks around Janeiro's Point. You know what I see? Money, money, money! Get me their precious skins and maybe I'll remember something important about those crystals Zeros is after.\n\nIf that's too dangerous for your cup of tea, I might be open to other forms of payment too. You know, the most common form.\n\n<Blixrez folds his arms and waits expectantly.>", objectives = "" }
WordHunterWoW_QuestEN[72530] = { title = "Anyway, I Started Bribing", description = "The scoundrel! I had a deal with Arty to market the crystals in the paper. Someone must've cut a bigger deal with him.\n\nArty routinely inspects the Venture Company's working area on the shore. He always brings his own guards, but no one is immune to gold in Booty Bay.\n\nTake my last bit of gold. Go to the oil rigs and bribe the guards to look the other way before you confront Arty.", objectives = "" }
WordHunterWoW_QuestEN[72532] = { title = "Money, Money, Money!", description = "Grub Redcut and his crew are notorious for their love of money. They'll do anything for it.\n\nI assume there is treasure to be had on his own ship, but just in case there isn't, there must be gold within their pockets. Will you do me the dirty business of collecting it?\n\nI won't question your negotiation tactics--just don't kill them! I'm not trying to start a serious blood feud today.", objectives = "" }
WordHunterWoW_QuestEN[72533] = { title = "Crystals Shmystals", description = "Grub. Redcut. <Zeros spits.> A sore, crusty loser, who thinks he's all tough because he's big and buff. He hates that someone like me can make more money than him.\n\nBelieve it or not, I play the auction house fairly. I'm a saint compared to him!\n\nSo Grub sold my crystals, eh? And then paid Arty to lie about them so no one would go looking for them. A fine plan.\n\nGrub must have something valuable on that ship of his. Well we're going to go take it. Search the ship thoroughly.", objectives = "" }
WordHunterWoW_QuestEN[72534] = { title = "Settled with the Baron", description = "Ha...! You returned just in time. A minute later and you might've found a skinned dragon on your hands.\n\nGive him the treasure, quickly.", objectives = "" }
WordHunterWoW_QuestEN[72539] = { title = "Dragonflight (60-69) E", description = "", objectives = "" }
WordHunterWoW_QuestEN[72544] = { title = "Dragonflight (70) E", description = "", objectives = "" }
WordHunterWoW_QuestEN[72545] = { title = "Creche Fallen", description = "This is my failure, {name}. \n\nI led these dracthyr here. They knew death was a possibility, but they also trusted me to be there for them.\n\nI should have been down there, clearing the ruins, not up here trawling through books. \n\n<Emberthal balls her fists.>\n\nI need you to retrieve their horn signets. We need to give them honors.", objectives = "" }
WordHunterWoW_QuestEN[72546] = { title = "Academic Assistance", description = "{name}! I've made a breakthrough with tha Winterpelt dialect. Ya helped get tha ball rollin' on this, so I felt like I ought ta keep ya apprised of the situation.\n\nMeet me in Theron's Watch and I'll tell ya all about it.", objectives = "" }
WordHunterWoW_QuestEN[72547] = { title = "Academic Acquisitions", description = "I'll head up tae the village an' give 'em the bad news--or try. Winterpelt's a right tricky dialect tae learn.\n\nI need ye tae get out there an' find me some furbolg writin' samples tae study if we ever hope tae communicate properly.\n\nThe Primalists've wiped out or converted most o' the remainin' furbolg in the Span, so go shake 'em down until whate'er cultural artifacts they have drop out.\n\nI'll need at least five tae start, but bring me as many as ye can, and I'll keep teachin' ye what I learn.", objectives = "" }
WordHunterWoW_QuestEN[72550] = { title = "Dragonflight (60-69) E", description = "", objectives = "" }
WordHunterWoW_QuestEN[72551] = { title = "A Living History", description = "The Winterpelt finally trust us enough to ask for aid.\n\nWe must nurture this trust so we may one day clasp their paws in friendship!\n\nThis Winterpelt, Jyrra of the, uh, Fuzzy Feet, says their elders went into hiding during the Primalist attack on their village. I don't yet understand their language, but it seems the elders left markers to help the clan find them later.\n\nIt's time to let the Winterpelt elders know it's safe to come home. Will you convey this message? It seems a simple enough task.", objectives = "" }
WordHunterWoW_QuestEN[72552] = { title = "Gathering Together", description = "I haven't heard an outsider speak 303-our tongue. Your 303-grasp is a bit basic...\n\nBut only a friend of the clan would speak it at all!\n\n303-I am Elder Mhaz. If it is safe to return home, we should set off soon. But many of us are weak with sadness of the heart--and grumbling of the stomach. I would not put you at risk gathering fresh meat, but could you gather roots for us? \n\nWe have already gathered ones that are close. I hope this comfort food will lift our spirits enough to return!", objectives = "" }
WordHunterWoW_QuestEN[72553] = { title = "More Effort, More Reward", description = "We're not sad. We're starving. 303-That's the truth of it. A few tasty roots won't 303-be enough.\n\nElder Mhaz doesn't recognize strength, but I do. It should be 303(100)-trivial for you to bring us some fresh meat! The 303-worms to the east should be easy prey.\n\nPlease, bring back 303-what you can carry!", objectives = "" }
WordHunterWoW_QuestEN[72554] = { title = "Break Him", description = "You handled those little worms with such ease!\n\nHowever... Saza hasn't come back. The giant worm, Icebreaker, has been hunting us for 303-weeks. It took two of our elders while we gathered food 303-and injured me when I tried to avenge them. And now, with Saza missing, I fear the worst.\n\nFind Saza, and get rid of that worm!", objectives = "" }
WordHunterWoW_QuestEN[72557] = { title = "Dragonflight (70) E", description = "", objectives = "" }
WordHunterWoW_QuestEN[72558] = { title = "Our Honored Ancestors", description = "It is time to take the next step to understanding the Winterpelt. That step is a spiritual one. \n\nThey look to their ancestors for advice as they choose their path forward. We can learn from them too.\n\nBut the Winterpelt rite to call their ancestors is... intricate. And long. \n\nIt would be rude to copy their ritual anyway. We'll do it our way with Rustpine Spiritspeaker incense.\n\nCome! Let us reveal their ancestors' wisdom and learn more about our new friends!", objectives = "" }
WordHunterWoW_QuestEN[72559] = { title = "History Heist", description = "When the Primalists raided our village, they took more than our lives; they stole the heart 303-of our community--our priceless historical documents! \n\nI will not stand for records of our traditions, 303-rituals, and rich history taken from us! We still have lessons to learn from them.\n\nPlease, recover them from those looting Primalist scouts 303-so they can be preserved!", objectives = "" }
WordHunterWoW_QuestEN[72567] = { title = "Dragonflight (70) E", description = "", objectives = "" }
WordHunterWoW_QuestEN[72572] = { title = "Dragonflight (70) E", description = "", objectives = "" }
WordHunterWoW_QuestEN[72575] = { title = "Dragonflight (70) E", description = "", objectives = "" }
WordHunterWoW_QuestEN[72580] = { title = "Dragonflight (70) E", description = "", objectives = "" }
WordHunterWoW_QuestEN[72583] = { title = "Dragonflight (70) E", description = "", objectives = "" }
